--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


--
-- Name: _irrigation_solar_calc(numeric, uuid, text, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._irrigation_solar_calc(p_hp numeric, p_panel_product_id uuid, p_structure_type text, p_toggles jsonb, p_discount_pct numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s public.irrigation_bom_settings;
  v_panel record;
  v_panel_discount_pct numeric;
  v_panel_cost_basis numeric;   -- تكلفتنا (بعد خصم المورد) — داخلي بس
  v_panel_list_price numeric;   -- سعر الموقع الكامل — ده اللي العميل بيشوفه
  v_inv record;
  v_inv_discount_pct numeric;
  v_inv_cost_basis numeric;
  v_inv_list_price numeric;
  v_comb record;
  v_comb_discount_pct numeric;
  v_comb_cost_basis numeric;
  v_comb_list_price numeric;
  v_comb_capacity int;
  panels_per_string int;
  arrays int;
  total_panels int;
  calc_kw numeric;
  efficiency_ratio numeric;
  v_iimp numeric; v_vimp numeric; v_voc numeric; v_isc numeric; v_isc_calc numeric;
  inverter_calc_kw numeric;
  inverter_oversize_warning text;
  reactor_model int;
  cb_size int;
  combiner_need int;
  panel_cost numeric; panel_sell numeric;
  steel_panel_cost numeric;
  cable_raw numeric; rounded_hundreds numeric; hundreds_unit numeric; even_unit numeric; cables_len int; cables_cost numeric;
  mc4_cost numeric;
  structure_price numeric; structure_cost numeric; structure_sell numeric;
  concrete_qty int; concrete_cost numeric;
  earth_qty int; earth_cost numeric; earth_sell numeric;
  reactor_price numeric;
  reactor_cost numeric; reactor_sell numeric;
  mech_install_cost numeric; elec_install_cost numeric;
  transport_qty int; transport_cost numeric;
  factor numeric;
  cables_sell numeric; mc4_sell numeric; ip65_sell numeric;
  install_lump_sell numeric; install_lump_cost numeric;
  rows jsonb := '[]'::jsonb;
  sell_total numeric := 0;
  final_total numeric;
  r_cables numeric; r_earth numeric; r_reactor numeric; r_install numeric;
begin
  if not (is_rep() or is_admin()) then raise exception 'not authorized'; end if;
  if p_hp is null or p_hp <= 0 then return jsonb_build_object('error', 'invalid_hp'); end if;

  select * into s from public.irrigation_bom_settings where id = 1;

  -- الألواح
  select id, name_ar, brand, category, price, power_watt, vimp, voc, iimp, isc
    into v_panel
    from public.products
    where id = p_panel_product_id and category = 'panels' and published = true
      and power_watt is not null and vimp is not null and voc is not null
      and iimp is not null and isc is not null;
  if v_panel.id is null then return jsonb_build_object('error', 'panel_not_found'); end if;

  select supplier_discount_pct into v_panel_discount_pct
    from public.supplier_discounts where category = v_panel.category and brand = v_panel.brand;
  v_panel_list_price := coalesce(v_panel.price, 0);
  v_panel_cost_basis := v_panel_list_price * (1 - coalesce(v_panel_discount_pct, 0) / 100.0);

  panels_per_string := floor(s.max_string_voltage / v_panel.vimp) - s.panels_per_string_adjust;
  if panels_per_string < 1 then return jsonb_build_object('error', 'panel_voltage_too_high'); end if;
  arrays := round(p_hp * 1000 * s.hp_capacity_ratio / (panels_per_string * v_panel.power_watt)) - s.strings_adjust;
  if arrays < 1 then arrays := 1; end if;
  total_panels := panels_per_string * arrays;
  calc_kw := v_panel.power_watt * total_panels / 1000.0;
  efficiency_ratio := calc_kw / p_hp;

  v_iimp := arrays * v_panel.iimp;
  v_vimp := panels_per_string * v_panel.vimp;
  v_voc  := panels_per_string * v_panel.voc;
  v_isc  := arrays * v_panel.isc;
  v_isc_calc := v_isc * 1.25;

  -- الإنفرتر
  inverter_calc_kw := ceil(p_hp * 0.8) + s.inverter_power_increase;
  select id, name_ar, brand, category, price, power_kw, max_solar_input_kw
    into v_inv
    from public.products
    where category = 'inverters' and published = true
      and power_kw is not null and max_solar_input_kw is not null
      and power_kw >= inverter_calc_kw
    order by power_kw asc limit 1;
  if v_inv.id is null then
    select id, name_ar, brand, category, price, power_kw, max_solar_input_kw
      into v_inv
      from public.products
      where category = 'inverters' and published = true
        and power_kw is not null and max_solar_input_kw is not null
      order by power_kw desc limit 1;
    if v_inv.id is null then return jsonb_build_object('error', 'no_inverter_available'); end if;
    inverter_oversize_warning := format('مفيش إنفرتر بقدرة %s كيلوواط أو أعلى بيانات كاملة — تم اختيار أعلى قدرة متاحة (%s كيلوواط)، راجع يدويًا.', inverter_calc_kw, v_inv.power_kw);
  end if;
  if calc_kw > v_inv.max_solar_input_kw then
    inverter_oversize_warning := coalesce(inverter_oversize_warning || ' ', '') || format('⚠️ قدرة الألواح المحسوبة (%.1f كيلوواط) تتجاوز أقصى ما يتحمله إنفرتر %s كيلوواط (الحد الأقصى %s كيلوواط) — راجع الاختيار يدويًا.', calc_kw, v_inv.power_kw, v_inv.max_solar_input_kw);
  end if;

  select supplier_discount_pct into v_inv_discount_pct
    from public.supplier_discounts where category = v_inv.category and brand = v_inv.brand;
  v_inv_list_price := coalesce(v_inv.price, 0);
  v_inv_cost_basis := v_inv_list_price * (1 - coalesce(v_inv_discount_pct, 0) / 100.0);

  select min(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x where x::numeric >= v_iimp;
  if reactor_model is null then select max(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x; end if;
  reactor_price := (s.reactor_prices ->> reactor_model::text)::numeric;

  select min(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x where x::numeric >= v_isc_calc;
  if cb_size is null then select max(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x; end if;

  -- صندوق التجميع (Combiner) — بيتسحب من المنتجات الفعلية (فئة combiners)
  -- السعة مستخرجة من اسم المنتج "صندوق جمع N Arrays ..."
  combiner_need := greatest(ceil(arrays * s.combiner_headroom)::int, arrays + s.combiner_min_spare_strings);
  select id, name_ar, brand, category, price,
         (regexp_match(name_ar, '(\d+)\s*Arrays'))[1]::int as capacity
    into v_comb
    from public.products
    where category = 'combiners' and published = true
      and (regexp_match(name_ar, '(\d+)\s*Arrays'))[1]::int >= combiner_need
    order by (regexp_match(name_ar, '(\d+)\s*Arrays'))[1]::int asc
    limit 1;
  if v_comb.id is null then
    select id, name_ar, brand, category, price,
           (regexp_match(name_ar, '(\d+)\s*Arrays'))[1]::int as capacity
      into v_comb
      from public.products
      where category = 'combiners' and published = true
      order by (regexp_match(name_ar, '(\d+)\s*Arrays'))[1]::int desc
      limit 1;
  end if;
  if v_comb.id is null then
    return jsonb_build_object('error', 'no_combiner_available');
  end if;
  v_comb_capacity := v_comb.capacity;
  select supplier_discount_pct into v_comb_discount_pct
    from public.supplier_discounts where category = v_comb.category and brand = v_comb.brand;
  v_comb_list_price := coalesce(v_comb.price, 0);
  v_comb_cost_basis := v_comb_list_price * (1 - coalesce(v_comb_discount_pct, 0) / 100.0);

  -- سعر العميل = سعر الموقع الكامل دايمًا (مؤكد)، هامش الربح = الفرق بينه وبين التكلفة بعد خصم المورد
  panel_cost := v_panel_cost_basis * calc_kw * 1000;
  panel_sell := v_panel_list_price * calc_kw * 1000;

  steel_panel_cost := s.steel_panel_per_hp * p_hp;
  ip65_sell := steel_panel_cost * (1 + s.ip65_markup_pct/100.0);

  structure_price := case when upper(p_structure_type) = 'ROTATIONAL' then s.structure_price_rotational else s.structure_price_fixed end;
  structure_cost := arrays * structure_price;
  structure_sell := structure_cost * (1 + s.structure_markup_pct/100.0);

  cable_raw := case when calc_kw >= 100 then s.cable_high_multiplier * arrays else s.cable_low_multiplier * arrays end;
  rounded_hundreds := round(cable_raw / 100.0) * 100;
  hundreds_unit := rounded_hundreds / 100;
  even_unit := case when mod(hundreds_unit::int, 2) = 0 then hundreds_unit when hundreds_unit > 0 then hundreds_unit + 1 else hundreds_unit - 1 end;
  cables_len := round(even_unit * 100)::int;
  cables_cost := cables_len * s.cable_per_meter;
  cables_sell := cables_cost * s.cable_markup;

  mc4_cost := arrays * s.mc4_per_unit;
  mc4_sell := mc4_cost * (1 + s.mc4_markup_pct/100.0);

  concrete_qty := round(arrays * 8 / 3.5);
  concrete_cost := concrete_qty * s.concrete_per_unit;

  earth_qty := round(calc_kw / 40);
  earth_cost := earth_qty * s.earthing_per_unit;
  earth_sell := earth_cost * (1 + s.concrete_markup_pct/100.0);

  reactor_cost := reactor_price;
  reactor_sell := reactor_cost * (1 + s.reactor_markup_pct/100.0);

  mech_install_cost := total_panels * s.mech_install_per_panel;
  elec_install_cost := total_panels * s.elec_install_per_panel;
  transport_qty := ceil(calc_kw / 20);
  transport_cost := greatest(transport_qty * s.transport_per_trip, s.transport_minimum);

  -- البند السابع المدموج: combiner بقى بسعر الموقع الحقيقي (مش سعر افتراضي + هامش يدوي)
  install_lump_cost := v_comb_cost_basis + mc4_cost + steel_panel_cost + mech_install_cost + elec_install_cost + transport_cost + concrete_cost;
  install_lump_sell := v_comb_list_price + mc4_sell + ip65_sell + mech_install_cost + elec_install_cost + transport_cost + (concrete_cost * (1+s.concrete_markup_pct/100.0));

  factor := greatest(0, least(4, coalesce(p_discount_pct, 0))) / 100.0;

  -- خصم المندوب الإضافي (0-4%) بيتطبق على هامش الربح فقط، بعد ما اتصلح السعر الأساسي
  r_cables  := (cables_sell - cables_cost) * factor;
  r_earth   := (earth_sell - earth_cost) * factor;
  r_reactor := (reactor_sell - reactor_cost) * factor;
  r_install := (install_lump_sell - install_lump_cost) * factor;

  rows := jsonb_build_array(
    jsonb_build_object('n',1,'name','الواح الطاقة الشمسية','type', v_panel.brand || ' ' || v_panel.power_watt || 'W',
      'qty', case when (p_toggles->>'panel')::boolean then format('%s لوح (%s × %s)', total_panels, arrays, panels_per_string) else 'لا يوجد' end,
      'origin','الصين','warranty','30 سنة ضد انخفاض الإنتاجية عن 87.40% / 12 سنة ضد عيوب الصناعة',
      'net', case when (p_toggles->>'panel')::boolean then round(panel_sell) else 0 end,
      'cost_note', jsonb_build_object('sell', round(panel_sell), 'cost', round(panel_cost))),
    jsonb_build_object('n',2,'name','الشاسية','type', case when upper(p_structure_type)='ROTATIONAL' then 'متحرك صينية - كمر سيجال - دهان ايبوكسي' else 'ثابت مجلفن تثبيت مسامير' end,
      'qty', case when (p_toggles->>'structure')::boolean then format('%s KW', round(calc_kw,1)) else 'لا يوجد' end,
      'origin','مصر','warranty','خمس سنوات',
      'net', case when (p_toggles->>'structure')::boolean then round(structure_sell - (structure_sell-structure_cost)*factor) else 0 end,
      'cost_note', jsonb_build_object('sell', round(structure_sell), 'cost', round(structure_cost))),
    jsonb_build_object('n',3,'name','الانفرتر','type', v_inv.brand || ' ' || v_inv.power_kw || ' KW',
      'qty', case when (p_toggles->>'inverter')::boolean then '1' else 'لا يوجد' end,
      'origin','الصين','warranty','سنتان',
      'net', case when (p_toggles->>'inverter')::boolean then round(v_inv_list_price) else 0 end,
      'cost_note', jsonb_build_object('sell', round(v_inv_list_price), 'cost', round(v_inv_cost_basis))),
    jsonb_build_object('n',4,'name','الكابلات','type','HIS / LEADER / KBE',
      'qty', case when (p_toggles->>'cables')::boolean then format('يحدد في الموقع - بحد أقصى %s متر', cables_len) else 'لا يوجد' end,
      'origin','ألمانيا / الصين','warranty','سنة واحدة',
      'net', case when (p_toggles->>'cables')::boolean then round(cables_sell - r_cables) else 0 end,
      'cost_note', jsonb_build_object('sell', round(cables_sell), 'cost', round(cables_cost))),
    jsonb_build_object('n',5,'name','التأريض / بئر أرضي','type','-',
      'qty', case when (p_toggles->>'earth')::boolean then 'يحدد في الموقع' else 'لا يوجد' end,
      'origin','مصر','warranty','----',
      'net', case when (p_toggles->>'earth')::boolean then round(earth_sell - r_earth) else 0 end,
      'cost_note', jsonb_build_object('sell', round(earth_sell), 'cost', round(earth_cost))),
    jsonb_build_object('n',6,'name','الريأكتور (VFD Reactor)','type', reactor_model || ' A',
      'qty', case when (p_toggles->>'reactor')::boolean then '1' else 'لا يوجد' end,
      'origin','مصر','warranty','سنة واحدة',
      'net', case when (p_toggles->>'reactor')::boolean then round(reactor_sell - r_reactor) else 0 end,
      'cost_note', jsonb_build_object('sell', round(reactor_sell), 'cost', round(reactor_cost))),
    jsonb_build_object('n',7,'name','التوريد والنقل والتركيب وعمالة ولوحة الحماية IP65 والاكسسوارات والمواسير','type', format('Combiner %s: %s', v_comb_capacity, v_comb.brand),
      'qty', format('%s KW', round(calc_kw)),
      'origin','مصر / الصين','warranty','----',
      'net', round(install_lump_sell - r_install),
      'cost_note', jsonb_build_object(
        'sell', round(install_lump_sell), 'cost', round(install_lump_cost),
        'breakdown', jsonb_build_object(
          'combiner', round(v_comb_list_price), 'mc4', round(mc4_sell), 'ip65', round(ip65_sell),
          'install_mech', round(mech_install_cost), 'install_elec', round(elec_install_cost),
          'transport', round(transport_cost), 'concrete', round(concrete_cost * (1+s.concrete_markup_pct/100.0))
        )))
  );

  select coalesce(sum((r->>'net')::numeric),0) into sell_total from jsonb_array_elements(rows) r;
  final_total := sell_total;

  return jsonb_build_object(
    'panels_per_string', panels_per_string, 'arrays', arrays, 'total_panels', total_panels,
    'calc_kw', round(calc_kw,1), 'efficiency_ratio', round(efficiency_ratio,3),
    'vimp', round(v_vimp,1), 'voc', round(v_voc,1), 'iimp', round(v_iimp,1), 'isc', round(v_isc,1), 'isc_calc', round(v_isc_calc,1),
    'inverter_brand', v_inv.brand, 'inverter_kw', v_inv.power_kw, 'inverter_oversize_warning', inverter_oversize_warning,
    'reactor_model', reactor_model, 'cb_size', cb_size, 'combiner_capacity', v_comb_capacity,
    'rows', rows, 'final_total', round(final_total),
    'payment_terms', jsonb_build_array(
      jsonb_build_object('label','مقدم عند التعاقد','pct',70,'amount', round(final_total*0.70)),
      jsonb_build_object('label','عند التوريد','pct',25,'amount', round(final_total*0.25)),
      jsonb_build_object('label','عند التشغيل','pct',5,'amount', round(final_total*0.05))
    )
  );
end;
$$;


--
-- Name: enforce_max_calc_featured_panels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_max_calc_featured_panels() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.calc_featured = true and new.category = 'panels' then
    if (
      select count(*) from public.products
      where category = 'panels'
        and calc_featured = true
        and id <> coalesce(new.id, '00000000-0000-0000-0000-000000000000'::uuid)
    ) >= 3 then
      raise exception 'لا يمكن اختيار أكثر من 3 ألواح لحاسبة تكاليف الري (max 3 calc_featured panels)';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.admin_users
    WHERE lower(email) = lower(coalesce(auth.jwt() ->> 'email', ''))
  );
$$;


--
-- Name: is_rep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_rep() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.reps
    where id = auth.uid() and active = true
  );
$$;


--
-- Name: preview_irrigation_solar_quote(numeric, uuid, text, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_irrigation_solar_quote(p_hp numeric, p_panel_product_id uuid, p_structure_type text DEFAULT 'FIXED'::text, p_toggles jsonb DEFAULT '{"mc4": true, "ip65": true, "earth": true, "panel": true, "cables": true, "reactor": true, "combiner": true, "concrete": true, "inverter": true, "structure": true, "transport": true, "install_elec": true, "install_mech": true}'::jsonb, p_discount_pct numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (is_rep() or is_admin()) then raise exception 'not authorized'; end if;
  return public._irrigation_solar_calc(p_hp, p_panel_product_id, p_structure_type, p_toggles, p_discount_pct);
end;
$$;


--
-- Name: rep_clear_quote_draft(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rep_clear_quote_draft() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from quote_drafts where rep_id = auth.uid();
end;
$$;


--
-- Name: rep_create_irrigation_quote(text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rep_create_irrigation_quote(p_customer_name text, p_customer_phone text, p_customer_city text, p_quote_type text, p_items jsonb, p_notes text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rep_id uuid := auth.uid();
  v_customer_id bigint;
  v_quote_id bigint;
  v_item jsonb;
  v_result_items jsonb := '[]'::jsonb;
  v_subtotal_customer numeric := 0;
  v_subtotal_cost numeric := 0;
  v_discount_pct numeric;
  v_supplier_discount_pct numeric;
  v_qty numeric;
  v_customer_unit numeric;
  v_cost_unit numeric;
  v_line_customer numeric;
  v_line_cost numeric;
  v_prod record;
  v_bom record;
  v_bom_cost record;
begin
  if not (is_rep() or is_admin()) then
    raise exception 'not authorized';
  end if;
  if p_quote_type not in ('supply_only','supply_install') then
    raise exception 'invalid quote_type';
  end if;
  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then
    raise exception 'invalid phone';
  end if;

  select * into v_bom from public.offgrid_bom_settings where id = 1;
  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_qty := coalesce((v_item->>'qty')::numeric, 0);
    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));
    if v_qty <= 0 then
      continue;
    end if;

    if v_item->>'type' = 'product' then
      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod
        from public.products p
        where p.id = (v_item->>'product_id')::uuid and p.published = true
          and p.category in ('well_motors','pumps','pipes');
      if v_prod.id is null then
        raise exception 'product not found, not published, or not a well category: %', v_item->>'product_id';
      end if;
      v_customer_unit := coalesce(v_prod.price, 0);
      select supplier_discount_pct into v_supplier_discount_pct
        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;
      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);

      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);
      v_line_cost := v_qty * v_cost_unit;

      v_result_items := v_result_items || jsonb_build_object(
        'label', coalesce(v_item->>'label', v_prod.name_ar),
        'qty', v_qty, 'unit_price', v_customer_unit,
        'discount_pct', v_discount_pct, 'line_total', v_line_customer
      );

    elsif v_item->>'type' = 'bom_fixed' then
      v_customer_unit := case v_item->>'key'
        when 'transport' then v_bom.transport_customer_fixed
        when 'install' then v_bom.install_customer_per_unit
        else null end;
      v_cost_unit := case v_item->>'key'
        when 'transport' then v_bom_cost.transport_cost_fixed
        when 'install' then v_bom_cost.install_cost_per_unit
        else null end;
      if v_customer_unit is null then
        raise exception 'unknown bom_fixed key for irrigation quote: %', v_item->>'key';
      end if;

      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);
      v_line_cost := v_qty * v_cost_unit;

      v_result_items := v_result_items || jsonb_build_object(
        'label', coalesce(v_item->>'label', v_item->>'key'),
        'qty', v_qty, 'unit_price', v_customer_unit,
        'discount_pct', v_discount_pct, 'line_total', v_line_customer
      );
    else
      raise exception 'unknown item type: %', v_item->>'type';
    end if;

    v_subtotal_customer := v_subtotal_customer + v_line_customer;
    v_subtotal_cost := v_subtotal_cost + v_line_cost;
  end loop;

  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)
  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')
  on conflict (phone) do update
    set name = excluded.name,
        city = coalesce(excluded.city, public.customers.city),
        updated_at = now()
  returning id into v_customer_id;

  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)
  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)
  returning id into v_quote_id;

  insert into public.quote_costs (quote_id, total_cost, profit)
  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);

  return v_quote_id;
end;
$$;


--
-- Name: rep_create_irrigation_solar_quote(text, text, text, numeric, uuid, text, jsonb, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rep_create_irrigation_solar_quote(p_customer_name text, p_customer_phone text, p_customer_city text, p_hp numeric, p_panel_product_id uuid, p_structure_type text DEFAULT 'FIXED'::text, p_toggles jsonb DEFAULT '{"mc4": true, "ip65": true, "earth": true, "panel": true, "cables": true, "reactor": true, "combiner": true, "concrete": true, "inverter": true, "structure": true, "transport": true, "install_elec": true, "install_mech": true}'::jsonb, p_discount_pct numeric DEFAULT 0, p_quote_type text DEFAULT 'supply_install'::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rep_id uuid := auth.uid();
  v_customer_id bigint;
  v_quote_id bigint;
  v_calc jsonb;
begin
  if not (is_rep() or is_admin()) then raise exception 'not authorized'; end if;
  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then raise exception 'invalid phone'; end if;

  v_calc := public._irrigation_solar_calc(p_hp, p_panel_product_id, p_structure_type, p_toggles, p_discount_pct);
  if v_calc ? 'error' then return v_calc; end if;

  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)
  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')
  on conflict (phone) do update set name = excluded.name, city = coalesce(excluded.city, public.customers.city), updated_at = now()
  returning id into v_customer_id;

  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)
  values (v_customer_id, v_rep_id, p_quote_type, v_calc->'rows', (v_calc->>'final_total')::numeric, 0, (v_calc->>'final_total')::numeric, p_notes)
  returning id into v_quote_id;

  return v_calc || jsonb_build_object('quote_id', v_quote_id);
end;
$$;


--
-- Name: rep_create_offgrid_quote(text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rep_create_offgrid_quote(p_customer_name text, p_customer_phone text, p_customer_city text, p_quote_type text, p_items jsonb, p_notes text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rep_id uuid := auth.uid();
  v_customer_id bigint;
  v_quote_id bigint;
  v_item jsonb;
  v_result_items jsonb := '[]'::jsonb;
  v_subtotal_customer numeric := 0;
  v_subtotal_cost numeric := 0;
  v_discount_pct numeric;
  v_supplier_discount_pct numeric;
  v_qty numeric;
  v_watt numeric;
  v_customer_unit numeric;
  v_cost_unit numeric;
  v_line_customer numeric;
  v_line_cost numeric;
  v_prod record;
  v_bom record;
  v_bom_cost record;
begin
  if not (is_rep() or is_admin()) then
    raise exception 'not authorized';
  end if;
  if p_quote_type not in ('supply_only','supply_install') then
    raise exception 'invalid quote_type';
  end if;
  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then
    raise exception 'invalid phone';
  end if;

  select * into v_bom from public.offgrid_bom_settings where id = 1;
  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_qty := coalesce((v_item->>'qty')::numeric, 0);
    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));
    if v_qty <= 0 then
      continue;
    end if;

    if v_item->>'type' = 'product' then
      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod
        from public.products p
        where p.id = (v_item->>'product_id')::uuid and p.published = true;
      if v_prod.id is null then
        raise exception 'product not found or not published: %', v_item->>'product_id';
      end if;
      v_customer_unit := coalesce(v_prod.price, 0);
      select supplier_discount_pct into v_supplier_discount_pct
        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;
      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);

      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);
      v_line_cost := v_qty * v_cost_unit;

      v_result_items := v_result_items || jsonb_build_object(
        'label', coalesce(v_item->>'label', v_prod.name_ar),
        'qty', v_qty, 'unit_price', v_customer_unit,
        'discount_pct', v_discount_pct, 'line_total', v_line_customer,
        'warranty', v_item->>'warranty'
      );

    elsif v_item->>'type' = 'panel' then
      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod
        from public.products p
        where p.id = (v_item->>'product_id')::uuid and p.published = true;
      if v_prod.id is null then
        raise exception 'panel product not found or not published: %', v_item->>'product_id';
      end if;
      v_watt := coalesce((v_item->>'watt')::numeric, 0);
      if v_watt <= 0 then
        raise exception 'invalid panel watt';
      end if;
      v_customer_unit := coalesce(v_prod.price, 0) * v_watt;
      select supplier_discount_pct into v_supplier_discount_pct
        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;
      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);

      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);
      v_line_cost := v_qty * v_cost_unit;

      v_result_items := v_result_items || jsonb_build_object(
        'label', coalesce(v_item->>'label', v_prod.name_ar),
        'qty', v_qty, 'unit_price', v_customer_unit,
        'discount_pct', v_discount_pct, 'line_total', v_line_customer,
        'warranty', v_item->>'warranty'
      );

    elsif v_item->>'type' = 'bom_fixed' then
      v_customer_unit := case v_item->>'key'
        when 'steel' then v_bom.steel_customer_per_unit
        when 'cables' then v_bom.cables_customer_per_meter
        when 'accessories' then v_bom.accessories_customer_fixed
        when 'transport' then v_bom.transport_customer_fixed
        when 'install' then v_bom.install_customer_per_unit
        when 'combiner_box' then v_bom.combiner_box_customer_fixed
        when 'mc4' then v_bom.mc4_customer_per_pair
        when 'concrete' then v_bom.concrete_customer_fixed
        when 'field_works' then v_bom.field_works_customer_fixed
        when 'electrical_install' then v_bom.electrical_install_customer_fixed
        else null end;
      v_cost_unit := case v_item->>'key'
        when 'steel' then v_bom_cost.steel_cost_per_unit
        when 'cables' then v_bom_cost.cables_cost_per_meter
        when 'accessories' then v_bom_cost.accessories_cost_fixed
        when 'transport' then v_bom_cost.transport_cost_fixed
        when 'install' then v_bom_cost.install_cost_per_unit
        when 'combiner_box' then v_bom_cost.combiner_box_cost_fixed
        when 'mc4' then v_bom_cost.mc4_cost_per_pair
        when 'concrete' then v_bom_cost.concrete_cost_fixed
        when 'field_works' then v_bom_cost.field_works_cost_fixed
        when 'electrical_install' then v_bom_cost.electrical_install_cost_fixed
        else null end;
      if v_customer_unit is null then
        raise exception 'unknown bom_fixed key: %', v_item->>'key';
      end if;

      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);
      v_line_cost := v_qty * v_cost_unit;

      v_result_items := v_result_items || jsonb_build_object(
        'label', coalesce(v_item->>'label', v_item->>'key'),
        'qty', v_qty, 'unit_price', v_customer_unit,
        'discount_pct', v_discount_pct, 'line_total', v_line_customer,
        'warranty', v_item->>'warranty'
      );

    elsif v_item->>'type' = 'custom' then
      -- بند يدوي بيدخله المندوب بنفسه (لوح إضافي/كابل زيادة/أي حاجة لظروف
      -- الموقع) — مفيش مرجع كتالوج نتحقق منه، فبنثق في السعر اللي كتبه
      -- المندوب زي ما هو. التكلفة الداخلية = نفس سعر البيع (مش أقل)، عشان
      -- تقرير الربح متفترضش هامش ربح وهمي على بند مالوش تكلفة موردين حقيقية.
      v_customer_unit := coalesce((v_item->>'unit_price')::numeric, 0);
      v_cost_unit := v_customer_unit;

      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);
      v_line_cost := v_qty * v_cost_unit;

      v_result_items := v_result_items || jsonb_build_object(
        'label', coalesce(v_item->>'label', 'بند يدوي'),
        'qty', v_qty, 'unit_price', v_customer_unit,
        'discount_pct', v_discount_pct, 'line_total', v_line_customer,
        'warranty', v_item->>'warranty'
      );

    elsif v_item->>'type' = 'info_only' then
      -- بند معلوماتي بس (زي التأريض/الريأكتور) — يظهر في العرض بدون سعر أو كمية
      v_result_items := v_result_items || jsonb_build_object(
        'label', v_item->>'label', 'qty', null, 'unit_price', 0,
        'discount_pct', 0, 'line_total', 0, 'warranty', v_item->>'warranty', 'info_only', true
      );
      continue;
    else
      raise exception 'unknown item type: %', v_item->>'type';
    end if;

    v_subtotal_customer := v_subtotal_customer + v_line_customer;
    v_subtotal_cost := v_subtotal_cost + v_line_cost;
  end loop;

  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)
  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')
  on conflict (phone) do update
    set name = excluded.name,
        city = coalesce(excluded.city, public.customers.city),
        updated_at = now()
  returning id into v_customer_id;

  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)
  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)
  returning id into v_quote_id;

  insert into public.quote_costs (quote_id, total_cost, profit)
  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);

  return v_quote_id;
end;
$$;


--
-- Name: rep_create_quote(text, text, text, text, jsonb, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rep_create_quote(p_customer_name text, p_customer_phone text, p_customer_city text, p_quote_type text, p_items jsonb, p_installation_cost numeric, p_notes text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rep_id uuid := auth.uid();
  v_customer_id bigint;
  v_quote_id bigint;
  v_item jsonb;
  v_product record;
  v_discount_pct numeric;
  v_unit_price numeric;
  v_qty numeric;
  v_computed_items jsonb := '[]'::jsonb;
  v_subtotal numeric := 0;
  v_total numeric := 0;
  v_install numeric := coalesce(p_installation_cost, 0);
begin
  if not (is_rep() or is_admin()) then
    raise exception 'not authorized';
  end if;
  if p_quote_type not in ('supply_only','supply_install') then
    raise exception 'invalid quote_type';
  end if;
  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then
    raise exception 'invalid phone';
  end if;
  if v_install < 0 then
    raise exception 'invalid installation cost';
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_qty := coalesce((v_item->>'qty')::numeric, 0);
    if v_qty <= 0 then
      raise exception 'invalid quantity';
    end if;

    select id, name_ar, name_en, category, brand, price
      into v_product
      from public.products
      where id = (v_item->>'product_id')::uuid
        and published = true;

    if v_product.id is null then
      raise exception 'product not found or unpublished: %', v_item->>'product_id';
    end if;

    select supplier_discount_pct into v_discount_pct
      from public.supplier_discounts
      where category = v_product.category and brand = v_product.brand;

    v_unit_price := round(coalesce(v_product.price, 0) * (1 - coalesce(v_discount_pct, 0) / 100.0), 2);

    v_computed_items := v_computed_items || jsonb_build_object(
      'product_id', v_product.id,
      'name', coalesce(v_product.name_ar, v_product.name_en),
      'unit_price', v_unit_price,
      'qty', v_qty,
      'line_total', v_unit_price * v_qty
    );

    v_subtotal := v_subtotal + (v_unit_price * v_qty);
  end loop;

  if jsonb_array_length(v_computed_items) = 0 then
    raise exception 'quote must have at least one item';
  end if;

  if p_quote_type = 'supply_install' then
    v_total := v_subtotal + v_install;
  else
    v_install := 0;
    v_total := v_subtotal;
  end if;

  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)
  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')
  on conflict (phone) do update
    set name = excluded.name,
        city = coalesce(excluded.city, public.customers.city),
        updated_at = now()
  returning id into v_customer_id;

  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)
  values (v_customer_id, v_rep_id, p_quote_type, v_computed_items, v_subtotal, v_install, v_total, p_notes)
  returning id into v_quote_id;

  return v_quote_id;
end;
$$;


--
-- Name: rep_upsert_quote_draft(text, text, text, jsonb, numeric, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rep_upsert_quote_draft(p_customer_name text, p_customer_phone text, p_quote_type text, p_items jsonb, p_subtotal numeric, p_installation_cost numeric, p_total numeric, p_page text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_rep() then raise exception 'not authorized'; end if;
  insert into quote_drafts (rep_id, customer_name, customer_phone, quote_type, items, subtotal, installation_cost, total, page, last_active_at)
  values (auth.uid(), p_customer_name, p_customer_phone, p_quote_type, p_items, p_subtotal, p_installation_cost, p_total, p_page, now())
  on conflict (rep_id) do update set
    customer_name = excluded.customer_name, customer_phone = excluded.customer_phone,
    quote_type = excluded.quote_type, items = excluded.items, subtotal = excluded.subtotal,
    installation_cost = excluded.installation_cost, total = excluded.total,
    page = excluded.page, last_active_at = now();
end;
$$;


--
-- Name: reps_protect_sensitive_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reps_protect_sensitive_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NOT is_admin() THEN
    NEW.email := OLD.email;
    NEW.active := OLD.active;
    NEW.id := OLD.id;
    NEW.can_access_offgrid := OLD.can_access_offgrid;
    NEW.can_access_products := OLD.can_access_products;
    NEW.can_access_crm := OLD.can_access_crm;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: submit_cart_quote_request(text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_cart_quote_request(p_customer_name text, p_customer_phone text, p_customer_city text, p_items jsonb, p_notes text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id bigint;
  v_item jsonb;
  v_product record;
  v_unit_price numeric;
  v_qty numeric;
  v_computed_items jsonb := '[]'::jsonb;
  v_subtotal numeric := 0;
begin
  if p_customer_name is null or length(trim(p_customer_name)) < 2 then
    raise exception 'invalid name';
  end if;
  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then
    raise exception 'invalid phone';
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_qty := coalesce((v_item->>'qty')::numeric, 0);
    if v_qty <= 0 then
      raise exception 'invalid quantity';
    end if;

    select id, name_ar, name_en, category, brand, price, power_watt
      into v_product
      from public.products
      where id = (v_item->>'product_id')::uuid;

    if v_product.id is null then
      raise exception 'product not found: %', v_item->>'product_id';
    end if;

    -- Panels: price column is EGP-per-watt, not a flat unit price.
    -- Everything else: price is already the flat per-unit price.
    if v_product.category = 'panels' and v_product.power_watt is not null then
      v_unit_price := round(coalesce(v_product.price, 0) * v_product.power_watt::numeric, 2);
    else
      v_unit_price := round(coalesce(v_product.price, 0), 2);
    end if;

    v_computed_items := v_computed_items || jsonb_build_object(
      'product_id', v_product.id,
      'name', coalesce(v_product.name_ar, v_product.name_en),
      'category', v_product.category,
      'brand', v_product.brand,
      'unit_price', v_unit_price,
      'qty', v_qty,
      'line_total', v_unit_price * v_qty
    );

    v_subtotal := v_subtotal + (v_unit_price * v_qty);
  end loop;

  if jsonb_array_length(v_computed_items) = 0 then
    raise exception 'cart is empty';
  end if;

  insert into public.cart_quote_requests (customer_name, customer_phone, customer_city, items, subtotal, notes)
  values (trim(p_customer_name), trim(p_customer_phone), nullif(trim(coalesce(p_customer_city, '')), ''), v_computed_items, v_subtotal, p_notes)
  returning id into v_request_id;

  return v_request_id;
end;
$$;


--
-- Name: apply_rls(jsonb, integer); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024)) RETURNS SETOF realtime.wal_rls
    LANGUAGE plpgsql
    AS $$
declare
    -- Regclass of the table e.g. public.notes
    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;

    -- I, U, D, T: insert, update ...
    action realtime.action = (
        case wal ->> 'action'
            when 'I' then 'INSERT'
            when 'U' then 'UPDATE'
            when 'D' then 'DELETE'
            else 'ERROR'
        end
    );

    -- Is row level security enabled for the table
    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;

    subscriptions realtime.subscription[] = array_agg(subs)
        from
            realtime.subscription subs
        where
            subs.entity = entity_
            -- Filter by action early - only get subscriptions interested in this action
            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'
            and (subs.action_filter = '*' or subs.action_filter = action::text);

    -- Subscription vars
    working_role regrole;
    working_selected_columns text[];
    claimed_role regrole;
    claims jsonb;

    subscription_id uuid;
    subscription_has_access bool;
    visible_to_subscription_ids uuid[] = '{}';

    -- structured info for wal's columns
    columns realtime.wal_column[];
    -- previous identity values for update/delete
    old_columns realtime.wal_column[];

    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;

    -- Primary jsonb output for record
    output jsonb;

    -- Loop record for iterating unique roles (outer loop)
    role_record record;
    -- Loop record for iterating unique selected_columns within a role (inner loop)
    cols_record record;
    -- Subscription ids visible at the role level (before fanning out by selected_columns)
    visible_role_sub_ids uuid[] = '{}';

begin
    perform set_config('role', null, true);

    columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'columns') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    old_columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'identity') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    for role_record in
        select claims_role
        from (select distinct claims_role from unnest(subscriptions)) t
        order by claims_role::text
    loop
        working_role := role_record.claims_role;

        -- Update `is_selectable` for columns and old_columns (once per role)
        columns =
            array_agg(
                (
                    c.name,
                    c.type_name,
                    c.type_oid,
                    c.value,
                    c.is_pkey,
                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                )::realtime.wal_column
            )
            from
                unnest(columns) c;

        old_columns =
                array_agg(
                    (
                        c.name,
                        c.type_name,
                        c.type_oid,
                        c.value,
                        c.is_pkey,
                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                    )::realtime.wal_column
                )
                from
                    unnest(old_columns) c;

        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then
            -- Fan out 400 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 400: Bad Request, no primary key']
                )::realtime.wal_rls;
            end loop;

        -- The claims role does not have SELECT permission to the primary key of entity
        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then
            -- Fan out 401 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 401: Unauthorized']
                )::realtime.wal_rls;
            end loop;

        else
            -- Create the prepared statement (once per role)
            if is_rls_enabled and action <> 'DELETE' then
                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then
                    deallocate walrus_rls_stmt;
                end if;
                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);
            end if;

            -- Collect all visible subscription IDs for this role (filter check + RLS check)
            visible_role_sub_ids = '{}';

            for subscription_id, claims in (
                    select
                        subs.subscription_id,
                        subs.claims
                    from
                        unnest(subscriptions) subs
                    where
                        subs.entity = entity_
                        and subs.claims_role = working_role
                        and (
                            realtime.is_visible_through_filters(columns, subs.filters)
                            or (
                              action = 'DELETE'
                              and realtime.is_visible_through_filters(old_columns, subs.filters)
                            )
                        )
            ) loop

                if not is_rls_enabled or action = 'DELETE' then
                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                else
                    -- Check if RLS allows the role to see the record
                    perform
                        -- Trim leading and trailing quotes from working_role because set_config
                        -- doesn't recognize the role as valid if they are included
                        set_config('role', trim(both '"' from working_role::text), true),
                        set_config('request.jwt.claims', claims::text, true);

                    execute 'execute walrus_rls_stmt' into subscription_has_access;

                    -- Reset the role on every FOR..LOOP batch execution.
                    -- The first batch of 10 rows is pre-fetched using the current connection role (PG internal behaviour)
                    -- then we have to reset it again otherwise it would use the role defined in the `set_config` above
                    -- to fetch the remaining rows when rows>10, which could be a user-defined role that lacks execution grants.
                    -- The flow is:
                    --   1. run batch with conn role
                    --   2. set_config working_role
                    --   3. execute walrus
                    --   4. reset role (revert)
                    --   5. repeat
                    perform set_config('role', null, true);

                    if subscription_has_access then
                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                    end if;
                end if;
            end loop;

            perform set_config('role', null, true);

            -- Inner loop: per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;

                output = jsonb_build_object(
                    'schema', wal ->> 'schema',
                    'table', wal ->> 'table',
                    'type', action,
                    'commit_timestamp', to_char(
                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),
                        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                    ),
                    'columns', (
                        select
                            jsonb_agg(
                                jsonb_build_object(
                                    'name', pa.attname,
                                    'type', pt.typname
                                )
                                order by pa.attnum asc
                            )
                        from
                            pg_attribute pa
                            join pg_type pt
                                on pa.atttypid = pt.oid
                            left join (
                                select unnest(conkey) as pkey_attnum
                                from pg_constraint
                                where conrelid = entity_ and contype = 'p'
                            ) pk on pk.pkey_attnum = pa.attnum
                        where
                            attrelid = entity_
                            and attnum > 0
                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')
                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)
                    )
                )
                -- Add "record" key for insert and update
                || case
                    when action in ('INSERT', 'UPDATE') then
                        jsonb_build_object(
                            'record',
                            (
                                select
                                    jsonb_object_agg(
                                        -- if unchanged toast, get column name and value from old record
                                        coalesce((c).name, (oc).name),
                                        case
                                            when (c).name is null then (oc).value
                                            else (c).value
                                        end
                                    )
                                from
                                    unnest(columns) c
                                    full outer join unnest(old_columns) oc
                                        on (c).name = (oc).name
                                where
                                    coalesce((c).is_selectable, (oc).is_selectable)
                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                            )
                        )
                    else '{}'::jsonb
                end
                -- Add "old_record" key for update and delete
                || case
                    when action = 'UPDATE' then
                        jsonb_build_object(
                                'old_record',
                                (
                                    select jsonb_object_agg((c).name, (c).value)
                                    from unnest(old_columns) c
                                    where
                                        (c).is_selectable
                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                )
                            )
                    when action = 'DELETE' then
                        jsonb_build_object(
                            'old_record',
                            (
                                select jsonb_object_agg((c).name, (c).value)
                                from unnest(old_columns) c
                                where
                                    (c).is_selectable
                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey
                            )
                        )
                    else '{}'::jsonb
                end;

                -- Filter visible_role_sub_ids to those matching the current selected_columns group
                visible_to_subscription_ids = coalesce(
                    (
                        select array_agg(s.subscription_id)
                        from unnest(subscriptions) s
                        where s.claims_role = working_role
                          and (s.selected_columns is not distinct from working_selected_columns)
                          and s.subscription_id = any(visible_role_sub_ids)
                    ),
                    '{}'::uuid[]
                );

                return next (
                    output,
                    is_rls_enabled,
                    visible_to_subscription_ids,
                    case
                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']
                        else '{}'
                    end
                )::realtime.wal_rls;
            end loop;

        end if;
    end loop;

    perform set_config('role', null, true);
end;
$$;


--
-- Name: broadcast_changes(text, text, text, text, text, record, record, text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Declare a variable to hold the JSONB representation of the row
    row_data jsonb := '{}'::jsonb;
BEGIN
    IF level = 'STATEMENT' THEN
        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';
    END IF;
    -- Check the operation type and handle accordingly
    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN
        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);
        PERFORM realtime.send (row_data, event_name, topic_name);
    ELSE
        RAISE EXCEPTION 'Unexpected operation type: %', operation;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;
END;

$$;


--
-- Name: build_prepared_statement_sql(text, regclass, realtime.wal_column[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) RETURNS text
    LANGUAGE sql
    AS $$
      /*
      Builds a sql string that, if executed, creates a prepared statement to
      tests retrive a row from *entity* by its primary key columns.
      Example
          select realtime.build_prepared_statement_sql('public.notes', '{"id"}'::text[], '{"bigint"}'::text[])
      */
          select
      'prepare ' || prepared_statement_name || ' as
          select
              exists(
                  select
                      1
                  from
                      ' || entity || '
                  where
                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '
              )'
          from
              unnest(columns) pkc
          where
              pkc.is_pkey
          group by
              entity
      $$;


--
-- Name: cast(text, regtype); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime."cast"(val text, type_ regtype) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  res jsonb;
begin
  if type_::text = 'bytea' then
    return to_jsonb(val);
  end if;
  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;
  return res;
end
$$;


--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
/*
Casts *val_1* and *val_2* as type *type_* and check the *op* condition for truthiness
*/
declare
    op_symbol text = (
        case
            when op = 'eq' then '='
            when op = 'neq' then '!='
            when op = 'lt' then '<'
            when op = 'lte' then '<='
            when op = 'gt' then '>'
            when op = 'gte' then '>='
            when op = 'in' then '= any'
            else 'UNKNOWN OP'
        end
    );
    res boolean;
begin
    execute format(
        'select %L::'|| type_::text || ' ' || op_symbol
        || ' ( %L::'
        || (
            case
                when op = 'in' then type_::text || '[]'
                else type_::text end
        )
        || ')', val_1, val_2) into res;
    return res;
end;
$$;


--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
declare
    op_symbol text;
    res boolean;
begin
    -- IS DISTINCT FROM / IS NOT DISTINCT FROM: infix, both sides typed literals
    if op = 'isdistinct' then
        execute format(
            'select %L::%s %s %L::%s',
            val_1,
            type_::text,
            case when negate then 'IS NOT DISTINCT FROM' else 'IS DISTINCT FROM' end,
            val_2,
            type_::text
        ) into res;
        return res;
    end if;

    -- IS requires a keyword RHS (NULL, TRUE, FALSE, UNKNOWN), not a typed literal
    if op = 'is' then
        if val_2 not in ('null', 'true', 'false', 'unknown') then
            raise exception 'invalid value for is filter: must be null, true, false, or unknown';
        end if;
        execute format(
            'select %L::%s %s %s',
            val_1,
            type_::text,
            case when negate then 'IS NOT' else 'IS' end,
            upper(val_2)
        ) into res;
        return res;
    end if;

    op_symbol = case
        when op = 'eq'    then '='
        when op = 'neq'   then '!='
        when op = 'lt'    then '<'
        when op = 'lte'   then '<='
        when op = 'gt'    then '>'
        when op = 'gte'   then '>='
        when op = 'in'    then '= any'
        when op = 'like'   then 'LIKE'
        when op = 'ilike'  then 'ILIKE'
        when op = 'match'  then '~'
        when op = 'imatch' then '~*'
        else null
    end;

    if op_symbol is null then
        raise exception 'unsupported equality operator: %', op::text;
    end if;

    execute format(
        'select %L::%s %s (%L::%s)',
        val_1,
        type_::text,
        op_symbol,
        val_2,
        case when op = 'in' then type_::text || '[]' else type_::text end
    ) into res;

    return case when negate then not res else res end;
end;
$$;


--
-- Name: is_visible_through_filters(realtime.wal_column[], realtime.user_defined_filter[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    select
        filters is null
        or array_length(filters, 1) is null
        or coalesce(
            count(col.name) = count(1)
            and sum(
                realtime.check_equality_op(
                    op:=f.op,
                    type_:=coalesce(col.type_oid::regtype, col.type_name::regtype),
                    val_1:=col.value #>> '{}',
                    val_2:=f.value,
                    negate:=coalesce(f.negate, false)
                )::int
            ) filter (where col.name is not null) = count(col.name),
            false
        )
    from
        unnest(filters) f
        left join unnest(columns) col
            on f.column_name = col.name;
$$;


--
-- Name: list_changes(name, name, integer, integer); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer) RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)
    LANGUAGE sql
    SET log_min_messages TO 'fatal'
    AS $$
  WITH pub AS (
    SELECT
      concat_ws(
        ',',
        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,
        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,
        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END
      ) AS w2j_actions,
      coalesce(
        string_agg(
          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),
          ','
        ) filter (WHERE ppt.tablename IS NOT NULL),
        ''
      ) AS w2j_add_tables
    FROM pg_publication pp
    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname
    WHERE pp.pubname = publication
    GROUP BY pp.pubname
    LIMIT 1
  ),
  -- MATERIALIZED ensures pg_logical_slot_get_changes is called exactly once
  w2j AS MATERIALIZED (
    SELECT x.*, pub.w2j_add_tables
    FROM pub,
         pg_logical_slot_get_changes(
           slot_name, null, max_changes,
           'include-pk', 'true',
           'include-transaction', 'false',
           'include-timestamp', 'true',
           'include-type-oids', 'true',
           'format-version', '2',
           'actions', pub.w2j_actions,
           'add-tables', pub.w2j_add_tables
         ) x
  ),
  slot_count AS (
    SELECT count(*)::bigint AS cnt
    FROM w2j
    WHERE w2j.w2j_add_tables <> ''
  ),
  rls_filtered AS (
    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors
    FROM w2j,
         realtime.apply_rls(
           wal := w2j.data::jsonb,
           max_record_bytes := max_record_bytes
         ) xyz(wal, is_rls_enabled, subscription_ids, errors)
    WHERE w2j.w2j_add_tables <> ''
      AND xyz.subscription_ids[1] IS NOT NULL
  )
  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt
  FROM rls_filtered rf, slot_count sc

  UNION ALL

  SELECT null, null, null, null, sc.cnt
  FROM slot_count sc
  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)
$$;


--
-- Name: quote_wal2json(regclass); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.quote_wal2json(entity regclass) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT
    realtime.wal2json_escape_identifier(nsp.nspname::text)
    || '.'
    || realtime.wal2json_escape_identifier(pc.relname::text)
  FROM pg_class pc
  JOIN pg_namespace nsp ON pc.relnamespace = nsp.oid
  WHERE pc.oid = entity
$$;


--
-- Name: send(jsonb, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  generated_id uuid;
  final_payload jsonb;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    -- Check if payload has an 'id' key, if not, add the generated UUID
    IF payload ? 'id' THEN
      final_payload := payload;
    ELSE
      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));
    END IF;

    -- Set the topic configuration
    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)
    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$$;


--
-- Name: send_binary(bytea, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.send_binary(payload bytea, event text, topic text, private boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  generated_id uuid;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, binary_payload, event, topic, private, extension)
    VALUES (generated_id, payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$$;


--
-- Name: subscription_check_filters(); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.subscription_check_filters() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    col_names text[] = coalesce(
            array_agg(a.attname order by a.attnum),
            '{}'::text[]
        )
        from
            pg_catalog.pg_attribute a
        where
            a.attrelid = new.entity
            and a.attnum > 0
            and not a.attisdropped
            and pg_catalog.has_column_privilege(
                (new.claims ->> 'role'),
                a.attrelid,
                a.attnum,
                'SELECT'
            );
    filter realtime.user_defined_filter;
    col_type regtype;
    in_val jsonb;
    selected_col text;
begin
    for filter in select * from unnest(new.filters) loop
        if not filter.column_name = any(col_names) then
            raise exception 'invalid column for filter %', filter.column_name;
        end if;

        col_type = (
            select atttypid::regtype
            from pg_catalog.pg_attribute
            where attrelid = new.entity
                  and attname = filter.column_name
        );
        if col_type is null then
            raise exception 'failed to lookup type for column %', filter.column_name;
        end if;

        if filter.op = 'in'::realtime.equality_op then
            in_val = realtime.cast(filter.value, (col_type::text || '[]')::regtype);
            if coalesce(jsonb_array_length(in_val), 0) > 100 then
                raise exception 'too many values for `in` filter. Maximum 100';
            end if;
        elsif filter.op = 'is'::realtime.equality_op then
            -- `is` requires a keyword RHS rather than a typed literal
            if filter.value not in ('null', 'true', 'false', 'unknown') then
                raise exception 'invalid value for is filter: must be null, true, false, or unknown';
            end if;
            -- IS NULL works for any type, but IS TRUE/FALSE/UNKNOWN require a boolean
            -- operand. Reject the non-null keywords on non-boolean columns here so they
            -- don't abort apply_rls at WAL time.
            if filter.value <> 'null' and col_type <> 'boolean'::regtype then
                raise exception 'is % filter requires a boolean column, got %', filter.value, col_type::text;
            end if;
        elsif filter.op in ('like'::realtime.equality_op, 'ilike'::realtime.equality_op) then
            -- like/ilike apply the text pattern operator (~~); reject column types that
            -- have no such operator instead of failing at WAL time
            if not exists (
                select 1 from pg_catalog.pg_operator
                where oprname = '~~' and oprleft = col_type
            ) then
                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;
            end if;
        elsif filter.op in ('match'::realtime.equality_op, 'imatch'::realtime.equality_op) then
            -- match/imatch apply the regex operators ~ / ~*; reject column types that have
            -- no such operator (e.g. integer) instead of failing at WAL time, mirroring the
            -- like/ilike guard above.
            if not exists (
                select 1 from pg_catalog.pg_operator
                where oprname = case when filter.op = 'imatch'::realtime.equality_op then '~*' else '~' end
                  and oprleft = col_type
                  and oprright = col_type
                  and oprresult = 'boolean'::regtype
            ) then
                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;
            end if;
            -- validate the regex eagerly so a bad pattern is rejected here, not inside
            -- apply_rls where it would abort the WAL stream for the entity
            begin
                perform '' ~ filter.value;
            exception when others then
                raise exception 'invalid regular expression for % filter: %', filter.op::text, sqlerrm;
            end;
        else
            -- eq/neq/lt/lte/gt/gte: value must be coercable to the type
            perform realtime.cast(filter.value, col_type);
        end if;
    end loop;

    if new.selected_columns is not null then
        for selected_col in select * from unnest(new.selected_columns) loop
            if not selected_col = any(col_names) then
                raise exception 'invalid column for select %', selected_col;
            end if;
        end loop;
    end if;

    -- Apply consistent order to filters so the unique constraint can't be tricked by a
    -- different filter order. negate is part of the sort key.
    new.filters = coalesce(
        array_agg(f order by f.column_name, f.op, f.value, f.negate),
        '{}'
    ) from unnest(new.filters) f;

    -- Normalize selected_columns order so ARRAY['a','b'] and ARRAY['b','a'] are treated
    -- as the same subscription group in apply_rls. Preserve an empty array as '{}'
    -- ("primary keys only") so it stays distinct from NULL ("all columns"); array_agg
    -- over an empty set would otherwise collapse '{}' back to NULL.
    if new.selected_columns is not null then
        new.selected_columns = coalesce(
            (
                select array_agg(c order by c)
                from unnest(new.selected_columns) c
            ),
            '{}'::text[]
        );
    end if;

    return new;
end;
$$;


--
-- Name: to_regrole(text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.to_regrole(role_name text) RETURNS regrole
    LANGUAGE sql IMMUTABLE
    AS $$ select role_name::regrole $$;


--
-- Name: topic(); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.topic() RETURNS text
    LANGUAGE sql STABLE
    AS $$
select nullif(current_setting('realtime.topic', true), '')::text;
$$;


--
-- Name: wal2json_escape_identifier(text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.wal2json_escape_identifier(name text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  -- Prefix `\`, `,`, `.`, and any whitespace with `\`
  SELECT regexp_replace(name, '([\\,.[:space:]])', '\\\1', 'g')
$$;


--
-- Name: allow_any_operation(text[]); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.allow_any_operation(expected_operations text[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  WITH current_operation AS (
    SELECT storage.operation() AS raw_operation
  ),
  normalized AS (
    SELECT CASE
      WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)
      ELSE raw_operation
    END AS current_operation
    FROM current_operation
  )
  SELECT EXISTS (
    SELECT 1
    FROM normalized n
    CROSS JOIN LATERAL unnest(expected_operations) AS expected_operation
    WHERE expected_operation IS NOT NULL
      AND expected_operation <> ''
      AND n.current_operation = CASE
        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)
        ELSE expected_operation
      END
  );
$$;


--
-- Name: allow_only_operation(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.allow_only_operation(expected_operation text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  WITH current_operation AS (
    SELECT storage.operation() AS raw_operation
  ),
  normalized AS (
    SELECT
      CASE
        WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)
        ELSE raw_operation
      END AS current_operation,
      CASE
        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)
        ELSE expected_operation
      END AS requested_operation
    FROM current_operation
  )
  SELECT CASE
    WHEN requested_operation IS NULL OR requested_operation = '' THEN FALSE
    ELSE COALESCE(current_operation = requested_operation, FALSE)
  END
  FROM normalized;
$$;


--
-- Name: can_insert_object(text, text, uuid, jsonb); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO "storage"."objects" ("bucket_id", "name", "owner", "metadata") VALUES (bucketid, name, owner, metadata);
  -- hack to rollback the successful insert
  RAISE sqlstate 'PT200' using
  message = 'ROLLBACK',
  detail = 'rollback successful insert';
END
$$;


--
-- Name: enforce_bucket_name_length(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.enforce_bucket_name_length() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if length(new.name) > 100 then
        raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
    end if;
    return new;
end;
$$;


--
-- Name: extension(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.extension(name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    _parts text[];
    _filename text;
BEGIN
    -- Split on "/" to get path segments
    SELECT string_to_array(name, '/') INTO _parts;
    -- Get the last path segment (the actual filename)
    SELECT _parts[array_length(_parts, 1)] INTO _filename;
    -- Extract extension: reverse, split on '.', then reverse again
    RETURN reverse(split_part(reverse(_filename), '.', 1));
END
$$;


--
-- Name: filename(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.filename(name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    _parts text[];
BEGIN
    SELECT string_to_array(name, '/') INTO _parts;
    RETURN _parts[array_length(_parts, 1)];
END
$$;


--
-- Name: foldername(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.foldername(name text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    _parts text[];
BEGIN
    -- Split on "/" to get path segments
    SELECT string_to_array(name, '/') INTO _parts;
    -- Return everything except the last segment
    RETURN _parts[1 : array_length(_parts,1) - 1];
END
$$;


--
-- Name: get_common_prefix(text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.get_common_prefix(p_key text, p_prefix text, p_delimiter text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT CASE
    WHEN position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)) > 0
    THEN left(p_key, length(p_prefix) + position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)))
    ELSE NULL
END;
$$;


--
-- Name: get_size_by_bucket(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.get_size_by_bucket() RETURNS TABLE(size bigint, bucket_id text)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    return query
        select sum((metadata->>'size')::bigint)::bigint as size, obj.bucket_id
        from "storage".objects as obj
        group by obj.bucket_id;
END
$$;


--
-- Name: list_multipart_uploads_with_delimiter(text, text, text, integer, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.list_multipart_uploads_with_delimiter(bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, next_key_token text DEFAULT ''::text, next_upload_token text DEFAULT ''::text) RETURNS TABLE(key text, id text, created_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $_$
BEGIN
    RETURN QUERY EXECUTE
        'SELECT DISTINCT ON(key COLLATE "C") * from (
            SELECT
                CASE
                    WHEN position($2 IN substring(key from length($1) + 1)) > 0 THEN
                        substring(key from 1 for length($1) + position($2 IN substring(key from length($1) + 1)))
                    ELSE
                        key
                END AS key, id, created_at
            FROM
                storage.s3_multipart_uploads
            WHERE
                bucket_id = $5 AND
                key ILIKE $1 || ''%'' AND
                CASE
                    WHEN $4 != '''' AND $6 = '''' THEN
                        CASE
                            WHEN position($2 IN substring(key from length($1) + 1)) > 0 THEN
                                substring(key from 1 for length($1) + position($2 IN substring(key from length($1) + 1))) COLLATE "C" > $4
                            ELSE
                                key COLLATE "C" > $4
                            END
                    ELSE
                        true
                END AND
                CASE
                    WHEN $6 != '''' THEN
                        id COLLATE "C" > $6
                    ELSE
                        true
                    END
            ORDER BY
                key COLLATE "C" ASC, created_at ASC) as e order by key COLLATE "C" LIMIT $3'
        USING prefix_param, delimiter_param, max_keys, next_key_token, bucket_id, next_upload_token;
END;
$_$;


--
-- Name: list_objects_with_delimiter(text, text, text, integer, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text) RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;

    -- Configuration
    v_is_asc BOOLEAN;
    v_prefix TEXT;
    v_start TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';
    v_prefix := coalesce(prefix_param, '');
    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;
    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);

    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE "C")
    IF v_prefix = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix, 1) = delimiter_param THEN
        v_upper_bound := left(v_prefix, -1) || chr(ascii(delimiter_param) + 1);
    ELSE
        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'AND o.name COLLATE "C" < $3 ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'AND o.name COLLATE "C" >= $3 ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- ========================================================================
    -- SEEK INITIALIZATION: Determine starting position
    -- ========================================================================
    IF v_start = '' THEN
        IF v_is_asc THEN
            v_next_seek := v_prefix;
        ELSE
            -- DESC without cursor: find the last item in range
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;

            IF v_next_seek IS NOT NULL THEN
                v_next_seek := v_next_seek || delimiter_param;
            ELSE
                RETURN;
            END IF;
        END IF;
    ELSE
        -- Cursor provided: determine if it refers to a folder or leaf
        IF EXISTS (
            SELECT 1 FROM storage.objects o
            WHERE o.bucket_id = _bucket_id
              AND o.name COLLATE "C" LIKE v_start || delimiter_param || '%'
            LIMIT 1
        ) THEN
            -- Cursor refers to a folder
            IF v_is_asc THEN
                v_next_seek := v_start || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_start || delimiter_param;
            END IF;
        ELSE
            -- Cursor refers to a leaf object
            IF v_is_asc THEN
                v_next_seek := v_start || delimiter_param;
            ELSE
                v_next_seek := v_start;
            END IF;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= max_keys;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Emit and skip to next folder (no heap access needed)
            name := rtrim(v_common_prefix, delimiter_param);
            id := NULL;
            updated_at := NULL;
            created_at := NULL;
            last_accessed_at := NULL;
            metadata := NULL;
            RETURN NEXT;
            v_count := v_count + 1;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := left(v_common_prefix, -1) || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_common_prefix;
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query USING _bucket_id, v_next_seek,
                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := v_current.name;
                    EXIT;
                END IF;

                -- Emit file
                name := v_current.name;
                id := v_current.id;
                updated_at := v_current.updated_at;
                created_at := v_current.created_at;
                last_accessed_at := v_current.last_accessed_at;
                metadata := v_current.metadata;
                RETURN NEXT;
                v_count := v_count + 1;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := v_current.name || delimiter_param;
                ELSE
                    v_next_seek := v_current.name;
                END IF;

                EXIT WHEN v_count >= max_keys;
            END LOOP;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: operation(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.operation() RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN current_setting('storage.operation', true);
END;
$$;


--
-- Name: protect_delete(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.protect_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if storage.allow_delete_query is set to 'true'
    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN
        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'
            USING HINT = 'This prevents accidental data loss from orphaned objects.',
                  ERRCODE = '42501';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: search(text, text, integer, integer, integer, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text) RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;
    v_delimiter CONSTANT TEXT := '/';

    -- Configuration
    v_limit INT;
    v_prefix TEXT;
    v_prefix_lower TEXT;
    v_prefix_len INT;
    v_prefix_start INT;
    v_combined_levels INT;
    v_is_asc BOOLEAN;
    v_order_by TEXT;
    v_sort_order TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;
    v_skipped INT := 0;
BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_limit := LEAST(coalesce(limits, 100), 1500);
    v_prefix := coalesce(prefix, '') || coalesce(search, '');
    v_prefix_lower := lower(v_prefix);
    v_prefix_len := length(coalesce(prefix, ''));
    v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''), v_delimiter), 1), 1);
    v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);
    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);

    -- Validate sort column
    CASE lower(coalesce(sortcolumn, 'name'))
        WHEN 'name' THEN v_order_by := 'name';
        WHEN 'updated_at' THEN v_order_by := 'updated_at';
        WHEN 'created_at' THEN v_order_by := 'created_at';
        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
        ELSE v_order_by := 'name';
    END CASE;

    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

    -- ========================================================================
    -- NON-NAME SORTING: Use path_tokens approach
    -- ========================================================================
    IF v_order_by != 'name' THEN
        RETURN QUERY EXECUTE format(
            $sql$
            WITH folders AS (
                SELECT array_to_string(path_tokens[$1:$2], '/') AS folder
                FROM storage.objects
                WHERE objects.name ILIKE $3 || '%%'
                  AND bucket_id = $4
                  AND array_length(objects.path_tokens, 1) <> $2
                GROUP BY folder
                ORDER BY folder %s
            )
            (SELECT folder AS "name",
                   NULL::uuid AS id,
                   NULL::timestamptz AS updated_at,
                   NULL::timestamptz AS created_at,
                   NULL::timestamptz AS last_accessed_at,
                   NULL::jsonb AS metadata FROM folders)
            UNION ALL
            (SELECT array_to_string(path_tokens[$1:$2], '/') AS "name",
                   id, updated_at, created_at, last_accessed_at, metadata
             FROM storage.objects
             WHERE objects.name ILIKE $3 || '%%'
               AND bucket_id = $4
               AND array_length(objects.path_tokens, 1) = $2
             ORDER BY %I %s)
            LIMIT $5 OFFSET $6
            $sql$, v_sort_order, v_order_by, v_sort_order
        ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets;
        RETURN;
    END IF;

    -- ========================================================================
    -- NAME SORTING: Hybrid skip-scan with batch optimization
    -- ========================================================================

    -- Calculate upper bound for prefix filtering
    IF v_prefix_lower = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
    ELSE
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'AND lower(o.name) COLLATE "C" < $3 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'AND lower(o.name) COLLATE "C" >= $3 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- Initialize seek position
    IF v_is_asc THEN
        v_next_seek := v_prefix_lower;
    ELSE
        -- DESC: find the last item in range first (static SQL)
        IF v_upper_bound IS NOT NULL THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower AND lower(o.name) COLLATE "C" < v_upper_bound
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSIF v_prefix_lower <> '' THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSE
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        END IF;

        IF v_peek_name IS NOT NULL THEN
            v_next_seek := lower(v_peek_name) || v_delimiter;
        ELSE
            RETURN;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= v_limit;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix_lower <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Handle offset, emit if needed, skip to next folder
            IF v_skipped < offsets THEN
                v_skipped := v_skipped + 1;
            ELSE
                name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);
                id := NULL;
                updated_at := NULL;
                created_at := NULL;
                last_accessed_at := NULL;
                metadata := NULL;
                RETURN NEXT;
                v_count := v_count + 1;
            END IF;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
            ELSE
                v_next_seek := lower(v_common_prefix);
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := lower(v_current.name);
                    EXIT;
                END IF;

                -- Handle offset skipping
                IF v_skipped < offsets THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    -- Emit file
                    name := substring(v_current.name from v_prefix_len + 1);
                    id := v_current.id;
                    updated_at := v_current.updated_at;
                    created_at := v_current.created_at;
                    last_accessed_at := v_current.last_accessed_at;
                    metadata := v_current.metadata;
                    RETURN NEXT;
                    v_count := v_count + 1;
                END IF;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := lower(v_current.name) || v_delimiter;
                ELSE
                    v_next_seek := lower(v_current.name);
                END IF;

                EXIT WHEN v_count >= v_limit;
            END LOOP;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: search_by_timestamp(text, text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_cursor_op text;
    v_query text;
    v_prefix text;
    v_sort_order text;
    v_sort_column text;
BEGIN
    v_prefix := coalesce(p_prefix, '');

    -- Defense-in-depth: this function is independently reachable and must
    -- not trust p_sort_order/p_sort_column to already be validated by a
    -- caller. Normalize to the same strict allow-list storage.search_v2
    -- uses before interpolating anything into dynamic SQL below.
    v_sort_order := lower(coalesce(p_sort_order, 'asc'));
    IF v_sort_order NOT IN ('asc', 'desc') THEN
        v_sort_order := 'asc';
    END IF;

    v_sort_column := lower(coalesce(p_sort_column, 'updated_at'));
    IF v_sort_column NOT IN ('updated_at', 'created_at') THEN
        v_sort_column := 'updated_at';
    END IF;

    IF v_sort_order = 'asc' THEN
        v_cursor_op := '>';
    ELSE
        v_cursor_op := '<';
    END IF;

    v_query := format($sql$
        WITH raw_objects AS (
            SELECT
                o.name AS obj_name,
                o.id AS obj_id,
                o.updated_at AS obj_updated_at,
                o.created_at AS obj_created_at,
                o.last_accessed_at AS obj_last_accessed_at,
                o.metadata AS obj_metadata,
                storage.get_common_prefix(o.name, $1, '/') AS common_prefix
            FROM storage.objects o
            WHERE o.bucket_id = $2
              AND o.name COLLATE "C" LIKE $1 || '%%'
        ),
        -- Aggregate common prefixes (folders)
        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior
        aggregated_prefixes AS (
            SELECT
                rtrim(common_prefix, '/') AS name,
                NULL::uuid AS id,
                MIN(obj_created_at) AS updated_at,
                MIN(obj_created_at) AS created_at,
                NULL::timestamptz AS last_accessed_at,
                NULL::jsonb AS metadata,
                TRUE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NOT NULL
            GROUP BY common_prefix
        ),
        leaf_objects AS (
            SELECT
                obj_name AS name,
                obj_id AS id,
                obj_updated_at AS updated_at,
                obj_created_at AS created_at,
                obj_last_accessed_at AS last_accessed_at,
                obj_metadata AS metadata,
                FALSE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NULL
        ),
        combined AS (
            SELECT * FROM aggregated_prefixes
            UNION ALL
            SELECT * FROM leaf_objects
        ),
        filtered AS (
            SELECT *
            FROM combined
            WHERE (
                $5 = ''
                OR ROW(
                    date_trunc('milliseconds', %I),
                    name COLLATE "C"
                ) %s ROW(
                    COALESCE(NULLIF($6, '')::timestamptz, 'epoch'::timestamptz),
                    $5
                )
            )
        )
        SELECT
            split_part(name, '/', $3) AS key,
            name,
            id,
            updated_at,
            created_at,
            last_accessed_at,
            metadata
        FROM filtered
        ORDER BY
            COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz) %s,
            name COLLATE "C" %s
        LIMIT $4
    $sql$,
        v_sort_column,
        v_cursor_op,
        v_sort_column,
        v_sort_order,
        v_sort_order
    );

    RETURN QUERY EXECUTE v_query
    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after;
END;
$_$;


--
-- Name: search_v2(text, text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_sort_col text;
    v_sort_ord text;
    v_limit int;
BEGIN
    -- Cap limit to maximum of 1500 records
    v_limit := LEAST(coalesce(limits, 100), 1500);

    -- Validate and normalize sort_order
    v_sort_ord := lower(coalesce(sort_order, 'asc'));
    IF v_sort_ord NOT IN ('asc', 'desc') THEN
        v_sort_ord := 'asc';
    END IF;

    -- Validate and normalize sort_column
    v_sort_col := lower(coalesce(sort_column, 'name'));
    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN
        v_sort_col := 'name';
    END IF;

    -- Route to appropriate implementation
    IF v_sort_col = 'name' THEN
        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))
        RETURN QUERY
        SELECT
            split_part(l.name, '/', levels) AS key,
            l.name AS name,
            l.id,
            l.updated_at,
            l.created_at,
            l.last_accessed_at,
            l.metadata
        FROM storage.list_objects_with_delimiter(
            bucket_name,
            coalesce(prefix, ''),
            '/',
            v_limit,
            start_after,
            '',
            v_sort_ord
        ) l;
    ELSE
        -- Use aggregation approach for timestamp sorting
        -- Not efficient for large datasets but supports correct pagination
        RETURN QUERY SELECT * FROM storage.search_by_timestamp(
            prefix, bucket_name, v_limit, levels, start_after,
            v_sort_ord, v_sort_col, sort_column_after
        );
    END IF;
END;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW; 
END;
$$;


