--
-- Name: pump_calculator_products; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pump_calculator_products AS
 SELECT id,
    category,
    brand,
    name_en,
    name_ar,
    power_hp,
    power_kw,
    specs_en,
    specs_ar,
    price,
    currency,
    image_url,
    images,
    datasheet_url,
    curve_data,
    in_stock,
    published
   FROM public.products
  WHERE ((category = ANY (ARRAY['well_motors'::text, 'pumps'::text])) AND (published = true) AND (in_stock = true))
  ORDER BY category, brand, power_hp;


