--
-- Name: supplier_discounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_discounts (
    category text NOT NULL,
    brand text NOT NULL,
    supplier_discount_pct numeric DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sale_discount_pct numeric DEFAULT 0 NOT NULL,
    CONSTRAINT supplier_discounts_sale_discount_pct_check CHECK (((sale_discount_pct >= (0)::numeric) AND (sale_discount_pct <= (100)::numeric))),
    CONSTRAINT supplier_discounts_sale_le_supplier_check CHECK ((sale_discount_pct <= supplier_discount_pct)),
    CONSTRAINT supplier_discounts_supplier_discount_pct_check CHECK (((supplier_discount_pct >= (0)::numeric) AND (supplier_discount_pct <= (100)::numeric)))
);


--
-- Name: COLUMN supplier_discounts.sale_discount_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.supplier_discounts.sale_discount_pct IS 'نسبة الخصم اللي بيتباع بيها للعميل (خصم بيع)، لازم تكون <= supplier_discount_pct عشان الشركة متبيعش بخسارة.';


