20260713105217	{"\n-- Price refresh for the existing DELIXI T4 (3ph in / 3ph out, 380V) line —\n-- same physical model line, matched by KW rating (more reliable than the\n-- HP label, which rounds slightly differently between price lists).\n-- Also tags each row with its exact CDI-SPDG model code.\nUPDATE public.products AS p\nSET price = v.new_price,\n    model_available = v.model,\n    updated_at = now()\nFROM (VALUES\n  (0.75::numeric, 8150::numeric,  'CDI-SPDG0R7T4'),\n  (1.5,  8450,  'CDI-SPDG1R5T4'),\n  (2.2,  10100, 'CDI-SPDG2R2T4'),\n  (4,    11150, 'CDI-SPDG4R0T4'),\n  (5.5,  14500, 'CDI-SPDG5R5T4'),\n  (7.5,  16000, 'CDI-SPDG7R5T4'),\n  (10,   21000, 'CDI-SPDG011T4'),\n  (15,   24000, 'CDI-SPDG0151T4'),\n  (18.5, 31700, 'CDI-SPDG018.5T4'),\n  (22,   38200, 'CDI-SPDG022T4'),\n  (30,   48200, 'CDI-SPDG030T4'),\n  (37,   57600, 'CDI-SPDG037T4'),\n  (45,   70150, 'CDI-SPDG045T4'),\n  (55,   87450, 'CDI-SPDG055T4'),\n  (75,   99550, 'CDI-SPDG075T4'),\n  (90,   122000,'CDI-SPDG090T4'),\n  (110,  139850,'CDI-SPDG110T4'),\n  (132,  181800,'CDI-SPDG132T4')\n) AS v(kw, new_price, model)\nWHERE p.category = 'inverters'\n  AND p.brand ILIKE 'Delixi'\n  AND (regexp_match(p.specs_ar, '([\\\\d.]+)\\\\s*KW'))[1]::numeric = v.kw;\n"}	update_delixi_t4_inverter_prices_and_models	alhussieni95@gmail.com	\N	\N
20260713105255	{"\n-- New DELIXI inverter models from the updated Rees/Eamar price list.\n-- Each row is tagged with its exact CDI-SPDG model code in model_available.\n-- Kept unit + specs_ar consistent with the existing 18 Delixi rows so the\n-- family-detail page groups them correctly under category+brand.\ninsert into public.products (category, brand, name_ar, specs_ar, model_available, power_kw, power_hp, unit, price, notes, sort_order, published) values\n-- T4 series: two additional high-power models\n('inverters','Delixi','إنفرتر Delixi','215 HP - 160 KW','CDI-SPDG160T4',160,215,'قطعة',242950,null,160,true),\n('inverters','Delixi','إنفرتر Delixi','250 HP - 185 KW','CDI-SPDG185T4',185,250,'قطعة',276800,null,161,true),\n\n-- SS2 series: 1-phase DC input, 1-phase output\n('inverters','Delixi','إنفرتر Delixi','1 HP - 0.7 KW','CDI-SPDG0R7SS2',0.7,1,'قطعة',8150,'دخل تيار مستمر أحادي الطور - خرج أحادي الطور',162,true),\n('inverters','Delixi','إنفرتر Delixi','2 HP - 1.5 KW','CDI-SPDG1R5SS2',1.5,2,'قطعة',9700,'دخل تيار مستمر أحادي الطور - خرج أحادي الطور',163,true),\n('inverters','Delixi','إنفرتر Delixi','3 HP - 2.2 KW','CDI-SPDG2R2SS2',2.2,3,'قطعة',13450,'دخل تيار مستمر أحادي الطور - خرج أحادي الطور',164,true),\n('inverters','Delixi','إنفرتر Delixi','5.5 HP - 4 KW','CDI-SPDG4R0SS2',4,5.5,'قطعة',14400,'دخل تيار مستمر أحادي الطور - خرج أحادي الطور',165,true),\n\n-- S2 series: 1-phase DC input, 3-phase output\n('inverters','Delixi','إنفرتر Delixi','1 HP - 0.7 KW','CDI-SPDG0R7S2',0.7,1,'قطعة',8500,'دخل تيار مستمر أحادي الطور - خرج ثلاثي الطور',166,true),\n('inverters','Delixi','إنفرتر Delixi','2 HP - 1.5 KW','CDI-SPDG1R5S2',1.5,2,'قطعة',8900,'دخل تيار مستمر أحادي الطور - خرج ثلاثي الطور',167,true),\n('inverters','Delixi','إنفرتر Delixi','3 HP - 2.2 KW','CDI-SPDG2R2S2',2.2,3,'قطعة',10600,'دخل تيار مستمر أحادي الطور - خرج ثلاثي الطور',168,true),\n('inverters','Delixi','إنفرتر Delixi','5.5 HP - 4 KW','CDI-SPDG4R0S2',4,5.5,'قطعة',13650,'دخل تيار مستمر أحادي الطور - خرج ثلاثي الطور',169,true),\n\n-- T2 series: 3-phase DC input, 3-phase output, 200-400V\n('inverters','Delixi','إنفرتر Delixi','5.5 HP - 4 KW','CDI-SPDG4R0T2',4,5.5,'قطعة',15050,'دخل تيار مستمر ثلاثي الطور - خرج ثلاثي الطور (200-400V)',170,true),\n\n-- C1 series: high-power line (57,850 - 205,250 EGP)\n('inverters','Delixi','إنفرتر Delixi','40 HP - 30 KW','CDI-SPDG030C1',30,40,'قطعة',57850,null,171,true),\n('inverters','Delixi','إنفرتر Delixi','50 HP - 37 KW','CDI-SPDG037C1',37,50,'قطعة',66250,null,172,true),\n('inverters','Delixi','إنفرتر Delixi','60 HP - 45 KW','CDI-SPDG045C1',45,60,'قطعة',78250,null,173,true),\n('inverters','Delixi','إنفرتر Delixi','75 HP - 55 KW','CDI-SPDG055C1',55,75,'قطعة',96450,null,174,true),\n('inverters','Delixi','إنفرتر Delixi','100 HP - 75 KW','CDI-SPDG075C1',75,100,'قطعة',113450,null,175,true),\n('inverters','Delixi','إنفرتر Delixi','125 HP - 90 KW','CDI-SPDG090C1',90,125,'قطعة',139700,null,176,true),\n('inverters','Delixi','إنفرتر Delixi','150 HP - 110 KW','CDI-SPDG110C1',110,150,'قطعة',159050,null,177,true),\n('inverters','Delixi','إنفرتر Delixi','175 HP - 132 KW','CDI-SPDG132C1',132,175,'قطعة',205250,null,178,true);\n"}	add_new_delixi_inverter_models	alhussieni95@gmail.com	\N	\N
20260713105334	{"\n-- Bug fix: model_available must be the SERIES (T4 / SS2 / S2 / T2 / C1) so\n-- the family-detail page groups same-series power variants together with\n-- a power picker. It was mistakenly set to the fully-unique part number,\n-- which made every single variant its own one-item \\"family\\". The exact\n-- part number is preserved in `notes` instead.\nUPDATE public.products SET\n  notes = COALESCE(notes || ' — ', '') || 'الموديل: ' || model_available,\n  model_available = CASE\n    WHEN model_available LIKE '%SS2' THEN 'SS2'\n    WHEN model_available LIKE '%S2'  THEN 'S2'\n    WHEN model_available LIKE '%T2'  THEN 'T2'\n    WHEN model_available LIKE '%T4'  THEN 'T4'\n    WHEN model_available LIKE '%C1'  THEN 'C1'\n    ELSE model_available\n  END\nWHERE brand ILIKE 'Delixi' AND model_available LIKE 'CDI-%';\n"}	fix_delixi_model_grouping_key	alhussieni95@gmail.com	\N	\N
