20260723092327	{"create table if not exists calc_settings (\n  id int primary key default 1,\n  suggestions_enabled boolean not null default true,\n  preferred_well_motor_brand text,\n  preferred_pump_brand text,\n  preferred_inverter_brand text,\n  preferred_pipe_brand text,\n  updated_at timestamptz not null default now(),\n  constraint calc_settings_single_row check (id = 1)\n);\n\ninsert into calc_settings (id) values (1) on conflict (id) do nothing;\n\nalter table calc_settings enable row level security;\n\ndrop policy if exists \\"Public can read calc settings\\" on calc_settings;\ncreate policy \\"Public can read calc settings\\" on calc_settings\n  for select using (true);\n\ndrop policy if exists \\"Admins can update calc settings\\" on calc_settings;\ncreate policy \\"Admins can update calc settings\\" on calc_settings\n  for update using (is_admin());\n"}	create_calc_settings	alhussieni95@gmail.com	\N	\N
