20260801120159	{"alter table products add column if not exists curve_data jsonb;"}	add_curve_data_column	alhussieni95@gmail.com	\N	\N
20260802055724	{"\n-- 1) جدول تحكم الأدمن في إظهار/إخفاء تصنيفات كاملة + تحديد القسم الرئيسي/الفرعي لكل تصنيف\nCREATE TABLE IF NOT EXISTS public.category_settings (\n  category_key   text PRIMARY KEY,          -- يطابق قيمة عمود products.category\n  display_name_ar text NOT NULL,\n  main_section    text NOT NULL,            -- مثال: 'irrigation_wells' / 'inverters' / 'panels' ...\n  sub_section     text,                     -- مثال: 'pumps' / 'well_motors' / 'ongrid' / 'offgrid' / 'pump_vfd'\n  visible         boolean NOT NULL DEFAULT true,\n  sort_order      integer NOT NULL DEFAULT 100,\n  updated_at      timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.category_settings ENABLE ROW LEVEL SECURITY;\n\n-- قراءة عامة (الموقع محتاج يعرف أي تصنيف ظاهر) — الكتابة تتم من الباك إند بصلاحية service role زي باقي جداول الإدارة (admin_secret, pricing_config)\nCREATE POLICY \\"public can read category settings\\"\n  ON public.category_settings FOR SELECT\n  USING (true);\n\n-- تعبئة القيم الحالية مبنية على التوزيع الفعلي للمنتجات + التصور المتفق عليه\nINSERT INTO public.category_settings (category_key, display_name_ar, main_section, sub_section, visible, sort_order) VALUES\n  ('well_motors',   'الموتورات',              'irrigation_wells', 'well_motors', true, 10),\n  ('pumps',         'الطلمبات',                'irrigation_wells', 'pumps',       true, 20),\n  ('pipes',         'المواسير',                'irrigation_wells', 'pipes',       true, 30),\n  ('inverters',     'إنفرتر بامب / VFD',       'inverters',        'pump_vfd',    true, 10),\n  ('offgrid',       'إنفرتر أوف جريد',         'inverters',        'offgrid',     true, 20),\n  -- placeholder لحد ما تتضاف منتجات فعلية (هايبرد/أون جريد) — مخفي افتراضيًا\n  ('ongrid',        'إنفرتر أون جريد',         'inverters',        'ongrid',      false, 30),\n  ('hybrid',        'إنفرتر هايبرد',           'inverters',        'hybrid',      false, 40),\n  ('panels',        'الألواح الشمسية',         'panels',           NULL,          true, 10),\n  ('structures',    'هياكل',                   'install_components', NULL,        true, 10),\n  ('cables',        'كابلات',                  'install_components', NULL,        true, 20),\n  ('combiners',     'صناديق تجميع',            'install_components', NULL,        true, 30),\n  ('accessories',   'إكسسوارات',               'install_components', NULL,        true, 40),\n  ('street_lights', 'إنارة شوارع شمسية',       'standalone_lighting', NULL,       true, 10),\n  ('flood_lights',  'كشافات شمسية',            'standalone_lighting', NULL,       true, 20),\n  ('garden_lights', 'إضاءة حدائق شمسية',       'standalone_lighting', NULL,       true, 30),\n  ('solar_safety',  'سلامة الطرق الشمسية',     'standalone_lighting', NULL,       true, 40),\n  ('solar_kits',    'كيت إضاءة منزلي',         'standalone_lighting', NULL,       true, 50),\n  ('batteries',     'بطاريات وتخزين الطاقة',   'batteries',        NULL,          true, 10)\nON CONFLICT (category_key) DO NOTHING;\n\n-- 2) Backfill: استخراج القدرة الحصانية من specs_ar للماركات اللي مالهاش power_hp مسجل\n-- تحقق مسبق (نُفّذ فعليًا قبل هذا الملف): 240 من 240 صف تطابقوا مع النمط بدون استثناء\nUPDATE public.products\nSET power_hp = (regexp_match(specs_ar, '(\\\\d+(\\\\.\\\\d+)?)\\\\s*حصان'))[1]::numeric\nWHERE power_hp IS NULL\n  AND category IN ('pumps','well_motors')\n  AND specs_ar ~ '\\\\d+(\\\\.\\\\d+)?\\\\s*حصان';\n\n-- تعبئة power_kw كتقريب هندسي حيث لسه فاضي (1 حصان ≈ 0.746 كيلوواط)، بس للصفوف اللي اتعبت للتو\nUPDATE public.products\nSET power_kw = ROUND(power_hp * 0.746, 2)\nWHERE power_kw IS NULL\n  AND power_hp IS NOT NULL\n  AND category IN ('pumps','well_motors')\n  AND specs_ar ~ '\\\\d+(\\\\.\\\\d+)?\\\\s*حصان';\n"}	category_visibility_and_hp_backfill	alhussieni95@gmail.com	\N	\N
20260802060224	{"\n-- إصلاح: إضافة سياسات كتابة مطابقة لنفس نمط is_admin() المستخدم في باقي جداول الإدارة\nCREATE POLICY \\"Admins can insert category settings\\"\n  ON public.category_settings FOR INSERT\n  WITH CHECK (is_admin());\n\nCREATE POLICY \\"Admins can update category settings\\"\n  ON public.category_settings FOR UPDATE\n  USING (is_admin())\n  WITH CHECK (is_admin());\n\nCREATE POLICY \\"Admins can delete category settings\\"\n  ON public.category_settings FOR DELETE\n  USING (is_admin());\n\n-- إصلاح: شيل عمود الاسم العربي المكرر — الجدول ده لمنطق الظهور/الترتيب بس، مش لأسماء العرض (دي فضّل مسؤولية نظام i18n الموجود في app.js عشان منتفاداش مصدرين مختلفين للنص)\nALTER TABLE public.category_settings DROP COLUMN IF EXISTS display_name_ar;\n"}	fix_category_settings_rls_and_simplify	alhussieni95@gmail.com	\N	\N
20260802110259	{"\n-- عمود قدرة مخصّص للألواح بالوات (مش كيلوواط، عشان منخلطش المقياس مع الإنفرترات/الموتورات)\nALTER TABLE public.products ADD COLUMN IF NOT EXISTS power_w numeric;\n\n-- استخراج قدرة الألواح: أول رقم قبل \\"وات\\" (لو فيه رينج زي \\"615-605 وات\\" ياخد أول رقم: 615)\nUPDATE public.products\nSET power_w = (regexp_match(specs_ar, '(\\\\d+(\\\\.\\\\d+)?)\\\\s*(-\\\\s*\\\\d+(\\\\.\\\\d+)?\\\\s*)?وات'))[1]::numeric\nWHERE category = 'panels'\n  AND power_w IS NULL\n  AND specs_ar ~ '\\\\d+(\\\\.\\\\d+)?\\\\s*وات';\n\n-- استخراج قدرة إنفرترات VEICHI (الحصان والكيلوواط مع بعض من نفس النص، صيغة \\"X HP - Y KW\\")\nUPDATE public.products\nSET power_hp = (regexp_match(specs_ar, '(\\\\d+(\\\\.\\\\d+)?)\\\\s*HP'))[1]::numeric,\n    power_kw = (regexp_match(specs_ar, 'HP\\\\s*-\\\\s*(\\\\d+(\\\\.\\\\d+)?)\\\\s*KW'))[1]::numeric\nWHERE category = 'inverters'\n  AND brand = 'VEICHI'\n  AND power_kw IS NULL\n  AND specs_ar ~ '\\\\d+(\\\\.\\\\d+)?\\\\s*HP\\\\s*-\\\\s*\\\\d+(\\\\.\\\\d+)?\\\\s*KW';\n"}	backfill_panel_watts_and_veichi_inverter_kw	alhussieni95@gmail.com	\N	\N
20260802194237	{"\ncreate or replace view pump_calculator_products as\nselect\n  id,\n  category,          -- 'well_motors' or 'pumps'\n  brand,\n  name_en,\n  name_ar,\n  power_hp,\n  power_kw,\n  specs_en,\n  specs_ar,\n  price,\n  currency,\n  image_url,\n  images,\n  datasheet_url,\n  curve_data,\n  in_stock,\n  published\nfrom products\nwhere category in ('well_motors','pumps')\n  and published = true\n  and in_stock = true\norder by category, brand, power_hp;\n"}	create_pump_calculator_live_view	alhussieni95@gmail.com	\N	\N
20260803073125	{"alter table public.products\n  add column if not exists sku            text,\n  add column if not exists description    text,\n  add column if not exists key_features   text[],\n  add column if not exists applications   text[],\n  add column if not exists rating         numeric(2,1),\n  add column if not exists review_count   int,\n  add column if not exists warranty_years int,\n  add column if not exists warranty_notes text,\n  add column if not exists temp_min       numeric,\n  add column if not exists temp_max       numeric,\n  add column if not exists weight_kg      numeric,\n  add column if not exists ip_rating      text,\n  add column if not exists cycle_life     text,\n  add column if not exists capacity_ah    numeric,\n  add column if not exists voltage_v      numeric;"}	add_product_detail_optional_fields	alhussieni95@gmail.com	\N	\N
20260803212002	{"alter table public.products\n  add column if not exists power_kw           numeric,   -- inverters\n  add column if not exists surge_capacity_pct numeric,   -- inverters, e.g. 1.5 = 150%\n  add column if not exists pv_voc_max         numeric,   -- inverters\n  add column if not exists pv_mppt_min        numeric,   -- inverters\n  add column if not exists pv_mppt_max        numeric,   -- inverters\n  add column if not exists dod                numeric,   -- batteries, 0-1\n  add column if not exists power_watt         numeric,   -- panels\n  add column if not exists vimp               numeric,   -- panels\n  add column if not exists voc                numeric,   -- panels (also reused for reference; distinct from pv_voc_max on inverters)\n  add column if not exists iimp               numeric,   -- panels\n  add column if not exists isc                numeric;   -- panels\n"}	add_offgrid_technical_specs	alhussieni95@gmail.com	\N	\N
20260805054058	{"\n-- 1) Extend calc_settings with off-grid controls\nalter table public.calc_settings\n  add column if not exists offgrid_enabled boolean not null default true,\n  add column if not exists preferred_offgrid_inverter_brand text,\n  add column if not exists preferred_offgrid_battery_brand text,\n  add column if not exists preferred_offgrid_panel_brand text;\n\n-- 2) System-offer presets (\\"منظومات المنازل المتاحة\\") — admin managed\ncreate table if not exists public.offgrid_presets (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  description text,\n  items jsonb not null default '[]'::jsonb,  -- [{\\"load\\":\\"ثلاجة\\",\\"count\\":1}, ...] load names must match the calculator's device catalogue\n  sort_order int not null default 0,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\nalter table public.offgrid_presets enable row level security;\n\ndrop policy if exists \\"Public can read active offgrid presets\\" on public.offgrid_presets;\ncreate policy \\"Public can read active offgrid presets\\" on public.offgrid_presets\n  for select using (is_active = true or is_admin());\n\ndrop policy if exists \\"Admins can insert offgrid presets\\" on public.offgrid_presets;\ncreate policy \\"Admins can insert offgrid presets\\" on public.offgrid_presets\n  for insert with check (is_admin());\n\ndrop policy if exists \\"Admins can update offgrid presets\\" on public.offgrid_presets;\ncreate policy \\"Admins can update offgrid presets\\" on public.offgrid_presets\n  for update using (is_admin()) with check (is_admin());\n\ndrop policy if exists \\"Admins can delete offgrid presets\\" on public.offgrid_presets;\ncreate policy \\"Admins can delete offgrid presets\\" on public.offgrid_presets\n  for delete using (is_admin());\n"}	offgrid_admin_controls	alhussieni95@gmail.com	\N	\N
20260806191206	{"update products set specs_ar='640 وات - باي فيشيال - Voc 53.9V - Vimp 45.2V', description='لوح شمسي Aiko Solar بقدرة 640 وات، بتقنية ثنائية الوجه (Bifacial)، بتاخد إضاءة منعكسة من الأرضية أو السقف وتزود إنتاجية الطاقة اليومية. مناسب للتركيبات المنزلية والتجارية ومزارع الطاقة الشمسية على الشبكة أو خارجها.', key_features=ARRAY['خلايا سيليكون عالية الكفاءة','إطار ألومنيوم مقوى لمقاومة الرياح والأحمال','اكتساب إنتاجية إضافية من الوجه الخلفي (Bifacial Gain)','معامل تدهور أداء منخفض سنويًا']::text[], updated_at=now() where id='2f4d3155-bd4b-4923-8e59-5291e9cd450a';\nupdate products set specs_ar='645 وات - باي فيشيال - Voc 53.9V - Vimp 45.2V', description='لوح شمسي Aiko Solar بقدرة 645 وات، بتقنية ثنائية الوجه (Bifacial)، بتاخد إضاءة منعكسة من الأرضية أو السقف وتزود إنتاجية الطاقة اليومية. مناسب للتركيبات المنزلية والتجارية ومزارع الطاقة الشمسية على الشبكة أو خارجها.', key_features=ARRAY['خلايا سيليكون عالية الكفاءة','إطار ألومنيوم مقوى لمقاومة الرياح والأحمال','اكتساب إنتاجية إضافية من الوجه الخلفي (Bifacial Gain)','معامل تدهور أداء منخفض سنويًا']::text[], updated_at=now() where id='adcd7ed2-55fc-41f1-82d2-06c0d029caa7';\nupdate products set specs_ar='715 وات - باي فيشيال', description='لوح شمسي Astronergy بقدرة 715 وات، بتقنية ثنائية الوجه (Bifacial)، بتاخد إضاءة منعكسة من الأرضية أو السقف وتزود إنتاجية الطاقة اليومية. مناسب للتركيبات المنزلية والتجارية ومزارع الطاقة الشمسية على الشبكة أو خارجها.', key_features=ARRAY['خلايا سيليكون عالية الكفاءة','إطار ألومنيوم مقوى لمقاومة الرياح والأحمال','اكتساب إنتاجية إضافية من الوجه الخلفي (Bifacial Gain)','معامل تدهور أداء منخفض سنويًا']::text[], updated_at=now() where id='64b9ea34-1a0f-4829-831e-9a405482a19e';\nupdate products set specs_ar='615 وات - باي فيشيال - Voc 49.6V - Vimp 41.7V', description='لوح شمسي Canadian Solar بقدرة 615 وات، بتقنية ثنائية الوجه (Bifacial)، بتاخد إضاءة منعكسة من الأرضية أو السقف وتزود إنتاجية الطاقة اليومية. مناسب للتركيبات المنزلية والتجارية ومزارع الطاقة الشمسية على الشبكة أو خارجه