20260808055023	{"update products set specs_ar='5.5 HP - 4 KW - تيار مقنن 10A - أقصى قدرة ألواح 5.6 كيلوواط', updated_at=now() where id='2cbfa574-e038-4646-b5be-ec4430cb1f6c';\nupdate products set specs_ar='7.5 HP - 5.5 KW - تيار مقنن 13A - أقصى قدرة ألواح 8 كيلوواط', updated_at=now() where id='327e8cdf-ee94-4483-99b5-f83ec2581e74';\nupdate products set specs_ar='10 HP - 7.5 KW - تيار مقنن 17A - أقصى قدرة ألواح 10 كيلوواط', updated_at=now() where id='5a809e4e-ca38-403e-953c-6e3ce9f9ed0d';\nupdate products set specs_ar='15 HP - 11 KW - تيار مقنن 25A - أقصى قدرة ألواح 14.3 كيلوواط', updated_at=now() where id='42593330-dfb7-48ff-82c1-1b0c258feefe';\nupdate products set specs_ar='20 HP - 15 KW - تيار مقنن 32A - أقصى قدرة ألواح 19.5 كيلوواط', updated_at=now() where id='02da694e-eac6-4892-8694-fa91b42b4d1d';\nupdate products set specs_ar='25 HP - 18.5 KW - تيار مقنن 38A - أقصى قدرة ألواح 23.4 كيلوواط', updated_at=now() where id='56f362a6-dd9f-459c-86ac-10380cb9f53e';\nupdate products set specs_ar='30 HP - 22 KW - تيار مقنن 45A - أقصى قدرة ألواح 28.6 كيلوواط', updated_at=now() where id='5d27ea91-68e3-4088-9247-7e2178a8c65d';\nupdate products set specs_ar='40 HP - 30 KW - تيار مقنن 60A - أقصى قدرة ألواح 39 كيلوواط', updated_at=now() where id='8c052c0f-d6fd-4cf2-a379-2c5996fda330';\nupdate products set specs_ar='50 HP - 37 KW - تيار مقنن 75A - أقصى قدرة ألواح 48.1 كيلوواط', updated_at=now() where id='42fd5669-d5bb-4cd3-97f6-977ef36ce0ce';\nupdate products set specs_ar='60 HP - 45 KW - تيار مقنن 90A - أقصى قدرة ألواح 58.5 كيلوواط', updated_at=now() where id='d327ebab-0d8b-4b0e-b774-b04aff63ca83';\nupdate products set specs_ar='75 HP - 55 KW - تيار مقنن 110A - أقصى قدرة ألواح 71.5 كيلوواط', updated_at=now() where id='ade65c70-936d-4f4f-933d-cee575eb71f0';\nupdate products set specs_ar='100 HP - 75 KW - تيار مقنن 150A - أقصى قدرة ألواح 97.5 كيلوواط', updated_at=now() where id='94949ece-357e-4406-83f3-a1638fa7d559';\nupdate products set specs_ar='125 HP - 90 KW - تيار مقنن 180A - أقصى قدرة ألواح 121.5 كيلوواط', updated_at=now() where id='c7873464-f28b-47c7-a261-7cf91b126a1b';\nupdate products set specs_ar='150 HP - 110 KW - تيار مقنن 210A - أقصى قدرة ألواح 148.5 كيلوواط', updated_at=now() where id='b27b9692-1478-413a-8838-c7cb8c39722c';\nupdate products set specs_ar='180 HP - 132 KW - تيار مقنن 250A - أقصى قدرة ألواح 178.2 كيلوواط', updated_at=now() where id='468cb67c-3030-4b32-81a2-d30884019f0f';\nupdate products set specs_ar='225 HP - 160 KW - تيار مقنن 310A - أقصى قدرة ألواح 216 كيلوواط', updated_at=now() where id='e4845bf1-ada0-4298-98b8-3147351b90bc';\nupdate products set specs_ar='250 HP - 185 KW - تيار مقنن 380A - أقصى قدرة ألواح 249.75 كيلوواط', updated_at=now() where id='298dd8f0-cbfa-4a24-85c4-a7e8b581d99e';\nupdate products set specs_ar='275 HP - 200 KW - تيار مقنن 415A - أقصى قدرة ألواح 270 كيلوواط', updated_at=now() where id='c0355e33-49ae-4638-b438-abb47535c212';\nupdate products set specs_ar='300 HP - 220 KW - تيار مقنن 470A - أقصى قدرة ألواح 297 كيلوواط', updated_at=now() where id='f138666f-41c9-4415-a104-f474b17d741d';"}	si23_specs_current_maxsolar	alhussieni95@gmail.com	\N	\N
20260809023228	{"alter table public.products add column if not exists pump_type text;\n\nupdate products set pump_type='غاطس', updated_at=now()\nwhere category='pumps' and brand='SP Sterapump'\n  and model_available in ('9S.P 110','Nirol','S.P 120','S.P 125','S.P 160','S.P 17','S.P 30','S.P 46','S.P 60','S.P 77','S.P 95','SDM-SD');\n\nupdate products set pump_type='تسميد', updated_at=now()\nwhere category='pumps' and brand='SP Sterapump' and model_available='المواتير السطحي (التسميد)';\n\nupdate products set pump_type='صرف', updated_at=now()\nwhere category='pumps' and brand='SP Sterapump' and model_available='مواتير الصرف';"}	add_pump_type	alhussieni95@gmail.com	\N	\N
20260810093041	{"ALTER TABLE products\n  ADD COLUMN IF NOT EXISTS description_ar text,\n  ADD COLUMN IF NOT EXISTS description_en text,\n  ADD COLUMN IF NOT EXISTS description_es text,\n  ADD COLUMN IF NOT EXISTS description_zh text,\n  ADD COLUMN IF NOT EXISTS key_features_ar text[],\n  ADD COLUMN IF NOT EXISTS key_features_en text[],\n  ADD COLUMN IF NOT EXISTS key_features_es text[],\n  ADD COLUMN IF NOT EXISTS key_features_zh text[],\n  ADD COLUMN IF NOT EXISTS applications_ar text[],\n  ADD COLUMN IF NOT EXISTS applications_en text[],\n  ADD COLUMN IF NOT EXISTS applications_es text[],\n  ADD COLUMN IF NOT EXISTS applications_zh text[],\n  ADD COLUMN IF NOT EXISTS notes_ar text,\n  ADD COLUMN IF NOT EXISTS notes_en text,\n  ADD COLUMN IF NOT EXISTS notes_es text,\n  ADD COLUMN IF NOT EXISTS notes_zh text;\n\n-- Seed the _ar columns from the existing (Arabic-only) legacy columns\nUPDATE products SET\n  description_ar = description,\n  key_features_ar = key_features,\n  applications_ar = applications,\n  notes_ar = notes;\n"}	add_multilang_columns_description_features_applications_notes	alhussieni95@gmail.com	\N	\N
20260810192057	{"ALTER TABLE products\n  ADD COLUMN IF NOT EXISTS motor_material text,\n  ADD COLUMN IF NOT EXISTS diameter_inch numeric;\n\n-- Extract mounting diameter (inches) for every well_motors row — the\n-- pattern \\"قطر التنصيب X\\"\\" appears consistently across all brands.\nUPDATE products\nSET diameter_inch = (regexp_match(specs_ar, 'قطر التنصيب (\\\\d+(?:\\\\.\\\\d+)?)'))[1]::numeric\nWHERE category = 'well_motors' AND specs_ar ~ 'قطر التنصيب \\\\d+';\n\n-- Extract material for the two brands that already state it in the\n-- Arabic name (Ferat, Shakti). MAX / PUNA / SP Sterapump are left NULL\n-- per client decision — no material step is shown for them.\nUPDATE products SET motor_material = 'stainless'\nWHERE category = 'well_motors' AND name_ar LIKE '%ستانلس%' AND name_ar NOT LIKE '%كاب حديد%';\n\nUPDATE products SET motor_material = 'cast_iron'\nWHERE category = 'well_motors' AND name_ar LIKE '%حديد زهر%' AND name_ar NOT LIKE '%ستانلس%';\n\nUPDATE products SET motor_material = 'stainless_cast_iron_cap'\nWHERE category = 'well_motors' AND name_ar LIKE '%ستانلس%' AND name_ar LIKE '%كاب حديد%';\n\nSELECT motor_material, count(*), count(diameter_inch) AS with_diameter FROM products WHERE category='well_motors' GROUP BY motor_material;"}	add_motor_material_and_diameter_columns	alhussieni95@gmail.com	\N	\N
20260811025621	{"ALTER TABLE products\n  ADD COLUMN IF NOT EXISTS pipe_pressure_class text,\n  ADD COLUMN IF NOT EXISTS pipe_pressure_bar numeric,\n  ADD COLUMN IF NOT EXISTS pipe_diameter_inch numeric;\n\nUPDATE products SET\n  pipe_pressure_class = CASE WHEN specs_ar LIKE '%Heavy%' THEN 'heavy' WHEN specs_ar LIKE '%Standard%' THEN 'standard' ELSE NULL END,\n  pipe_pressure_bar = (regexp_match(specs_ar, 'ضغط (?:Standard|Heavy) (\\\\d+) بار'))[1]::numeric,\n  pipe_diameter_inch = (regexp_match(name_ar, '(\\\\d+(?:\\\\.\\\\d+)?) بوصة'))[1]::numeric\nWHERE category = 'pipes';\n\nSELECT brand, pipe_diameter_inch, pipe_pressure_class, pipe_pressure_bar, count(*)\nFROM products WHERE category='pipes'\nGROUP BY brand, pipe_diameter_inch, pipe_pressure_class, pipe_pressure_bar\nORDER BY brand, pipe_diameter_inch;"}	add_pipe_pressure_and_diameter_columns	alhussieni95@gmail.com	\N	\N
20260811033348	{"\n-- ============================================================\n-- 1) جدول المناديب (reps) — مرتبط بحساب Supabase Auth حقيقي\n-- ============================================================\ncreate table public.reps (\n  id uuid primary key references auth.users(id) on delete cascade,\n  email text not null unique,\n  display_name text not null,\n  active boolean not null default true,\n  created_at timestamptz not null default now()\n);\n\nalter table public.reps enable row level security;\n\ncreate policy \\"Reps can read own row, admins read all\\"\n  on public.reps for select\n  using (id = auth.uid() or is_admin());\n\ncreate policy \\"Admins manage reps\\"\n  on public.reps for all\n  using (is_admin())\n  with check (is_admin());\n\n-- ============================================================\n-- 2) دالة is_rep() — بنفس منطق is_admin() الموجودة بالفعل\n-- ============================================================\ncreate or replace function public.is_rep()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select exists (\n    select 1 from public.reps\n    where id = auth.uid() and active = true\n  );\n$$;\n\n-- ============================================================\n-- 3) جدول العملاء (leads) اللي المناديب بيسجلوها\n-- ============================================================\ncreate table public.customers (\n  id bigint generated always as identity primary key,\n  name text not null,\n  phone text not null unique,\n  city text,\n  lead_source text not null default 'rep_quote',\n  assigned_rep_id uuid references public.reps(id),\n  notes text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\nalter table public.customers enable row level security;\n\ncreate policy \\"Reps see own customers, admins see all\\"\n  on public.customers for select\n  using (is_admin() or (is_rep() and assigned_rep_id = auth.uid()));\n\ncreate policy \\"Reps update own customers, admins update all\\"\n  on public.customers for update\n  using (is_admin() or (is_rep() and assigned_rep_id = auth.uid()))\n  with check (is_admin() or (is_rep() and assigned_rep_id = auth.uid()));\n\ncreate policy \\"Admins delete customers\\"\n  on public.customers for delete\n  using (is_admin());\n\n-- ============================================================\n-- 4) جدول عروض الأسعار\n-- ============================================================\ncreate table public.quotes (\n  id bigint generated always as identity primary key,\n  customer_id bigint not null references public.customers(id),\n  rep_id uuid not null references public.reps(id),\n  quote_type text not null check (quote_type in ('supply_only','supply_install')),\n  items jsonb not null,\n  subtotal numeric not null default 0,\n  installation_cost numeric not null default 0,\n  total numeric not null default 0,\n  currency text not null default 'EGP',\n  notes text,\n  created_at timestamptz not null default now()\n);\n\ncreate index quotes_rep_id_idx on public.quotes(rep_id);\ncreate index quotes_customer_id_idx on public.quotes(customer_id);\n\nalter table public.quotes enable row level security;\n\ncreate policy \\"Reps see own quotes, admins see all\\"\n  on public.quotes for select\n  using (is_admin() or (is_rep() and rep_id = auth.uid()));\n\ncreate policy \\"Admins delete quotes\\"\n  on public.quotes for delete\n  using (is_admin());\n\n-- ============================================================\n-- 5) دالة موحدة لإنشاء عميل+عرض سعر معًا (تتجاوز RLS بأمان\n--    بعد التحقق اليدوي، عشان تمنع تعارض تخصيص العميل بين مندوبين)\n-- ============================================================\ncreate or replace function public.rep_create_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,\n  p_items jsonb,\n  p_subtotal numeric,\n  p_installation_cost numeric,\n  p_total numeric,\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, p_items, p_subtotal, p_installation_cost, p_total, p_notes)\n  returning id into v_quote_id;\n\n  return v_quote_id;\nend;\n$$;\n\ngrant execute on function public.rep_create_quote to authenticated;\n\n-- ============================================================\n-- 6) تصحيح ثغرة موجودة: pump_prices / pump_systems كانت بتسمح\n--    لأي حساب \\"authenticated\\" (مش الأدمن بس) بالتعديل والحذف.\n--    بعد إضافة حسابات مناديب، ده كان هيديهم صلاحية زيادة عن اللازم.\n-- ============================================================\ndrop policy if exists \\"auth_write_prices\\" on public.pump_prices;\ncreate policy \\"Admins write pump_prices\\"\n  on public.pump_prices for all\n  using (is_admin())\n  with check (is_admin());\n\ndrop policy if exists \\"auth_write_systems\\" on public.pump_systems;\ncreate policy \\"Admins write pump_systems\\"\n  on public.pump_systems for all\n  using (is_admin())\n  with check (is_admin());\n"}	rep_quote_system	alhussieni95@gmail.com	\N	\N
20260811102540	{"\n-- ============================================================\n-- 1) تكلفة داخلية لكل منتج — جدول منفصل، الأدمن بس يقدر يشوفه\n-- ============================================================\ncreate table public.product_costs (\n  product_id uuid primary key references public.products(id) on delete cascade,\n  cost_price numeric not null,\n  updated_at timestamptz not null default now()\n);\n\nalter table public.product_costs enable row level security;\n\ncreate policy \\"Admins only can access product costs\\"\n  on public.product_costs for all\n  using (is_admin())\n  with check (is_admin());\n\n-- ============================================================\n-- 2) ثوابت بنود الأوف جريد الثابتة (شاسيه/كابلات/إكسسوارات/نقل/تركيب)\n--    مقسّمة لجدولين: سعر العميل (يقرأه المندوب) وسعر التكلفة (أدمن بس)\n-- ============================================================\ncreate table public.offgrid_bom_settings (\n  id int primary key default 1,\n  steel_customer_per_unit numeric not null default 1500,\n  cables_customer_per_meter numeric not null default 65,\n  cable_meters_per_steel_unit numeric not null default 20,\n  accessories_customer_fixed numeric not null default 2500,\n  transport_customer_fixed numeric not null default 0,\n  install_customer_per_unit numeric not null default 0,\n  battery_charge_sun_hours numeric not null default 5.5,\n  system_efficiency numeric not null default 0.78,\n  default_surge_capacity_pct numeric not null default 1.5,\n  updated_at timestamptz not null default now(),\n  check (id = 1)\n);\ninsert into public.offgrid_bom_settings (id) values (1);\n\nalter table public.offgrid_bom_settings enable row level security;\n\ncreate policy \\"Public can read offgrid bom settings\\"\n  on public.offgrid_bom_settings for select\n  using (true);\n\ncreate policy \\"Admins can update offgrid bom settings\\"\n  on public.offgrid_bom_settings for update\n  using (is_admin())\n  with check (is_admin());\n\ncreate table public.offgrid_bom_cost_settings (\n  id int primary key default 1,\n  steel_cost_per_unit numeric not null default 1500,\n  cables_cost_per_meter numeric not null default 65,\n  accessories_cost_fixed numeric not null default 2500,\n  transport_cost_fixed numeric not null default 0,\n  install_cost_per_unit numeric not null default 0,\n  updated_at timestamptz not null default now(),\n  check (id = 1)\n);\ninsert into public.offgrid_bom_cost_settings (id) values (1);\n\nalter table public.offgrid_bom_cost_settings enable row level security;\n\ncreate policy \\"Admins only can access offgrid cost settings\\"\n  on public.offgrid_bom_cost_settings for all\n  using (is_admin())\n  with check (is_admin());\n\n-- ============================================================\n-- 3) تكلفة وربح كل عرض سعر — جدول منفصل عن quotes، أدمن بس\n-- ============================================================\ncreate table public.quote_costs (\n  quote_id bigint primary key references public.quotes(id) on delete cascade,\n  total_cost numeric not null,\n  profit numeric not null,\n  created_at timestamptz not null default now()\n);\n\nalter table public.quote_costs enable row level security;\n\ncreate policy \\"Admins only can access quote costs\\"\n  on public.quote_costs for all\n  using (is_admin())\n  with check (is_admin());\n\n-- ============================================================\n-- 4) دالة إصدار عرض سعر أوف جريد كامل\n--    بتحسب سعر العميل والتكلفة من قاعدة البيانات نفسها وقت الحفظ\n--    (مش من أي رقم جاي من متصفح المندوب) — عشان محدش يقدر يلعب\n--    بالأسعار أو التكلفة من جوه الـ Developer Tools.\n--    الخصم بس (discount_pct لكل بند) هو الحاجة الوحيدة اللي المندوب بيتحكم فيها.\n-- ============================================================\ncreate or replace function public.rep_create_offgrid_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,           -- 'supply_only' | 'supply_install'\n  p_items jsonb,                -- [{type:'product', product_id, qty, discount_pct, label}, {type:'bom_fixed', key, qty, discount_pct}]\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_qty numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select coalesce(cost_price, v_customer_unit) into v_cost_unit\n        from public.product_costs where product_id = v_prod.id;\n      if v_cost_unit is null then v_cost_unit := v_customer_unit; end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'steel' then v_bom.steel_customer_per_unit\n        when 'cables' then v_bom.cables_customer_per_meter\n        when 'accessories' then v_bom.accessories_customer_fixed\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'steel' then v_bom_cost.steel_cost_per_unit\n        when 'cables' then v_bom_cost.cables_cost_per_meter\n        when 'accessories' then v_bom_cost.accessories_cost_fixed\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$$;\n\ngrant execute on function public.rep_create_offgrid_quote to authenticated;\n"}	offgrid_rep_quote_engine	alhussieni95@gmail.com	\N	\N
20260811102724	{"\n-- تصحيح: سعر الألواح في جدول products مسجّل بالجنيه/وات مش سعر اللوح الكامل،\n-- فكان لازم نوع بند مستقل يضرب السعر × القدرة بالوات قبل الضرب في العدد،\n-- بدل ما يتعامل معاه زي أي منتج عادي (كان هيدي سعر أقل بكتير من الصح).\ncreate or replace function public.rep_create_offgrid_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,\n  p_items jsonb,\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_qty numeric;\n  v_watt numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select coalesce(cost_price, v_customer_unit) into v_cost_unit\n        from public.product_costs where product_id = v_prod.id;\n      if v_cost_unit is null then v_cost_unit := v_customer_unit; end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'panel' then\n      -- سعر الألواح مسجّل بالجنيه/وات في products.price، فلازم يتضرب في القدرة\n      -- بالوات (p_items.watt) قبل الضرب في عدد الألواح (qty)\n      select p.id, p.name_ar, p.price into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'panel product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_watt := coalesce((v_item->>'watt')::numeric, 0);\n      if v_watt <= 0 then\n        raise exception 'invalid panel watt';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0) * v_watt;\n      select coalesce(cost_price, v_prod.price) into v_cost_unit\n        from public.product_costs where product_id = v_prod.id;\n      if v_cost_unit is null then v_cost_unit := coalesce(v_prod.price, 0); end if;\n      v_cost_unit := v_cost_unit * v_watt;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'steel' then v_bom.steel_customer_per_unit\n        when 'cables' then v_bom.cables_customer_per_meter\n        when 'accessories' then v_bom.accessories_customer_fixed\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'steel' then v_bom_cost.steel_cost_per_unit\n        when 'cables' then v_bom_cost.cables_cost_per_meter\n        when 'accessories' then v_bom_cost.accessories_cost_fixed\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$$;\n"}	offgrid_quote_panel_pricing_fix	alhussieni95@gmail.com	\N	\N
20260811103204	{"\n-- تغيير النموذج: بدل \\"سعر تكلفة مطلق\\"، الأدمن بيسجّل نسبة خصم المورد\n-- (0-100) لكل منتج، والتكلفة الفعلية = سعر البيع المعروض × (1 - النسبة/100)\nalter table public.product_costs rename column cost_price to supplier_discount_pct;\nalter table public.product_costs alter column supplier_discount_pct set default 0;\nalter table public.product_costs add constraint supplier_discount_pct_range check (supplier_discount_pct >= 0 and supplier_discount_pct <= 100);\n\ncreate or replace function public.rep_create_offgrid_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,\n  p_items jsonb,\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_supplier_discount_pct numeric;\n  v_qty numeric;\n  v_watt numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.product_costs where product_id = v_prod.id;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'panel' then\n      select p.id, p.name_ar, p.price into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'panel product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_watt := coalesce((v_item->>'watt')::numeric, 0);\n      if v_watt <= 0 then\n        raise exception 'invalid panel watt';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0) * v_watt;\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.product_costs where product_id = v_prod.id;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'steel' then v_bom.steel_customer_per_unit\n        when 'cables' then v_bom.cables_customer_per_meter\n        when 'accessories' then v_bom.accessories_customer_fixed\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'steel' then v_bom_cost.steel_cost_per_unit\n        when 'cables' then v_bom_cost.cables_cost_per_meter\n        when 'accessories' then v_bom_cost.accessories_cost_fixed\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$$;\n"}	product_costs_as_discount_pct	alhussieni95@gmail.com	\N	\N
20260811162215	{"\n-- استبدال الخصم لكل منتج بخصم على مستوى (الفئة + الماركة) —\n-- عشان الأدمن يقدر يسجّل خصم واحد يغطي كل موديلات نفس الماركة في نفس الفئة\ndrop table if exists public.product_costs cascade;\n\ncreate table public.supplier_discounts (\n  category text not null,\n  brand text not null,\n  supplier_discount_pct numeric not null default 0 check (supplier_discount_pct >= 0 and supplier_discount_pct <= 100),\n  updated_at timestamptz not null default now(),\n  primary key (category, brand)\n);\n\nalter table public.supplier_discounts enable row level security;\n\ncreate policy \\"Admins only can access supplier discounts\\"\n  on public.supplier_discounts for all\n  using (is_admin())\n  with check (is_admin());\n\n-- تحديث دالة عرض السعر: التكلفة بتترجع من خصم (فئة+ماركة) بدل خصم لكل منتج\ncreate or replace function public.rep_create_offgrid_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,\n  p_items jsonb,\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_supplier_discount_pct numeric;\n  v_qty numeric;\n  v_watt numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'panel' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'panel product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_watt := coalesce((v_item->>'watt')::numeric, 0);\n      if v_watt <= 0 then\n        raise exception 'invalid panel watt';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0) * v_watt;\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'steel' then v_bom.steel_customer_per_unit\n        when 'cables' then v_bom.cables_customer_per_meter\n        when 'accessories' then v_bom.accessories_customer_fixed\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'steel' then v_bom_cost.steel_cost_per_unit\n        when 'cables' then v_bom_cost.cables_cost_per_meter\n        when 'accessories' then v_bom_cost.accessories_cost_fixed\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$$;\n"}	supplier_discounts_by_brand	alhussieni95@gmail.com	\N	\N
20260912230029	{"\ncreate table public.offgrid_loads (\n  id uuid primary key default gen_random_uuid(),\n  name text not null unique,\n  watt numeric not null,\n  running_factor numeric not null default 1,\n  day_hours numeric not null default 0,\n  night_hours numeric not null default 0,\n  surge_factor numeric not null default 1,\n  voltage integer not null default 220 check (voltage in (220,380)),\n  phase text not null default 'single' check (phase in ('single','three')),\n  is_active boolean not null default true,\n  sort_order integer not null default 100,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\nalter table public.offgrid_loads enable row level security;\n\ncreate policy \\"Public can read active offgrid loads\\" on public.offgrid_loads\n  for select using (is_active = true or is_admin());\n\ncreate policy \\"Admins can insert offgrid loads\\" on public.offgrid_loads\n  for insert with check (is_admin());\n\ncreate policy \\"Admins can update offgrid loads\\" on public.offgrid_loads\n  for update using (is_admin()) with check (is_admin());\n\ncreate policy \\"Admins can delete offgrid loads\\" on public.offgrid_loads\n  for delete using (is_admin());\n\ninsert into public.offgrid_loads (name, watt, running_factor, day_hours, night_hours, surge_factor, voltage, phase, sort_order) values\n('لمبة - LED Light', 10, 0.5, 5, 19, 1, 220, 'single', 10),\n('DVR / NVR', 25, 1, 5, 19, 1, 220, 'single', 20),\n('راوتر / شاحن', 15, 1, 5, 19, 1, 220, 'single', 30),\n('كاميرا مراقبة', 10, 1, 5, 19, 1, 220, 'single', 40),\n('لابتوب', 65, 1, 8, 0, 1, 220, 'single', 50),\n('مروحة', 70, 0.5, 4, 6, 3, 220, 'single', 60),\n('شفاط مطبخ', 75, 1, 2, 0, 3, 220, 'single', 70),\n('تلفاز LCD / كاميرات CCTV', 60, 1, 5, 19, 1, 220, 'single', 80),\n('تلفاز LCD', 80, 1, 3, 3, 1, 220, 'single', 90),\n('ثلاجة', 175, 0.8, 6, 18, 7, 220, 'single', 100),\n('كشاف إنارة', 200, 1, 0, 12, 1, 220, 'single', 110),\n('فريزر', 300, 0.8, 6, 18, 7, 220, 'single', 120),\n('موتور 1 حصان', 740, 1, 0.25, 2, 7, 220, 'single', 130),\n('ميكروويف', 1000, 1, 1, 1, 1, 220, 'single', 140),\n('موتور 1.5 حصان / غاطس', 1100, 1, 2, 0.5, 7, 220, 'single', 150),\n('تكييف 1.5 حصان', 1100, 0.75, 8, 8, 7, 220, 'single', 160),\n('غسالة', 1500, 1, 2, 0, 7, 220, 'single', 170),\n('تكييف 2.5 حصان', 1800, 0.5, 8, 8, 7, 220, 'single', 180),\n('تكييف 3 حصان', 2200, 0.5, 8, 8, 7, 220, 'single', 190),\n('هيتر مياه', 9000, 1, 2, 0, 1, 220, 'single', 200);\n"}	create_offgrid_loads_table	alhussieni95@gmail.com	\N	\N
20260812190342	{"\ncreate or replace function public.rep_create_irrigation_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,           -- 'supply_only' | 'supply_install'\n  p_items jsonb,                -- [{type:'product', product_id, qty, discount_pct, label}, {type:'bom_fixed', key:'transport'|'install', qty, discount_pct}]\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_supplier_discount_pct numeric;\n  v_qty numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true\n          and p.category in ('well_motors','pumps','inverters','pipes');\n      if v_prod.id is null then\n        raise exception 'product not found, not published, or not an irrigation category: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key for irrigation quote: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$$;\n\ngrant execute on function public.rep_create_irrigation_quote to authenticated;\n"}	irrigation_quote_engine	alhussieni95@gmail.com	\N	\N
20260813054957	{"\n-- rep_create_quote: يحسب السعر من products + supplier_discounts سيرفر-سايد\n-- بدل ما يثق في الأرقام الجاية من المتصفح.\n-- شكل p_items الجديد: [{\\"product_id\\": \\"...\\", \\"qty\\": 2}, ...]\ncreate or replace function public.rep_create_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,\n  p_items jsonb,\n  p_installation_cost numeric,\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_product record;\n  v_discount_pct numeric;\n  v_unit_price numeric;\n  v_qty numeric;\n  v_computed_items jsonb := '[]'::jsonb;\n  v_subtotal numeric := 0;\n  v_total numeric := 0;\n  v_install numeric := coalesce(p_installation_cost, 0);\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n  if v_install < 0 then\n    raise exception 'invalid installation cost';\n  end if;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    if v_qty <= 0 then\n      raise exception 'invalid quantity';\n    end if;\n\n    select id, name_ar, name_en, category, brand, price\n      into v_product\n      from public.products\n      where id = (v_item->>'product_id')::uuid\n        and published = true;\n\n    if v_product.id is null then\n      raise exception 'product not found or unpublished: %', v_item->>'product_id';\n    end if;\n\n    select supplier_discount_pct into v_discount_pct\n      from public.supplier_discounts\n      where category = v_product.category and brand = v_product.brand;\n\n    v_unit_price := round(coalesce(v_product.price, 0) * (1 - coalesce(v_discount_pct, 0) / 100.0), 2);\n\n    v_computed_items := v_computed_items || jsonb_build_object(\n      'product_id', v_product.id,\n      'name', coalesce(v_product.name_ar, v_product.name_en),\n      'unit_price', v_unit_price,\n      'qty', v_qty,\n      'line_total', v_unit_price * v_qty\n    );\n\n    v_subtotal := v_subtotal + (v_unit_price * v_qty);\n  end loop;\n\n  if jsonb_array_length(v_computed_items) = 0 then\n    raise exception 'quote must have at least one item';\n  end if;\n\n  if p_quote_type = 'supply_install' then\n    v_total := v_subtotal + v_install;\n  else\n    v_install := 0;\n    v_total := v_subtotal;\n  end if;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_computed_items, v_subtotal, v_install, v_total, p_notes)\n  returning id into v_quote_id;\n\n  return v_quote_id;\nend;\n$function$;\n\n-- قفل التنفيذ على anon، السماح بس للمسجلين دخول (auth.uid() لسه بيتحقق جواها كمان)\nrevoke execute on function public.rep_create_quote(text, text, text, text, jsonb, numeric, text) from anon;\ngrant execute on function public.rep_create_quote(text, text, text, text, jsonb, numeric, text) to authenticated;\n\n-- شيل التوقيع القديم اللي كان بياخد الأسعار من المتصفح\ndrop function if exists public.rep_create_quote(text, text, text, text, jsonb, numeric, numeric, numeric, text);\n"}	server_side_price_calc_for_rep_quotes	alhussieni95@gmail.com	\N	\N
20260813055106	{"\nrevoke execute on function public.rep_create_irrigation_quote(text, text, text, text, jsonb, text) from anon;\ngrant execute on function public.rep_create_irrigation_quote(text, text, text, text, jsonb, text) to authenticated;\n\nrevoke execute on function public.rep_create_offgrid_quote(text, text, text, text, jsonb, text) from anon;\ngrant execute on function public.rep_create_offgrid_quote(text, text, text, text, jsonb, text) to authenticated;\n"}	restrict_anon_execute_on_rep_quote_functions	alhussieni95@gmail.com	\N	\N
20260813055227	{"\ncreate or replace function public.rep_create_irrigation_quote(\n  p_customer_name text, p_customer_phone text, p_customer_city text,\n  p_quote_type text, p_items jsonb, p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_supplier_discount_pct numeric;\n  v_qty numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    -- الحد الأقصى لخصم المندوب: 4% (بدل 100% قبل كده)\n    v_discount_pct := greatest(0, least(4, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true\n          and p.category in ('well_motors','pumps','inverters','pipes');\n      if v_prod.id is null then\n        raise exception 'product not found, not published, or not an irrigation category: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key for irrigation quote: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$function$;\n\ncreate or replace function public.rep_create_offgrid_quote(\n  p_customer_name text, p_customer_phone text, p_customer_city text,\n  p_quote_type text, p_items jsonb, p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_supplier_discount_pct numeric;\n  v_qty numeric;\n  v_watt numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(4, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'panel' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'panel product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_watt := coalesce((v_item->>'watt')::numeric, 0);\n      if v_watt <= 0 then\n        raise exception 'invalid panel watt';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0) * v_watt;\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'steel' then v_bom.steel_customer_per_unit\n        when 'cables' then v_bom.cables_customer_per_meter\n        when 'accessories' then v_bom.accessories_customer_fixed\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'steel' then v_bom_cost.steel_cost_per_unit\n        when 'cables' then v_bom_cost.cables_cost_per_meter\n        when 'accessories' then v_bom_cost.accessories_cost_fixed\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$function$;\n\nrevoke execute on function public.rep_create_irrigation_quote(text, text, text, text, jsonb, text) from anon;\ngrant execute on function public.rep_create_irrigation_quote(text, text, text, text, jsonb, text) to authenticated;\nrevoke execute on function public.rep_create_offgrid_quote(text, text, text, text, jsonb, text) from anon;\ngrant execute on function public.rep_create_offgrid_quote(text, text, text, text, jsonb, text) to authenticated;\n"}	cap_rep_discount_pct_at_4_percent	alhussieni95@gmail.com	\N	\N
20260813115851	{"\n-- إعدادات تسعير البنود اللي مش منتجات حقيقية في الكتالوج (كابلات، خرسانة، تركيب، إلخ)\n-- منقولة بالأرقام الحقيقية من نظام Holoul المرجعي (pricing_config.data)\ncreate table if not exists public.irrigation_bom_settings (\n  id int primary key default 1,\n  vat numeric not null default 0.15,\n  hp_capacity_ratio numeric not null default 1.15,\n  max_string_voltage numeric not null default 720,\n  panels_per_string_adjust int not null default 0,\n  strings_adjust int not null default 0,\n  inverter_power_increase numeric not null default 0,\n  cb_ladder jsonb not null default '[32,63,80,100,125,160,200,250]',\n  reactor_ladder jsonb not null default '[50,80,100,160,315,450,560,1000]',\n  reactor_prices jsonb not null default '{\\"50\\":389,\\"80\\":479,\\"100\\":499,\\"160\\":599,\\"315\\":999,\\"450\\":1374,\\"560\\":1539,\\"1000\\":2529}',\n  reactor_markup_pct numeric not null default 10,\n  combiner_boxes jsonb not null default '[[4,749],[8,949],[10,1149],[16,1649],[22,2649],[30,3849],[34,4598],[38,4798],[40,4998],[46,5498],[50,6147],[56,6647],[60,7698],[64,8447],[68,8647],[70,8847],[76,9347],[90,11547]]',\n  combiner_headroom numeric not null default 1.1,\n  combiner_min_spare_strings int not null default 0,\n  combiner_markup_pct numeric not null default 30,\n  cable_low_multiplier numeric not null default 45,\n  cable_high_multiplier numeric not null default 90,\n  cable_per_meter numeric not null default 4,\n  cable_markup numeric not null default 1.25,\n  mc4_per_unit numeric not null default 5,\n  mc4_markup_pct numeric not null default 50,\n  structure_price_fixed numeric not null default 1499,\n  structure_price_rotational numeric not null default 1499,\n  structure_markup_pct numeric not null default 10,\n  concrete_per_unit numeric not null default 230,\n  concrete_markup_pct numeric not null default 10,\n  earthing_per_unit numeric not null default 2500,\n  flex_tube_per_unit numeric not null default 50,\n  mech_install_per_panel numeric not null default 40,\n  elec_install_per_panel numeric not null default 30,\n  transport_per_trip numeric not null default 200,\n  transport_minimum numeric not null default 2000,\n  steel_panel_per_hp numeric not null default 16,\n  ip65_markup_pct numeric not null default 25,\n  panel_margin_per_watt numeric not null default 0.01,\n  updated_at timestamptz not null default now(),\n  check (id = 1)\n);\ninsert into public.irrigation_bom_settings (id) values (1) on conflict (id) do nothing;\n\nalter table public.irrigation_bom_settings enable row level security;\ncreate policy \\"reps and admins can read bom settings\\" on public.irrigation_bom_settings\n  for select using (is_rep() or is_admin());\ncreate policy \\"admins can update bom settings\\" on public.irrigation_bom_settings\n  for update using (is_admin());\n"}	create_irrigation_solar_bom_settings	alhussieni95@gmail.com	\N	\N
20260813115955	{"\ncreate or replace function public.rep_create_irrigation_solar_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_hp numeric,\n  p_panel_product_id uuid,\n  p_structure_type text default 'FIXED',   -- 'FIXED' | 'ROTATIONAL'\n  p_toggles jsonb default '{\\"panel\\":true,\\"inverter\\":true,\\"ip65\\":true,\\"combiner\\":true,\\"cables\\":true,\\"mc4\\":true,\\"structure\\":true,\\"concrete\\":true,\\"earth\\":true,\\"reactor\\":true,\\"install_mech\\":true,\\"install_elec\\":true,\\"transport\\":true}',\n  p_discount_pct numeric default 0,        -- 0-4%، تطبق على هامش الربح فقط (زي الغطاء المتفق عليه)\n  p_quote_type text default 'supply_install',\n  p_notes text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  s public.irrigation_bom_settings;\n  v_panel record;\n  v_panel_discount_pct numeric;\n  v_panel_customer_price numeric;   -- سعر الوات بعد خصم الموردين\n  v_inv record;\n  v_inv_discount_pct numeric;\n  v_inv_customer_price numeric;\n  panels_per_string int;\n  arrays int;\n  total_panels int;\n  calc_kw numeric;\n  efficiency_ratio numeric;\n  v_iimp numeric; v_vimp numeric; v_voc numeric; v_isc numeric; v_isc_calc numeric;\n  inverter_calc_kw numeric;\n  inverter_oversize_warning text;\n  reactor_model int;\n  reactor_price numeric;\n  cb_size int;\n  combiner_need int;\n  combiner_row jsonb;\n  combiner_capacity int;\n  combiner_cost numeric;\n  panel_cost numeric; panel_sell numeric;\n  steel_panel_cost numeric;\n  cable_raw numeric; rounded_hundreds numeric; hundreds_unit numeric; even_unit numeric; cables_len numeric; cables_cost numeric;\n  mc4_cost numeric;\n  structure_price numeric; structure_cost numeric;\n  concrete_qty int; concrete_cost numeric;\n  earth_qty int; earth_cost numeric;\n  reactor_cost numeric; reactor_sell numeric;\n  mech_install_cost numeric; elec_install_cost numeric;\n  transport_qty int; transport_cost numeric;\n  factor numeric;\n  items jsonb := '[]'::jsonb;\n  it jsonb;\n  sell numeric; cost_basis numeric; margin numeric; discount numeric; net numeric;\n  sell_total numeric := 0; discount_total numeric := 0;\n  net_after_discount numeric; vat_amt numeric; final_total numeric;\n  supply_only_total numeric; supply_install_total numeric;\n  t jsonb;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_hp is null or p_hp <= 0 then\n    raise exception 'invalid hp';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n\n  select * into s from public.irrigation_bom_settings where id = 1;\n  t := coalesce(p_toggles, '{}'::jsonb);\n\n  -- اللوح: لازم يكون منشور، من فئة panels، وله كل القيم الكهربائية (استبعاد الناقص بيانات)\n  select id, name_ar, brand, category, price, power_watt, vimp, voc, iimp, isc\n    into v_panel\n    from public.products\n    where id = p_panel_product_id and category = 'panels' and published = true\n      and power_watt is not null and vimp is not null and voc is not null\n      and iimp is not null and isc is not null;\n  if v_panel.id is null then\n    raise exception 'panel not found, unpublished, or missing electrical specs (vimp/voc/iimp/isc/power_watt required)';\n  end if;\n\n  select supplier_discount_pct into v_panel_discount_pct\n    from public.supplier_discounts where category = v_panel.category and brand = v_panel.brand;\n  v_panel_customer_price := coalesce(v_panel.price, 0) * (1 - coalesce(v_panel_discount_pct, 0) / 100.0);\n\n  -- تصميم السلاسل\n  panels_per_string := floor(s.max_string_voltage / v_panel.vimp) - s.panels_per_string_adjust;\n  if panels_per_string < 1 then\n    raise exception 'panel vimp too high for max string voltage configured';\n  end if;\n  arrays := round(p_hp * 1000 * s.hp_capacity_ratio / (panels_per_string * v_panel.power_watt)) - s.strings_adjust;\n  if arrays < 1 then arrays := 1; end if;\n  total_panels := panels_per_string * arrays;\n  calc_kw := v_panel.power_watt * total_panels / 1000.0;\n  efficiency_ratio := calc_kw / p_hp;\n\n  v_iimp := arrays * v_panel.iimp;\n  v_vimp := panels_per_string * v_panel.vimp;\n  v_voc  := panels_per_string * v_panel.voc;\n  v_isc  := arrays * v_panel.isc;\n  v_isc_calc := v_isc * 1.25;\n\n  -- اختيار الإنفرتر: أقرب مقاس ≥ القدرة المطلوبة، من الإنفرترات المنشورة وعندها max_solar_input_kw\n  -- (استبعاد الناقص بيانات، زي القرار المتفق عليه)\n  inverter_calc_kw := ceil(p_hp * 0.8) + s.inverter_power_increase;\n\n  select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n    into v_inv\n    from public.products\n    where category = 'inverters' and published = true\n      and power_kw is not null and max_solar_input_kw is not null\n      and power_kw >= inverter_calc_kw\n    order by power_kw asc\n    limit 1;\n\n  if v_inv.id is null then\n    -- مفيش إنفرتر بالقدرة المطلوبة أو أعلى بمواصفات كاملة — نديله أعلى قدرة متاحة بدل ما نوقف كل الحساب\n    select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n      into v_inv\n      from public.products\n      where category = 'inverters' and published = true\n        and power_kw is not null and max_solar_input_kw is not null\n      order by power_kw desc\n      limit 1;\n    if v_inv.id is null then\n      raise exception 'no inverter with complete specs (power_kw + max_solar_input_kw) found in catalog';\n    end if;\n    inverter_oversize_warning := format(\n      'مفيش إنفرتر بقدرة %s كيلوواط أو أعلى بيانات كاملة — تم اختيار أعلى قدرة متاحة (%s كيلوواط)، راجع يدويًا.',\n      inverter_calc_kw, v_inv.power_kw);\n  end if;\n\n  if calc_kw > v_inv.max_solar_input_kw then\n    inverter_oversize_warning := coalesce(inverter_oversize_warning || ' ', '') || format(\n      '⚠️ قدرة الألواح المحسوبة (%.1f كيلوواط) تتجاوز أقصى ما يتحمله إنفرتر %s كيلوواط (الحد الأقصى %s كيلوواط) — راجع الاختيار يدويًا.',\n      calc_kw, v_inv.power_kw, v_inv.max_solar_input_kw);\n  end if;\n\n  select supplier_discount_pct into v_inv_discount_pct\n    from public.supplier_discounts where category = v_inv.category and brand = v_inv.brand;\n  v_inv_customer_price := coalesce(v_inv.price, 0) * (1 - coalesce(v_inv_discount_pct, 0) / 100.0);\n\n  -- الريأكتور والقاطع (سلالم اختيار)\n  select min(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x where x::numeric >= v_iimp;\n  if reactor_model is null then select max(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x; end if;\n  reactor_price := (s.reactor_prices ->> reactor_model::text)::numeric;\n\n  select min(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x where x::numeric >= v_isc_calc;\n  if cb_size is null then select max(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x; end if;\n\n  combiner_need := greatest(ceil(arrays * s.combiner_headroom)::int, arrays + s.combiner_min_spare_strings);\n  select row into combiner_row from (\n    select row, (row->>0)::int as cap\n    from (select jsonb_array_elements(s.combiner_boxes) as row) q\n    order by (row->>0)::int\n  ) x where cap >= combiner_need limit 1;\n  if combiner_row is null then\n    select row into combiner_row from (\n      select row, (row->>0)::int as cap\n      from (select jsonb_array_elements(s.combiner_boxes) as row) q\n      order by (row->>0)::int desc limit 1\n    ) x;\n  end if;\n  combiner_capacity := (combiner_row->>0)::int;\n  combiner_cost := (combiner_row->>1)::numeric;\n\n  panel_cost := v_panel_customer_price * calc_kw * 1000 / 1000; -- priceW-equivalent: price already per-watt-like? see note below\n  -- ملاحظة: عمود products.price للألواح مسجّل بسعر الوات (زي \\"8.5\\" ريال/وات) فعليًا حسب البيانات الحالية،\n  -- فمفيش تحويل إضافي مطلوب — panel_cost = سعر الوات × القدرة بالوات.\n  panel_cost := v_panel_customer_price * calc_kw * 1000;\n  panel_sell := (v_panel_customer_price + s.panel_margin_per_watt) * calc_kw * 1000;\n\n  steel_panel_cost := s.steel_panel_per_hp * p_hp;\n\n  cable_raw := case when calc_kw >= 100 then s.cable_high_multiplier * arrays else s.cable_low_multiplier * arrays end;\n  rounded_hundreds := round(cable_raw / 100.0) * 100;\n  hundreds_unit := rounded_hundreds / 100;\n  even_unit := case when mod(hundreds_unit::int, 2) = 0 then hundreds_unit\n               when hundreds_unit > 0 then hundreds_unit + 1 else hundreds_unit - 1 end;\n  cables_len := even_unit * 100;\n  cables_cost := cables_len * s.cable_per_meter;\n\n  mc4_cost := arrays * s.mc4_per_unit;\n  structure_price := case when upper(p_structure_type) = 'ROTATIONAL' then s.structure_price_rotational else s.structure_price_fixed end;\n  structure_cost := arrays * structure_price;\n  concrete_qty := round(arrays * 8 / 3.5);\n  concrete_cost := concrete_qty * s.concrete_per_unit;\n  earth_qty := round(calc_kw / 40);\n  earth_cost := earth_qty * s.earthing_per_unit;\n  reactor_cost := reactor_price;\n  reactor_sell := reactor_cost * (1 + s.reactor_markup_pct / 100.0);\n  mech_install_cost := total_panels * s.mech_install_per_panel;\n  elec_install_cost := total_panels * s.elec_install_per_panel;\n  transport_qty := ceil(calc_kw / 20);\n  transport_cost := greatest(transport_qty * s.transport_per_trip, s.transport_minimum);\n\n  factor := greatest(0, least(4, coalesce(p_discount_pct, 0))) / 100.0;\n\n  -- بناء البنود\n  items := items || jsonb_build_object('key','panel','label','ألواح الطاقة الشمسية','on', (t->>'panel')::boolean,\n    'sell', panel_sell, 'cost_basis', panel_cost, 'type', v_panel.brand || ' ' || v_panel.power_watt || 'W', 'qty', total_panels, 'no_discount', true);\n  items := items || jsonb_build_object('key','inverter','label','الانفرتر','on', (t->>'inverter')::boolean,\n    'sell', v_inv_customer_price, 'cost_basis', coalesce(v_inv.price,0), 'type', v_inv.brand || ' ' || v_inv.power_kw || ' KW', 'qty', 1);\n  items := items || jsonb_build_object('key','ip65','label','لوحة الحماية IP65','on', (t->>'ip65')::boolean,\n    'sell', steel_panel_cost * (1+s.ip65_markup_pct/100.0), 'cost_basis', steel_panel_cost, 'type', format('خاصة بانفرتر %s KW', v_inv.power_kw), 'qty', 1);\n  items := items || jsonb_build_object('key','combiner','label', format('Combiner box %s', combiner_capacity), 'on', (t->>'combiner')::boolean,\n    'sell', combiner_cost * (1+s.combiner_markup_pct/100.0), 'cost_basis', combiner_cost, 'type', '-', 'qty', 1);\n  items := items || jsonb_build_object('key','cables','label','الكابلات - DC','on', (t->>'cables')::boolean,\n    'sell', cables_cost * s.cable_markup, 'cost_basis', cables_cost, 'type','6mm', 'qty', cables_len);\n  items := items || jsonb_build_object('key','mc4','label','وصلات MC4','on', (t->>'mc4')::boolean,\n    'sell', mc4_cost * (1+s.mc4_markup_pct/100.0), 'cost_basis', mc4_cost, 'type','-', 'qty', arrays);\n  items := items || jsonb_build_object('key','structure','label', case when upper(p_structure_type)='ROTATIONAL' then 'الشاسيه (متحرك)' else 'الشاسيه (ثابت)' end,\n    'on', (t->>'structure')::boolean, 'sell', structure_cost * (1+s.structure_markup_pct/100.0), 'cost_basis', structure_cost, 'type','HDG مجلفن', 'qty', arrays);\n  items := items || jsonb_build_object('key','concrete','label','الخرسانة','on', (t->>'concrete')::boolean,\n    'sell', concrete_cost * (1+s.concrete_markup_pct/100.0), 'cost_basis', concrete_cost, 'type','-', 'qty', concrete_qty);\n  items := items || jsonb_build_object('key','earth','label','التأريض (بئر أرضي)','on', (t->>'earth')::boolean,\n    'sell', earth_cost, 'cost_basis', earth_cost, 'type','-', 'qty', earth_qty);\n  items := items || jsonb_build_object('key','reactor','label','الريأكتور','on', (t->>'reactor')::boolean,\n    'sell', reactor_sell, 'cost_basis', reactor_cost, 'type', reactor_model || 'A', 'qty', 1);\n  items := items || jsonb_build_object('key','install_mech','label','الأعمال الميدانية وتثبيت الألواح','on', (t->>'install_mech')::boolean,\n    'sell', mech_install_cost, 'cost_basis', mech_install_cost, 'type','-', 'qty', total_panels);\n  items := items || jsonb_build_object('key','install_elec','label','التركيبات والتوصيلات الكهربائية','on', (t->>'install_elec')::boolean,\n    'sell', elec_install_cost, 'cost_basis', elec_install_cost, 'type','-', 'qty', total_panels);\n  items := items || jsonb_build_object('key','transport','label','النقل','on', (t->>'transport')::boolean,\n    'sell', transport_cost, 'cost_basis', transport_cost, 'type','-', 'qty', transport_qty);\n\n  -- تطبيق الخصم على الهامش فقط (مش على السعر مباشرة) — الألواح مالهاش خصم أبدًا\n  declare\n    v_final_items jsonb := '[]'::jsonb;\n  begin\n    for it in select * from jsonb_array_elements(items)\n    loop\n      if not (it->>'on')::boolean then\n        v_final_items := v_final_items || jsonb_set(jsonb_set(it, '{discount}', '0'), '{net}', '0');\n        continue;\n      end if;\n      sell := (it->>'sell')::numeric;\n      cost_basis := (it->>'cost_basis')::numeric;\n      margin := sell - cost_basis;\n      discount := case when coalesce((it->>'no_discount')::boolean,false) then 0 else margin * factor end;\n      net := sell - discount;\n      sell_total := sell_total + sell;\n      discount_total := discount_total + discount;\n      v_final_items := v_final_items || jsonb_set(jsonb_set(it, '{discount}', to_jsonb(round(discount,2))), '{net}', to_jsonb(round(net,2)));\n    end loop;\n    items := v_final_items;\n  end;\n\n  discount_total := round(discount_total / 10) * 10;\n  net_after_discount := sell_total - discount_total;\n  vat_amt := net_after_discount * s.vat;\n  final_total := net_after_discount + vat_amt;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name, city = coalesce(excluded.city, public.customers.city), updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, items, net_after_discount, 0, round(final_total), p_notes)\n  returning id into v_quote_id;\n\n  return jsonb_build_object(\n    'quote_id', v_quote_id,\n    'panels_per_string', panels_per_string, 'arrays', arrays, 'total_panels', total_panels,\n    'calc_kw', round(calc_kw,1), 'efficiency_ratio', round(efficiency_ratio,3),\n    'vimp', round(v_vimp,1), 'voc', round(v_voc,1), 'iimp', round(v_iimp,1), 'isc', round(v_isc,1), 'isc_calc', round(v_isc_calc,1),\n    'inverter_brand', v_inv.brand, 'inverter_kw', v_inv.power_kw, 'inverter_oversize_warning', inverter_oversize_warning,\n    'reactor_model', reactor_model, 'cb_size', cb_size, 'combiner_capacity', combiner_capacity,\n    'items', items, 'sell_total', round(sell_total,2), 'discount_total', discount_total,\n    'net_after_discount', round(net_after_discount,2), 'vat', round(vat_amt,2), 'final_total', round(final_total),\n    'sar_per_kw', round(final_total / calc_kw, 1)\n  );\nend;\n$function$;\n\nrevoke execute on function public.rep_create_irrigation_solar_quote(text,text,text,numeric,uuid,text,jsonb,numeric,text,text) from anon;\ngrant execute on function public.rep_create_irrigation_solar_quote(text,text,text,numeric,uuid,text,jsonb,numeric,text,text) to authenticated;\n"}	rep_create_irrigation_solar_quote	alhussieni95@gmail.com	\N	\N
20260814075620	{"\n-- دالة معاينة بس (بدون حفظ، بدون بيانات عميل) — آمنة تتنفذ مع كل تغيير في الواجهة\ncreate or replace function public.preview_irrigation_solar_quote(\n  p_hp numeric,\n  p_panel_product_id uuid,\n  p_structure_type text default 'FIXED',\n  p_toggles jsonb default '{\\"panel\\":true,\\"inverter\\":true,\\"ip65\\":true,\\"combiner\\":true,\\"cables\\":true,\\"mc4\\":true,\\"structure\\":true,\\"concrete\\":true,\\"earth\\":true,\\"reactor\\":true,\\"install_mech\\":true,\\"install_elec\\":true,\\"transport\\":true}',\n  p_discount_pct numeric default 0\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  s public.irrigation_bom_settings;\n  v_panel record;\n  v_panel_discount_pct numeric;\n  v_panel_customer_price numeric;\n  v_inv record;\n  v_inv_discount_pct numeric;\n  v_inv_customer_price numeric;\n  panels_per_string int;\n  arrays int;\n  total_panels int;\n  calc_kw numeric;\n  efficiency_ratio numeric;\n  v_iimp numeric; v_vimp numeric; v_voc numeric; v_isc numeric; v_isc_calc numeric;\n  inverter_calc_kw numeric;\n  inverter_oversize_warning text;\n  reactor_model int;\n  cb_size int;\n  combiner_need int;\n  combiner_row jsonb;\n  combiner_capacity int;\n  combiner_cost numeric;\n  panel_cost numeric; panel_sell numeric;\n  steel_panel_cost numeric;\n  cable_raw numeric; rounded_hundreds numeric; hundreds_unit numeric; even_unit numeric; cables_len numeric; cables_cost numeric;\n  mc4_cost numeric;\n  structure_price numeric; structure_cost numeric;\n  concrete_qty int; concrete_cost numeric;\n  earth_qty int; earth_cost numeric;\n  reactor_price numeric;\n  reactor_cost numeric; reactor_sell numeric;\n  mech_install_cost numeric; elec_install_cost numeric;\n  transport_qty int; transport_cost numeric;\n  factor numeric;\n  items jsonb := '[]'::jsonb;\n  it jsonb;\n  sell numeric; cost_basis numeric; margin numeric; discount numeric; net numeric;\n  sell_total numeric := 0; discount_total numeric := 0;\n  net_after_discount numeric; vat_amt numeric; final_total numeric;\n  t jsonb;\n  v_final_items jsonb := '[]'::jsonb;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_hp is null or p_hp <= 0 then\n    return jsonb_build_object('error', 'invalid_hp');\n  end if;\n\n  select * into s from public.irrigation_bom_settings where id = 1;\n  t := coalesce(p_toggles, '{}'::jsonb);\n\n  select id, name_ar, brand, category, price, power_watt, vimp, voc, iimp, isc\n    into v_panel\n    from public.products\n    where id = p_panel_product_id and category = 'panels' and published = true\n      and power_watt is not null and vimp is not null and voc is not null\n      and iimp is not null and isc is not null;\n  if v_panel.id is null then\n    return jsonb_build_object('error', 'panel_not_found');\n  end if;\n\n  select supplier_discount_pct into v_panel_discount_pct\n    from public.supplier_discounts where category = v_panel.category and brand = v_panel.brand;\n  v_panel_customer_price := coalesce(v_panel.price, 0) * (1 - coalesce(v_panel_discount_pct, 0) / 100.0);\n\n  panels_per_string := floor(s.max_string_voltage / v_panel.vimp) - s.panels_per_string_adjust;\n  if panels_per_string < 1 then\n    return jsonb_build_object('error', 'panel_voltage_too_high');\n  end if;\n  arrays := round(p_hp * 1000 * s.hp_capacity_ratio / (panels_per_string * v_panel.power_watt)) - s.strings_adjust;\n  if arrays < 1 then arrays := 1; end if;\n  total_panels := panels_per_string * arrays;\n  calc_kw := v_panel.power_watt * total_panels / 1000.0;\n  efficiency_ratio := calc_kw / p_hp;\n\n  v_iimp := arrays * v_panel.iimp;\n  v_vimp := panels_per_string * v_panel.vimp;\n  v_voc  := panels_per_string * v_panel.voc;\n  v_isc  := arrays * v_panel.isc;\n  v_isc_calc := v_isc * 1.25;\n\n  inverter_calc_kw := ceil(p_hp * 0.8) + s.inverter_power_increase;\n\n  select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n    into v_inv\n    from public.products\n    where category = 'inverters' and published = true\n      and power_kw is not null and max_solar_input_kw is not null\n      and power_kw >= inverter_calc_kw\n    order by power_kw asc limit 1;\n\n  if v_inv.id is null then\n    select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n      into v_inv\n      from public.products\n      where category = 'inverters' and published = true\n        and power_kw is not null and max_solar_input_kw is not null\n      order by power_kw desc limit 1;\n    if v_inv.id is null then\n      return jsonb_build_object('error', 'no_inverter_available');\n    end if;\n    inverter_oversize_warning := format(\n      'مفيش إنفرتر بقدرة %s كيلوواط أو أعلى بيانات كاملة — تم اختيار أعلى قدرة متاحة (%s كيلوواط)، راجع يدويًا.',\n      inverter_calc_kw, v_inv.power_kw);\n  end if;\n\n  if calc_kw > v_inv.max_solar_input_kw then\n    inverter_oversize_warning := coalesce(inverter_oversize_warning || ' ', '') || format(\n      '⚠️ قدرة الألواح المحسوبة (%.1f كيلوواط) تتجاوز أقصى ما يتحمله إنفرتر %s كيلوواط (الحد الأقصى %s كيلوواط) — راجع الاختيار يدويًا.',\n      calc_kw, v_inv.power_kw, v_inv.max_solar_input_kw);\n  end if;\n\n  select supplier_discount_pct into v_inv_discount_pct\n    from public.supplier_discounts where category = v_inv.category and brand = v_inv.brand;\n  v_inv_customer_price := coalesce(v_inv.price, 0) * (1 - coalesce(v_inv_discount_pct, 0) / 100.0);\n\n  select min(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x where x::numeric >= v_iimp;\n  if reactor_model is null then select max(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x; end if;\n  reactor_price := (s.reactor_prices ->> reactor_model::text)::numeric;\n\n  select min(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x where x::numeric >= v_isc_calc;\n  if cb_size is null then select max(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x; end if;\n\n  combiner_need := greatest(ceil(arrays * s.combiner_headroom)::int, arrays + s.combiner_min_spare_strings);\n  select row into combiner_row from (\n    select row, (row->>0)::int as cap\n    from (select jsonb_array_elements(s.combiner_boxes) as row) q\n    order by (row->>0)::int\n  ) x where cap >= combiner_need limit 1;\n  if combiner_row is null then\n    select row into combiner_row from (\n      select row, (row->>0)::int as cap\n      from (select jsonb_array_elements(s.combiner_boxes) as row) q\n      order by (row->>0)::int desc limit 1\n    ) x;\n  end if;\n  combiner_capacity := (combiner_row->>0)::int;\n  combiner_cost := (combiner_row->>1)::numeric;\n\n  panel_cost := v_panel_customer_price * calc_kw * 1000;\n  panel_sell := (v_panel_customer_price + s.panel_margin_per_watt) * calc_kw * 1000;\n  steel_panel_cost := s.steel_panel_per_hp * p_hp;\n\n  cable_raw := case when calc_kw >= 100 then s.cable_high_multiplier * arrays else s.cable_low_multiplier * arrays end;\n  rounded_hundreds := round(cable_raw / 100.0) * 100;\n  hundreds_unit := rounded_hundreds / 100;\n  even_unit := case when mod(hundreds_unit::int, 2) = 0 then hundreds_unit\n               when hundreds_unit > 0 then hundreds_unit + 1 else hundreds_unit - 1 end;\n  cables_len := even_unit * 100;\n  cables_cost := cables_len * s.cable_per_meter;\n\n  mc4_cost := arrays * s.mc4_per_unit;\n  structure_price := case when upper(p_structure_type) = 'ROTATIONAL' then s.structure_price_rotational else s.structure_price_fixed end;\n  structure_cost := arrays * structure_price;\n  concrete_qty := round(arrays * 8 / 3.5);\n  concrete_cost := concrete_qty * s.concrete_per_unit;\n  earth_qty := round(calc_kw / 40);\n  earth_cost := earth_qty * s.earthing_per_unit;\n  reactor_cost := reactor_price;\n  reactor_sell := reactor_cost * (1 + s.reactor_markup_pct / 100.0);\n  mech_install_cost := total_panels * s.mech_install_per_panel;\n  elec_install_cost := total_panels * s.elec_install_per_panel;\n  transport_qty := ceil(calc_kw / 20);\n  transport_cost := greatest(transport_qty * s.transport_per_trip, s.transport_minimum);\n\n  factor := greatest(0, least(4, coalesce(p_discount_pct, 0))) / 100.0;\n\n  items := items || jsonb_build_object('key','panel','label','ألواح الطاقة الشمسية','on', (t->>'panel')::boolean,\n    'sell', panel_sell, 'cost_basis', panel_cost, 'type', v_panel.brand || ' ' || v_panel.power_watt || 'W', 'qty', total_panels, 'no_discount', true);\n  items := items || jsonb_build_object('key','inverter','label','الانفرتر','on', (t->>'inverter')::boolean,\n    'sell', v_inv_customer_price, 'cost_basis', coalesce(v_inv.price,0), 'type', v_inv.brand || ' ' || v_inv.power_kw || ' KW', 'qty', 1);\n  items := items || jsonb_build_object('key','ip65','label','لوحة الحماية IP65','on', (t->>'ip65')::boolean,\n    'sell', steel_panel_cost * (1+s.ip65_markup_pct/100.0), 'cost_basis', steel_panel_cost, 'type', format('خاصة بانفرتر %s KW', v_inv.power_kw), 'qty', 1);\n  items := items || jsonb_build_object('key','combiner','label', format('Combiner box %s', combiner_capacity), 'on', (t->>'combiner')::boolean,\n    'sell', combiner_cost * (1+s.combiner_markup_pct/100.0), 'cost_basis', combiner_cost, 'type', '-', 'qty', 1);\n  items := items || jsonb_build_object('key','cables','label','الكابلات - DC','on', (t->>'cables')::boolean,\n    'sell', cables_cost * s.cable_markup, 'cost_basis', cables_cost, 'type','6mm', 'qty', cables_len);\n  items := items || jsonb_build_object('key','mc4','label','وصلات MC4','on', (t->>'mc4')::boolean,\n    'sell', mc4_cost * (1+s.mc4_markup_pct/100.0), 'cost_basis', mc4_cost, 'type','-', 'qty', arrays);\n  items := items || jsonb_build_object('key','structure','label', case when upper(p_structure_type)='ROTATIONAL' then 'الشاسيه (متحرك)' else 'الشاسيه (ثابت)' end,\n    'on', (t->>'structure')::boolean, 'sell', structure_cost * (1+s.structure_markup_pct/100.0), 'cost_basis', structure_cost, 'type','HDG مجلفن', 'qty', arrays);\n  items := items || jsonb_build_object('key','concrete','label','الخرسانة','on', (t->>'concrete')::boolean,\n    'sell', concrete_cost * (1+s.concrete_markup_pct/100.0), 'cost_basis', concrete_cost, 'type','-', 'qty', concrete_qty);\n  items := items || jsonb_build_object('key','earth','label','التأريض (بئر أرضي)','on', (t->>'earth')::boolean,\n    'sell', earth_cost, 'cost_basis', earth_cost, 'type','-', 'qty', earth_qty);\n  items := items || jsonb_build_object('key','reactor','label','الريأكتور','on', (t->>'reactor')::boolean,\n    'sell', reactor_sell, 'cost_basis', reactor_cost, 'type', reactor_model || 'A', 'qty', 1);\n  items := items || jsonb_build_object('key','install_mech','label','الأعمال الميدانية وتثبيت الألواح','on', (t->>'install_mech')::boolean,\n    'sell', mech_install_cost, 'cost_basis', mech_install_cost, 'type','-', 'qty', total_panels);\n  items := items || jsonb_build_object('key','install_elec','label','التركيبات والتوصيلات الكهربائية','on', (t->>'install_elec')::boolean,\n    'sell', elec_install_cost, 'cost_basis', elec_install_cost, 'type','-', 'qty', total_panels);\n  items := items || jsonb_build_object('key','transport','label','النقل','on', (t->>'transport')::boolean,\n    'sell', transport_cost, 'cost_basis', transport_cost, 'type','-', 'qty', transport_qty);\n\n  for it in select * from jsonb_array_elements(items)\n  loop\n    if not (it->>'on')::boolean then\n      v_final_items := v_final_items || jsonb_set(jsonb_set(it, '{discount}', '0'), '{net}', '0');\n      continue;\n    end if;\n    sell := (it->>'sell')::numeric;\n    cost_basis := (it->>'cost_basis')::numeric;\n    margin := sell - cost_basis;\n    discount := case when coalesce((it->>'no_discount')::boolean,false) then 0 else margin * factor end;\n    net := sell - discount;\n    sell_total := sell_total + sell;\n    discount_total := discount_total + discount;\n    v_final_items := v_final_items || jsonb_set(jsonb_set(it, '{discount}', to_jsonb(round(discount,2))), '{net}', to_jsonb(round(net,2)));\n  end loop;\n  items := v_final_items;\n\n  discount_total := round(discount_total / 10) * 10;\n  net_after_discount := sell_total - discount_total;\n  vat_amt := net_after_discount * s.vat;\n  final_total := net_after_discount + vat_amt;\n\n  return jsonb_build_object(\n    'panels_per_string', panels_per_string, 'arrays', arrays, 'total_panels', total_panels,\n    'calc_kw', round(calc_kw,1), 'efficiency_ratio', round(efficiency_ratio,3),\n    'vimp', round(v_vimp,1), 'voc', round(v_voc,1), 'iimp', round(v_iimp,1), 'isc', round(v_isc,1), 'isc_calc', round(v_isc_calc,1),\n    'inverter_brand', v_inv.brand, 'inverter_kw', v_inv.power_kw, 'inverter_oversize_warning', inverter_oversize_warning,\n    'reactor_model', reactor_model, 'cb_size', cb_size, 'combiner_capacity', combiner_capacity,\n    'items', items, 'sell_total', round(sell_total,2), 'discount_total', discount_total,\n    'net_after_discount', round(net_after_discount,2), 'vat', round(vat_amt,2), 'final_total', round(final_total),\n    'sar_per_kw', round(final_total / calc_kw, 1)\n  );\nend;\n$function$;\n\nrevoke execute on function public.preview_irrigation_solar_quote(numeric, uuid, text, jsonb, numeric) from anon;\ngrant execute on function public.preview_irrigation_solar_quote(numeric, uuid, text, jsonb, numeric) to authenticated;\n"}	split_irrigation_preview_and_save	alhussieni95@gmail.com	\N	\N
20260814213719	{"\n-- إعادة بناء دالتي المعاينة والحفظ عشان يطلعوا بنفس بنية 7 بنود\n-- (منشأ + ضمان لكل بند، شروط سداد 70/25/5%) زي AlaslSolarEgypt-QL بالظبط.\ncreate or replace function public._irrigation_solar_calc(\n  p_hp numeric,\n  p_panel_product_id uuid,\n  p_structure_type text,\n  p_toggles jsonb,\n  p_discount_pct numeric\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  s public.irrigation_bom_settings;\n  v_panel record;\n  v_panel_discount_pct numeric;\n  v_panel_customer_price numeric;\n  v_inv record;\n  v_inv_discount_pct numeric;\n  v_inv_customer_price numeric;\n  panels_per_string int;\n  arrays int;\n  total_panels int;\n  calc_kw numeric;\n  efficiency_ratio numeric;\n  v_iimp numeric; v_vimp numeric; v_voc numeric; v_isc numeric; v_isc_calc numeric;\n  inverter_calc_kw numeric;\n  inverter_oversize_warning text;\n  reactor_model int;\n  cb_size int;\n  combiner_need int;\n  combiner_row jsonb;\n  combiner_capacity int;\n  combiner_cost numeric;\n  panel_cost numeric; panel_sell numeric;\n  steel_panel_cost numeric;\n  cable_raw numeric; rounded_hundreds numeric; hundreds_unit numeric; even_unit numeric; cables_len numeric; cables_cost numeric;\n  mc4_cost numeric;\n  structure_price numeric; structure_cost numeric; structure_sell numeric;\n  concrete_qty int; concrete_cost numeric;\n  earth_qty int; earth_cost numeric; earth_sell numeric;\n  reactor_price numeric;\n  reactor_cost numeric; reactor_sell numeric;\n  mech_install_cost numeric; elec_install_cost numeric;\n  transport_qty int; transport_cost numeric;\n  factor numeric;\n  cables_sell numeric; mc4_sell numeric; ip65_sell numeric; combiner_sell numeric;\n  install_lump_sell numeric; install_lump_cost numeric; install_lump_net numeric;\n  rows jsonb := '[]'::jsonb;\n  sell_total numeric := 0; cost_total numeric := 0;\n  final_total numeric;\n  r_cables numeric; r_earth numeric; r_reactor numeric; r_install numeric;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_hp is null or p_hp <= 0 then\n    return jsonb_build_object('error', 'invalid_hp');\n  end if;\n\n  select * into s from public.irrigation_bom_settings where id = 1;\n\n  select id, name_ar, brand, category, price, power_watt, vimp, voc, iimp, isc\n    into v_panel\n    from public.products\n    where id = p_panel_product_id and category = 'panels' and published = true\n      and power_watt is not null and vimp is not null and voc is not null\n      and iimp is not null and isc is not null;\n  if v_panel.id is null then\n    return jsonb_build_object('error', 'panel_not_found');\n  end if;\n\n  select supplier_discount_pct into v_panel_discount_pct\n    from public.supplier_discounts where category = v_panel.category and brand = v_panel.brand;\n  v_panel_customer_price := coalesce(v_panel.price, 0) * (1 - coalesce(v_panel_discount_pct, 0) / 100.0);\n\n  panels_per_string := floor(s.max_string_voltage / v_panel.vimp) - s.panels_per_string_adjust;\n  if panels_per_string < 1 then return jsonb_build_object('error', 'panel_voltage_too_high'); end if;\n  arrays := round(p_hp * 1000 * s.hp_capacity_ratio / (panels_per_string * v_panel.power_watt)) - s.strings_adjust;\n  if arrays < 1 then arrays := 1; end if;\n  total_panels := panels_per_string * arrays;\n  calc_kw := v_panel.power_watt * total_panels / 1000.0;\n  efficiency_ratio := calc_kw / p_hp;\n\n  v_iimp := arrays * v_panel.iimp;\n  v_vimp := panels_per_string * v_panel.vimp;\n  v_voc  := panels_per_string * v_panel.voc;\n  v_isc  := arrays * v_panel.isc;\n  v_isc_calc := v_isc * 1.25;\n\n  inverter_calc_kw := ceil(p_hp * 0.8) + s.inverter_power_increase;\n\n  select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n    into v_inv\n    from public.products\n    where category = 'inverters' and published = true\n      and power_kw is not null and max_solar_input_kw is not null\n      and power_kw >= inverter_calc_kw\n    order by power_kw asc limit 1;\n  if v_inv.id is null then\n    select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n      into v_inv\n      from public.products\n      where category = 'inverters' and published = true\n        and power_kw is not null and max_solar_input_kw is not null\n      order by power_kw desc limit 1;\n    if v_inv.id is null then return jsonb_build_object('error', 'no_inverter_available'); end if;\n    inverter_oversize_warning := format('مفيش إنفرتر بقدرة %s كيلوواط أو أعلى بيانات كاملة — تم اختيار أعلى قدرة متاحة (%s كيلوواط)، راجع يدويًا.', inverter_calc_kw, v_inv.power_kw);\n  end if;\n  if calc_kw > v_inv.max_solar_input_kw then\n    inverter_oversize_warning := coalesce(inverter_oversize_warning || ' ', '') || format('⚠️ قدرة الألواح المحسوبة (%.1f كيلوواط) تتجاوز أقصى ما يتحمله إنفرتر %s كيلوواط (الحد الأقصى %s كيلوواط) — راجع الاختيار يدويًا.', calc_kw, v_inv.power_kw, v_inv.max_solar_input_kw);\n  end if;\n\n  select supplier_discount_pct into v_inv_discount_pct\n    from public.supplier_discounts where category = v_inv.category and brand = v_inv.brand;\n  v_inv_customer_price := coalesce(v_inv.price, 0) * (1 - coalesce(v_inv_discount_pct, 0) / 100.0);\n\n  select min(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x where x::numeric >= v_iimp;\n  if reactor_model is null then select max(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x; end if;\n  reactor_price := (s.reactor_prices ->> reactor_model::text)::numeric;\n\n  select min(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x where x::numeric >= v_isc_calc;\n  if cb_size is null then select max(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x; end if;\n\n  combiner_need := greatest(ceil(arrays * s.combiner_headroom)::int, arrays + s.combiner_min_spare_strings);\n  select row into combiner_row from (select row, (row->>0)::int as cap from (select jsonb_array_elements(s.combiner_boxes) as row) q order by (row->>0)::int) x where cap >= combiner_need limit 1;\n  if combiner_row is null then select row into combiner_row from (select row, (row->>0)::int as cap from (select jsonb_array_elements(s.combiner_boxes) as row) q order by (row->>0)::int desc limit 1) x; end if;\n  combiner_capacity := (combiner_row->>0)::int;\n  combiner_cost := (combiner_row->>1)::numeric;\n  combiner_sell := combiner_cost * (1 + s.combiner_markup_pct/100.0);\n\n  panel_cost := v_panel_customer_price * calc_kw * 1000;\n  panel_sell := (v_panel_customer_price + s.panel_margin_per_watt) * calc_kw * 1000;\n\n  steel_panel_cost := s.steel_panel_per_hp * p_hp;\n  ip65_sell := steel_panel_cost * (1 + s.ip65_markup_pct/100.0);\n\n  structure_price := case when upper(p_structure_type) = 'ROTATIONAL' then s.structure_price_rotational else s.structure_price_fixed end;\n  structure_cost := arrays * structure_price;\n  structure_sell := structure_cost * (1 + s.structure_markup_pct/100.0);\n\n  cable_raw := case when calc_kw >= 100 then s.cable_high_multiplier * arrays else s.cable_low_multiplier * arrays end;\n  rounded_hundreds := round(cable_raw / 100.0) * 100;\n  hundreds_unit := rounded_hundreds / 100;\n  even_unit := case when mod(hundreds_unit::int, 2) = 0 then hundreds_unit when hundreds_unit > 0 then hundreds_unit + 1 else hundreds_unit - 1 end;\n  cables_len := even_unit * 100;\n  cables_cost := cables_len * s.cable_per_meter;\n  cables_sell := cables_cost * s.cable_markup;\n\n  mc4_cost := arrays * s.mc4_per_unit;\n  mc4_sell := mc4_cost * (1 + s.mc4_markup_pct/100.0);\n\n  concrete_qty := round(arrays * 8 / 3.5);\n  concrete_cost := concrete_qty * s.concrete_per_unit;\n\n  earth_qty := round(calc_kw / 40);\n  earth_cost := earth_qty * s.earthing_per_unit;\n  earth_sell := earth_cost * (1 + s.concrete_markup_pct/100.0);\n\n  reactor_cost := reactor_price;\n  reactor_sell := reactor_cost * (1 + s.reactor_markup_pct/100.0);\n\n  mech_install_cost := total_panels * s.mech_install_per_panel;\n  elec_install_cost := total_panels * s.elec_install_per_panel;\n  transport_qty := ceil(calc_kw / 20);\n  transport_cost := greatest(transport_qty * s.transport_per_trip, s.transport_minimum);\n\n  install_lump_cost := combiner_cost + mc4_cost + steel_panel_cost + mech_install_cost + elec_install_cost + transport_cost + concrete_cost;\n  install_lump_sell := combiner_sell + mc4_sell + ip65_sell + mech_install_cost + elec_install_cost + transport_cost + (concrete_cost * (1+s.concrete_markup_pct/100.0));\n\n  factor := greatest(0, least(4, coalesce(p_discount_pct, 0))) / 100.0;\n\n  -- خصم الهامش بس مش على الألواح أبدًا (زي الاتفاق قبل كده)، وبنطبقه على باقي البنود\n  r_cables  := (cables_sell - cables_cost) * factor;\n  r_earth   := (earth_sell - earth_cost) * factor;\n  r_reactor := (reactor_sell - reactor_cost) * factor;\n  r_install := (install_lump_sell - install_lump_cost) * factor;\n\n  rows := jsonb_build_array(\n    jsonb_build_object('n',1,'name','الواح الطاقة الشمسية','type', v_panel.brand || ' ' || v_panel.power_watt || 'W',\n      'qty', case when (p_toggles->>'panel')::boolean then format('%s لوح (%s × %s)', total_panels, arrays, panels_per_string) else 'لا يوجد' end,\n      'origin','الصين','warranty','30 سنة ضد انخفاض الإنتاجية عن 87.40% / 12 سنة ضد عيوب الصناعة',\n      'net', case when (p_toggles->>'panel')::boolean then round(panel_sell) else 0 end),\n    jsonb_build_object('n',2,'name','الشاسية','type', case when upper(p_structure_type)='ROTATIONAL' then 'متحرك صينية - كمر سيجال - دهان ايبوكسي' else 'ثابت مجلفن تثبيت مسامير' end,\n      'qty', case when (p_toggles->>'structure')::boolean then format('%s KW', round(calc_kw,1)) else 'لا يوجد' end,\n      'origin','مصر','warranty','خمس سنوات',\n      'net', case when (p_toggles->>'structure')::boolean then round(structure_sell - (structure_sell-structure_cost)*factor) else 0 end),\n    jsonb_build_object('n',3,'name','الانفرتر','type', v_inv.brand || ' ' || v_inv.power_kw || ' KW',\n      'qty', case when (p_toggles->>'inverter')::boolean then '1' else 'لا يوجد' end,\n      'origin','الصين','warranty','سنتان',\n      'net', case when (p_toggles->>'inverter')::boolean then round(v_inv_customer_price) else 0 end),\n    jsonb_build_object('n',4,'name','الكابلات','type','HIS / LEADER / KBE',\n      'qty', case when (p_toggles->>'cables')::boolean then format('يحدد في الموقع - بحد أقصى %s متر', cables_len) else 'لا يوجد' end,\n      'origin','ألمانيا / الصين','warranty','سنة واحدة',\n      'net', case when (p_toggles->>'cables')::boolean then round(cables_sell - r_cables) else 0 end),\n    jsonb_build_object('n',5,'name','التأريض / بئر أرضي','type','-',\n      'qty', case when (p_toggles->>'earth')::boolean then 'يحدد في الموقع' else 'لا يوجد' end,\n      'origin','مصر','warranty','----',\n      'net', case when (p_toggles->>'earth')::boolean then round(earth_sell - r_earth) else 0 end),\n    jsonb_build_object('n',6,'name','الريأكتور (VFD Reactor)','type', reactor_model || ' A',\n      'qty', case when (p_toggles->>'reactor')::boolean then '1' else 'لا يوجد' end,\n      'origin','مصر','warranty','سنة واحدة',\n      'net', case when (p_toggles->>'reactor')::boolean then round(reactor_sell - r_reactor) else 0 end),\n    jsonb_build_object('n',7,'name','التوريد والنقل والتركيب وعمالة ولوحة الحماية IP65 والاكسسوارات والمواسير','type','-',\n      'qty', format('%s KW', round(calc_kw)),\n      'origin','مصر / الصين','warranty','----',\n      'net', round(install_lump_sell - r_install))\n  );\n\n  select coalesce(sum((r->>'net')::numeric),0) into sell_total from jsonb_array_elements(rows) r;\n  final_total := sell_total;\n\n  return jsonb_build_object(\n    'panels_per_string', panels_per_string, 'arrays', arrays, 'total_panels', total_panels,\n    'calc_kw', round(calc_kw,1), 'efficiency_ratio', round(efficiency_ratio,3),\n    'vimp', round(v_vimp,1), 'voc', round(v_voc,1), 'iimp', round(v_iimp,1), 'isc', round(v_isc,1), 'isc_calc', round(v_isc_calc,1),\n    'inverter_brand', v_inv.brand, 'inverter_kw', v_inv.power_kw, 'inverter_oversize_warning', inverter_oversize_warning,\n    'reactor_model', reactor_model, 'cb_size', cb_size,\n    'rows', rows, 'final_total', round(final_total),\n    'payment_terms', jsonb_build_array(\n      jsonb_build_object('label','مقدم عند التعاقد','pct',70,'amount', round(final_total*0.70)),\n      jsonb_build_object('label','عند التوريد','pct',25,'amount', round(final_total*0.25)),\n      jsonb_build_object('label','عند التشغيل','pct',5,'amount', round(final_total*0.05))\n    )\n  );\nend;\n$function$;\n\nrevoke execute on function public._irrigation_solar_calc(numeric, uuid, text, jsonb, numeric) from anon;\nrevoke execute on function public._irrigation_solar_calc(numeric, uuid, text, jsonb, numeric) from authenticated;\n-- دالة داخلية بس (security definer)، مش هتتنادى مباشرة من الفرونت\n\n-- دالة معاينة (بدون حفظ) — بتنادي المحرك الداخلي\ncreate or replace function public.preview_irrigation_solar_quote(\n  p_hp numeric, p_panel_product_id uuid, p_structure_type text default 'FIXED',\n  p_toggles jsonb default '{\\"panel\\":true,\\"inverter\\":true,\\"ip65\\":true,\\"combiner\\":true,\\"cables\\":true,\\"mc4\\":true,\\"structure\\":true,\\"concrete\\":true,\\"earth\\":true,\\"reactor\\":true,\\"install_mech\\":true,\\"install_elec\\":true,\\"transport\\":true}',\n  p_discount_pct numeric default 0\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\nbegin\n  if not (is_rep() or is_admin()) then raise exception 'not authorized'; end if;\n  return public._irrigation_solar_calc(p_hp, p_panel_product_id, p_structure_type, p_toggles, p_discount_pct);\nend;\n$function$;\nrevoke execute on function public.preview_irrigation_solar_quote(numeric, uuid, text, jsonb, numeric) from anon;\ngrant execute on function public.preview_irrigation_solar_quote(numeric, uuid, text, jsonb, numeric) to authenticated;\n\n-- دالة الحفظ الفعلي\ncreate or replace function public.rep_create_irrigation_solar_quote(\n  p_customer_name text, p_customer_phone text, p_customer_city text,\n  p_hp numeric, p_panel_product_id uuid, p_structure_type text default 'FIXED',\n  p_toggles jsonb default '{\\"panel\\":true,\\"inverter\\":true,\\"ip65\\":true,\\"combiner\\":true,\\"cables\\":true,\\"mc4\\":true,\\"structure\\":true,\\"concrete\\":true,\\"earth\\":true,\\"reactor\\":true,\\"install_mech\\":true,\\"install_elec\\":true,\\"transport\\":true}',\n  p_discount_pct numeric default 0, p_quote_type text default 'supply_install', p_notes text default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_calc jsonb;\nbegin\n  if not (is_rep() or is_admin()) then raise exception 'not authorized'; end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then raise exception 'invalid phone'; end if;\n\n  v_calc := public._irrigation_solar_calc(p_hp, p_panel_product_id, p_structure_type, p_toggles, p_discount_pct);\n  if v_calc ? 'error' then return v_calc; end if;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update set name = excluded.name, city = coalesce(excluded.city, public.customers.city), updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_calc->'rows', (v_calc->>'final_total')::numeric, 0, (v_calc->>'final_total')::numeric, p_notes)\n  returning id into v_quote_id;\n\n  return v_calc || jsonb_build_object('quote_id', v_quote_id);\nend;\n$function$;\nrevoke execute on function public.rep_create_irrigation_solar_quote(text,text,text,numeric,uuid,text,jsonb,numeric,text,text) from anon;\ngrant execute on function public.rep_create_irrigation_solar_quote(text,text,text,numeric,uuid,text,jsonb,numeric,text,text) to authenticated;\n"}	rewrite_irrigation_quote_to_match_proven_reference	alhussieni95@gmail.com	\N	\N
20260815044048	{"\ncreate or replace function public._irrigation_solar_calc(\n  p_hp numeric, p_panel_product_id uuid, p_structure_type text, p_toggles jsonb, p_discount_pct numeric\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  s public.irrigation_bom_settings;\n  v_panel record;\n  v_panel_discount_pct numeric;\n  v_panel_customer_price numeric;\n  v_inv record;\n  v_inv_discount_pct numeric;\n  v_inv_customer_price numeric;\n  panels_per_string int;\n  arrays int;\n  total_panels int;\n  calc_kw numeric;\n  efficiency_ratio numeric;\n  v_iimp numeric; v_vimp numeric; v_voc numeric; v_isc numeric; v_isc_calc numeric;\n  inverter_calc_kw numeric;\n  inverter_oversize_warning text;\n  reactor_model int;\n  cb_size int;\n  combiner_need int;\n  combiner_row jsonb;\n  combiner_capacity int;\n  combiner_cost numeric;\n  panel_cost numeric; panel_sell numeric;\n  steel_panel_cost numeric;\n  cable_raw numeric; rounded_hundreds numeric; hundreds_unit numeric; even_unit numeric; cables_len int; cables_cost numeric;\n  mc4_cost numeric;\n  structure_price numeric; structure_cost numeric; structure_sell numeric;\n  concrete_qty int; concrete_cost numeric;\n  earth_qty int; earth_cost numeric; earth_sell numeric;\n  reactor_price numeric;\n  reactor_cost numeric; reactor_sell numeric;\n  mech_install_cost numeric; elec_install_cost numeric;\n  transport_qty int; transport_cost numeric;\n  factor numeric;\n  cables_sell numeric; mc4_sell numeric; ip65_sell numeric; combiner_sell numeric;\n  install_lump_sell numeric; install_lump_cost numeric;\n  rows jsonb := '[]'::jsonb;\n  sell_total numeric := 0;\n  final_total numeric;\n  r_cables numeric; r_earth numeric; r_reactor numeric; r_install numeric;\nbegin\n  if not (is_rep() or is_admin()) then raise exception 'not authorized'; end if;\n  if p_hp is null or p_hp <= 0 then return jsonb_build_object('error', 'invalid_hp'); end if;\n\n  select * into s from public.irrigation_bom_settings where id = 1;\n\n  select id, name_ar, brand, category, price, power_watt, vimp, voc, iimp, isc\n    into v_panel\n    from public.products\n    where id = p_panel_product_id and category = 'panels' and published = true\n      and power_watt is not null and vimp is not null and voc is not null\n      and iimp is not null and isc is not null;\n  if v_panel.id is null then return jsonb_build_object('error', 'panel_not_found'); end if;\n\n  select supplier_discount_pct into v_panel_discount_pct\n    from public.supplier_discounts where category = v_panel.category and brand = v_panel.brand;\n  v_panel_customer_price := coalesce(v_panel.price, 0) * (1 - coalesce(v_panel_discount_pct, 0) / 100.0);\n\n  panels_per_string := floor(s.max_string_voltage / v_panel.vimp) - s.panels_per_string_adjust;\n  if panels_per_string < 1 then return jsonb_build_object('error', 'panel_voltage_too_high'); end if;\n  arrays := round(p_hp * 1000 * s.hp_capacity_ratio / (panels_per_string * v_panel.power_watt)) - s.strings_adjust;\n  if arrays < 1 then arrays := 1; end if;\n  total_panels := panels_per_string * arrays;\n  calc_kw := v_panel.power_watt * total_panels / 1000.0;\n  efficiency_ratio := calc_kw / p_hp;\n\n  v_iimp := arrays * v_panel.iimp;\n  v_vimp := panels_per_string * v_panel.vimp;\n  v_voc  := panels_per_string * v_panel.voc;\n  v_isc  := arrays * v_panel.isc;\n  v_isc_calc := v_isc * 1.25;\n\n  inverter_calc_kw := ceil(p_hp * 0.8) + s.inverter_power_increase;\n\n  select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n    into v_inv\n    from public.products\n    where category = 'inverters' and published = true\n      and power_kw is not null and max_solar_input_kw is not null\n      and power_kw >= inverter_calc_kw\n    order by power_kw asc limit 1;\n  if v_inv.id is null then\n    select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n      into v_inv\n      from public.products\n      where category = 'inverters' and published = true\n        and power_kw is not null and max_solar_input_kw is not null\n      order by power_kw desc limit 1;\n    if v_inv.id is null then return jsonb_build_object('error', 'no_inverter_available'); end if;\n    inverter_oversize_warning := format('مفيش إنفرتر بقدرة %s كيلوواط أو أعلى بيانات كاملة — تم اختيار أعلى قدرة متاحة (%s كيلوواط)، راجع يدويًا.', inverter_calc_kw, v_inv.power_kw);\n  end if;\n  if calc_kw > v_inv.max_solar_input_kw then\n    inverter_oversize_warning := coalesce(inverter_oversize_warning || ' ', '') || format('⚠️ قدرة الألواح المحسوبة (%.1f كيلوواط) تتجاوز أقصى ما يتحمله إنفرتر %s كيلوواط (الحد الأقصى %s كيلوواط) — راجع الاختيار يدويًا.', calc_kw, v_inv.power_kw, v_inv.max_solar_input_kw);\n  end if;\n\n  select supplier_discount_pct into v_inv_discount_pct\n    from public.supplier_discounts where category = v_inv.category and brand = v_inv.brand;\n  v_inv_customer_price := coalesce(v_inv.price, 0) * (1 - coalesce(v_inv_discount_pct, 0) / 100.0);\n\n  select min(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x where x::numeric >= v_iimp;\n  if reactor_model is null then select max(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x; end if;\n  reactor_price := (s.reactor_prices ->> reactor_model::text)::numeric;\n\n  select min(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x where x::numeric >= v_isc_calc;\n  if cb_size is null then select max(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x; end if;\n\n  combiner_need := greatest(ceil(arrays * s.combiner_headroom)::int, arrays + s.combiner_min_spare_strings);\n  select row into combiner_row from (select row, (row->>0)::int as cap from (select jsonb_array_elements(s.combiner_boxes) as row) q order by (row->>0)::int) x where cap >= combiner_need limit 1;\n  if combiner_row is null then select row into combiner_row from (select row, (row->>0)::int as cap from (select jsonb_array_elements(s.combiner_boxes) as row) q order by (row->>0)::int desc limit 1) x; end if;\n  combiner_capacity := (combiner_row->>0)::int;\n  combiner_cost := (combiner_row->>1)::numeric;\n  combiner_sell := combiner_cost * (1 + s.combiner_markup_pct/100.0);\n\n  panel_cost := v_panel_customer_price * calc_kw * 1000;\n  panel_sell := (v_panel_customer_price + s.panel_margin_per_watt) * calc_kw * 1000;\n\n  steel_panel_cost := s.steel_panel_per_hp * p_hp;\n  ip65_sell := steel_panel_cost * (1 + s.ip65_markup_pct/100.0);\n\n  structure_price := case when upper(p_structure_type) = 'ROTATIONAL' then s.structure_price_rotational else s.structure_price_fixed end;\n  structure_cost := arrays * structure_price;\n  structure_sell := structure_cost * (1 + s.structure_markup_pct/100.0);\n\n  cable_raw := case when calc_kw >= 100 then s.cable_high_multiplier * arrays else s.cable_low_multiplier * arrays end;\n  rounded_hundreds := round(cable_raw / 100.0) * 100;\n  hundreds_unit := rounded_hundreds / 100;\n  even_unit := case when mod(hundreds_unit::int, 2) = 0 then hundreds_unit when hundreds_unit > 0 then hundreds_unit + 1 else hundreds_unit - 1 end;\n  cables_len := round(even_unit * 100)::int;  -- تحويل لعدد صحيح — ده كان سبب الأصفار الزيادة\n  cables_cost := cables_len * s.cable_per_meter;\n  cables_sell := cables_cost * s.cable_markup;\n\n  mc4_cost := arrays * s.mc4_per_unit;\n  mc4_sell := mc4_cost * (1 + s.mc4_markup_pct/100.0);\n\n  concrete_qty := round(arrays * 8 / 3.5);\n  concrete_cost := concrete_qty * s.concrete_per_unit;\n\n  earth_qty := round(calc_kw / 40);\n  earth_cost := earth_qty * s.earthing_per_unit;\n  earth_sell := earth_cost * (1 + s.concrete_markup_pct/100.0);\n\n  reactor_cost := reactor_price;\n  reactor_sell := reactor_cost * (1 + s.reactor_markup_pct/100.0);\n\n  mech_install_cost := total_panels * s.mech_install_per_panel;\n  elec_install_cost := total_panels * s.elec_install_per_panel;\n  transport_qty := ceil(calc_kw / 20);\n  transport_cost := greatest(transport_qty * s.transport_per_trip, s.transport_minimum);\n\n  install_lump_cost := combiner_cost + mc4_cost + steel_panel_cost + mech_install_cost + elec_install_cost + transport_cost + concrete_cost;\n  install_lump_sell := combiner_sell + mc4_sell + ip65_sell + mech_install_cost + elec_install_cost + transport_cost + (concrete_cost * (1+s.concrete_markup_pct/100.0));\n\n  factor := greatest(0, least(4, coalesce(p_discount_pct, 0))) / 100.0;\n\n  r_cables  := (cables_sell - cables_cost) * factor;\n  r_earth   := (earth_sell - earth_cost) * factor;\n  r_reactor := (reactor_sell - reactor_cost) * factor;\n  r_install := (install_lump_sell - install_lump_cost) * factor;\n\n  rows := jsonb_build_array(\n    jsonb_build_object('n',1,'name','الواح الطاقة الشمسية','type', v_panel.brand || ' ' || v_panel.power_watt || 'W',\n      'qty', case when (p_toggles->>'panel')::boolean then format('%s لوح (%s × %s)', total_panels, arrays, panels_per_string) else 'لا يوجد' end,\n      'origin','الصين','warranty','30 سنة ضد انخفاض الإنتاجية عن 87.40% / 12 سنة ضد عيوب الصناعة',\n      'net', case when (p_toggles->>'panel')::boolean then round(panel_sell) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(panel_sell), 'cost', round(panel_cost))),\n    jsonb_build_object('n',2,'name','الشاسية','type', case when upper(p_structure_type)='ROTATIONAL' then 'متحرك صينية - كمر سيجال - دهان ايبوكسي' else 'ثابت مجلفن تثبيت مسامير' end,\n      'qty', case when (p_toggles->>'structure')::boolean then format('%s KW', round(calc_kw,1)) else 'لا يوجد' end,\n      'origin','مصر','warranty','خمس سنوات',\n      'net', case when (p_toggles->>'structure')::boolean then round(structure_sell - (structure_sell-structure_cost)*factor) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(structure_sell), 'cost', round(structure_cost))),\n    jsonb_build_object('n',3,'name','الانفرتر','type', v_inv.brand || ' ' || v_inv.power_kw || ' KW',\n      'qty', case when (p_toggles->>'inverter')::boolean then '1' else 'لا يوجد' end,\n      'origin','الصين','warranty','سنتان',\n      'net', case when (p_toggles->>'inverter')::boolean then round(v_inv_customer_price) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(v_inv_customer_price), 'cost', round(coalesce(v_inv.price,0)))),\n    jsonb_build_object('n',4,'name','الكابلات','type','HIS / LEADER / KBE',\n      'qty', case when (p_toggles->>'cables')::boolean then format('يحدد في الموقع - بحد أقصى %s متر', cables_len) else 'لا يوجد' end,\n      'origin','ألمانيا / الصين','warranty','سنة واحدة',\n      'net', case when (p_toggles->>'cables')::boolean then round(cables_sell - r_cables) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(cables_sell), 'cost', round(cables_cost))),\n    jsonb_build_object('n',5,'name','التأريض / بئر أرضي','type','-',\n      'qty', case when (p_toggles->>'earth')::boolean then 'يحدد في الموقع' else 'لا يوجد' end,\n      'origin','مصر','warranty','----',\n      'net', case when (p_toggles->>'earth')::boolean then round(earth_sell - r_earth) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(earth_sell), 'cost', round(earth_cost))),\n    jsonb_build_object('n',6,'name','الريأكتور (VFD Reactor)','type', reactor_model || ' A',\n      'qty', case when (p_toggles->>'reactor')::boolean then '1' else 'لا يوجد' end,\n      'origin','مصر','warranty','سنة واحدة',\n      'net', case when (p_toggles->>'reactor')::boolean then round(reactor_sell - r_reactor) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(reactor_sell), 'cost', round(reactor_cost))),\n    jsonb_build_object('n',7,'name','التوريد والنقل والتركيب وعمالة ولوحة الحماية IP65 والاكسسوارات والمواسير','type','-',\n      'qty', format('%s KW', round(calc_kw)),\n      'origin','مصر / الصين','warranty','----',\n      'net', round(install_lump_sell - r_install),\n      -- تفصيل داخلي بس (مش هيظهر في الطباعة) عشان توضيح مكوّنات البند ده لو المندوب سأل\n      'cost_note', jsonb_build_object(\n        'sell', round(install_lump_sell), 'cost', round(install_lump_cost),\n        'breakdown', jsonb_build_object(\n          'combiner', round(combiner_sell), 'mc4', round(mc4_sell), 'ip65', round(ip65_sell),\n          'install_mech', round(mech_install_cost), 'install_elec', round(elec_install_cost),\n          'transport', round(transport_cost), 'concrete', round(concrete_cost * (1+s.concrete_markup_pct/100.0))\n        )))\n  );\n\n  select coalesce(sum((r->>'net')::numeric),0) into sell_total from jsonb_array_elements(rows) r;\n  final_total := sell_total;\n\n  return jsonb_build_object(\n    'panels_per_string', panels_per_string, 'arrays', arrays, 'total_panels', total_panels,\n    'calc_kw', round(calc_kw,1), 'efficiency_ratio', round(efficiency_ratio,3),\n    'vimp', round(v_vimp,1), 'voc', round(v_voc,1), 'iimp', round(v_iimp,1), 'isc', round(v_isc,1), 'isc_calc', round(v_isc_calc,1),\n    'inverter_brand', v_inv.brand, 'inverter_kw', v_inv.power_kw, 'inverter_oversize_warning', inverter_oversize_warning,\n    'reactor_model', reactor_model, 'cb_size', cb_size,\n    'rows', rows, 'final_total', round(final_total),\n    'payment_terms', jsonb_build_array(\n      jsonb_build_object('label','مقدم عند التعاقد','pct',70,'amount', round(final_total*0.70)),\n      jsonb_build_object('label','عند التوريد','pct',25,'amount', round(final_total*0.25)),\n      jsonb_build_object('label','عند التشغيل','pct',5,'amount', round(final_total*0.05))\n    )\n  );\nend;\n$function$;\n"}	fix_cable_length_decimal_formatting	alhussieni95@gmail.com	\N	\N
20260816141951	{"\ncreate or replace function public._irrigation_solar_calc(\n  p_hp numeric, p_panel_product_id uuid, p_structure_type text, p_toggles jsonb, p_discount_pct numeric\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  s public.irrigation_bom_settings;\n  v_panel record;\n  v_panel_discount_pct numeric;\n  v_panel_cost_basis numeric;   -- تكلفتنا (بعد خصم المورد) — داخلي بس\n  v_panel_list_price numeric;   -- سعر الموقع الكامل — ده اللي العميل بيشوفه\n  v_inv record;\n  v_inv_discount_pct numeric;\n  v_inv_cost_basis numeric;\n  v_inv_list_price numeric;\n  v_comb record;\n  v_comb_discount_pct numeric;\n  v_comb_cost_basis numeric;\n  v_comb_list_price numeric;\n  v_comb_capacity int;\n  panels_per_string int;\n  arrays int;\n  total_panels int;\n  calc_kw numeric;\n  efficiency_ratio numeric;\n  v_iimp numeric; v_vimp numeric; v_voc numeric; v_isc numeric; v_isc_calc numeric;\n  inverter_calc_kw numeric;\n  inverter_oversize_warning text;\n  reactor_model int;\n  cb_size int;\n  combiner_need int;\n  panel_cost numeric; panel_sell numeric;\n  steel_panel_cost numeric;\n  cable_raw numeric; rounded_hundreds numeric; hundreds_unit numeric; even_unit numeric; cables_len int; cables_cost numeric;\n  mc4_cost numeric;\n  structure_price numeric; structure_cost numeric; structure_sell numeric;\n  concrete_qty int; concrete_cost numeric;\n  earth_qty int; earth_cost numeric; earth_sell numeric;\n  reactor_price numeric;\n  reactor_cost numeric; reactor_sell numeric;\n  mech_install_cost numeric; elec_install_cost numeric;\n  transport_qty int; transport_cost numeric;\n  factor numeric;\n  cables_sell numeric; mc4_sell numeric; ip65_sell numeric;\n  install_lump_sell numeric; install_lump_cost numeric;\n  rows jsonb := '[]'::jsonb;\n  sell_total numeric := 0;\n  final_total numeric;\n  r_cables numeric; r_earth numeric; r_reactor numeric; r_install numeric;\nbegin\n  if not (is_rep() or is_admin()) then raise exception 'not authorized'; end if;\n  if p_hp is null or p_hp <= 0 then return jsonb_build_object('error', 'invalid_hp'); end if;\n\n  select * into s from public.irrigation_bom_settings where id = 1;\n\n  -- الألواح\n  select id, name_ar, brand, category, price, power_watt, vimp, voc, iimp, isc\n    into v_panel\n    from public.products\n    where id = p_panel_product_id and category = 'panels' and published = true\n      and power_watt is not null and vimp is not null and voc is not null\n      and iimp is not null and isc is not null;\n  if v_panel.id is null then return jsonb_build_object('error', 'panel_not_found'); end if;\n\n  select supplier_discount_pct into v_panel_discount_pct\n    from public.supplier_discounts where category = v_panel.category and brand = v_panel.brand;\n  v_panel_list_price := coalesce(v_panel.price, 0);\n  v_panel_cost_basis := v_panel_list_price * (1 - coalesce(v_panel_discount_pct, 0) / 100.0);\n\n  panels_per_string := floor(s.max_string_voltage / v_panel.vimp) - s.panels_per_string_adjust;\n  if panels_per_string < 1 then return jsonb_build_object('error', 'panel_voltage_too_high'); end if;\n  arrays := round(p_hp * 1000 * s.hp_capacity_ratio / (panels_per_string * v_panel.power_watt)) - s.strings_adjust;\n  if arrays < 1 then arrays := 1; end if;\n  total_panels := panels_per_string * arrays;\n  calc_kw := v_panel.power_watt * total_panels / 1000.0;\n  efficiency_ratio := calc_kw / p_hp;\n\n  v_iimp := arrays * v_panel.iimp;\n  v_vimp := panels_per_string * v_panel.vimp;\n  v_voc  := panels_per_string * v_panel.voc;\n  v_isc  := arrays * v_panel.isc;\n  v_isc_calc := v_isc * 1.25;\n\n  -- الإنفرتر\n  inverter_calc_kw := ceil(p_hp * 0.8) + s.inverter_power_increase;\n  select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n    into v_inv\n    from public.products\n    where category = 'inverters' and published = true\n      and power_kw is not null and max_solar_input_kw is not null\n      and power_kw >= inverter_calc_kw\n    order by power_kw asc limit 1;\n  if v_inv.id is null then\n    select id, name_ar, brand, category, price, power_kw, max_solar_input_kw\n      into v_inv\n      from public.products\n      where category = 'inverters' and published = true\n        and power_kw is not null and max_solar_input_kw is not null\n      order by power_kw desc limit 1;\n    if v_inv.id is null then return jsonb_build_object('error', 'no_inverter_available'); end if;\n    inverter_oversize_warning := format('مفيش إنفرتر بقدرة %s كيلوواط أو أعلى بيانات كاملة — تم اختيار أعلى قدرة متاحة (%s كيلوواط)، راجع يدويًا.', inverter_calc_kw, v_inv.power_kw);\n  end if;\n  if calc_kw > v_inv.max_solar_input_kw then\n    inverter_oversize_warning := coalesce(inverter_oversize_warning || ' ', '') || format('⚠️ قدرة الألواح المحسوبة (%.1f كيلوواط) تتجاوز أقصى ما يتحمله إنفرتر %s كيلوواط (الحد الأقصى %s كيلوواط) — راجع الاختيار يدويًا.', calc_kw, v_inv.power_kw, v_inv.max_solar_input_kw);\n  end if;\n\n  select supplier_discount_pct into v_inv_discount_pct\n    from public.supplier_discounts where category = v_inv.category and brand = v_inv.brand;\n  v_inv_list_price := coalesce(v_inv.price, 0);\n  v_inv_cost_basis := v_inv_list_price * (1 - coalesce(v_inv_discount_pct, 0) / 100.0);\n\n  select min(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x where x::numeric >= v_iimp;\n  if reactor_model is null then select max(x::int) into reactor_model from jsonb_array_elements_text(s.reactor_ladder) x; end if;\n  reactor_price := (s.reactor_prices ->> reactor_model::text)::numeric;\n\n  select min(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x where x::numeric >= v_isc_calc;\n  if cb_size is null then select max(x::int) into cb_size from jsonb_array_elements_text(s.cb_ladder) x; end if;\n\n  -- صندوق التجميع (Combiner) — بيتسحب من المنتجات الفعلية (فئة combiners)\n  -- السعة مستخرجة من اسم المنتج \\"صندوق جمع N Arrays ...\\"\n  combiner_need := greatest(ceil(arrays * s.combiner_headroom)::int, arrays + s.combiner_min_spare_strings);\n  select id, name_ar, brand, category, price,\n         (regexp_match(name_ar, '(\\\\d+)\\\\s*Arrays'))[1]::int as capacity\n    into v_comb\n    from public.products\n    where category = 'combiners' and published = true\n      and (regexp_match(name_ar, '(\\\\d+)\\\\s*Arrays'))[1]::int >= combiner_need\n    order by (regexp_match(name_ar, '(\\\\d+)\\\\s*Arrays'))[1]::int asc\n    limit 1;\n  if v_comb.id is null then\n    select id, name_ar, brand, category, price,\n           (regexp_match(name_ar, '(\\\\d+)\\\\s*Arrays'))[1]::int as capacity\n      into v_comb\n      from public.products\n      where category = 'combiners' and published = true\n      order by (regexp_match(name_ar, '(\\\\d+)\\\\s*Arrays'))[1]::int desc\n      limit 1;\n  end if;\n  if v_comb.id is null then\n    return jsonb_build_object('error', 'no_combiner_available');\n  end if;\n  v_comb_capacity := v_comb.capacity;\n  select supplier_discount_pct into v_comb_discount_pct\n    from public.supplier_discounts where category = v_comb.category and brand = v_comb.brand;\n  v_comb_list_price := coalesce(v_comb.price, 0);\n  v_comb_cost_basis := v_comb_list_price * (1 - coalesce(v_comb_discount_pct, 0) / 100.0);\n\n  -- سعر العميل = سعر الموقع الكامل دايمًا (مؤكد)، هامش الربح = الفرق بينه وبين التكلفة بعد خصم المورد\n  panel_cost := v_panel_cost_basis * calc_kw * 1000;\n  panel_sell := v_panel_list_price * calc_kw * 1000;\n\n  steel_panel_cost := s.steel_panel_per_hp * p_hp;\n  ip65_sell := steel_panel_cost * (1 + s.ip65_markup_pct/100.0);\n\n  structure_price := case when upper(p_structure_type) = 'ROTATIONAL' then s.structure_price_rotational else s.structure_price_fixed end;\n  structure_cost := arrays * structure_price;\n  structure_sell := structure_cost * (1 + s.structure_markup_pct/100.0);\n\n  cable_raw := case when calc_kw >= 100 then s.cable_high_multiplier * arrays else s.cable_low_multiplier * arrays end;\n  rounded_hundreds := round(cable_raw / 100.0) * 100;\n  hundreds_unit := rounded_hundreds / 100;\n  even_unit := case when mod(hundreds_unit::int, 2) = 0 then hundreds_unit when hundreds_unit > 0 then hundreds_unit + 1 else hundreds_unit - 1 end;\n  cables_len := round(even_unit * 100)::int;\n  cables_cost := cables_len * s.cable_per_meter;\n  cables_sell := cables_cost * s.cable_markup;\n\n  mc4_cost := arrays * s.mc4_per_unit;\n  mc4_sell := mc4_cost * (1 + s.mc4_markup_pct/100.0);\n\n  concrete_qty := round(arrays * 8 / 3.5);\n  concrete_cost := concrete_qty * s.concrete_per_unit;\n\n  earth_qty := round(calc_kw / 40);\n  earth_cost := earth_qty * s.earthing_per_unit;\n  earth_sell := earth_cost * (1 + s.concrete_markup_pct/100.0);\n\n  reactor_cost := reactor_price;\n  reactor_sell := reactor_cost * (1 + s.reactor_markup_pct/100.0);\n\n  mech_install_cost := total_panels * s.mech_install_per_panel;\n  elec_install_cost := total_panels * s.elec_install_per_panel;\n  transport_qty := ceil(calc_kw / 20);\n  transport_cost := greatest(transport_qty * s.transport_per_trip, s.transport_minimum);\n\n  -- البند السابع المدموج: combiner بقى بسعر الموقع الحقيقي (مش سعر افتراضي + هامش يدوي)\n  install_lump_cost := v_comb_cost_basis + mc4_cost + steel_panel_cost + mech_install_cost + elec_install_cost + transport_cost + concrete_cost;\n  install_lump_sell := v_comb_list_price + mc4_sell + ip65_sell + mech_install_cost + elec_install_cost + transport_cost + (concrete_cost * (1+s.concrete_markup_pct/100.0));\n\n  factor := greatest(0, least(4, coalesce(p_discount_pct, 0))) / 100.0;\n\n  -- خصم المندوب الإضافي (0-4%) بيتطبق على هامش الربح فقط، بعد ما اتصلح السعر الأساسي\n  r_cables  := (cables_sell - cables_cost) * factor;\n  r_earth   := (earth_sell - earth_cost) * factor;\n  r_reactor := (reactor_sell - reactor_cost) * factor;\n  r_install := (install_lump_sell - install_lump_cost) * factor;\n\n  rows := jsonb_build_array(\n    jsonb_build_object('n',1,'name','الواح الطاقة الشمسية','type', v_panel.brand || ' ' || v_panel.power_watt || 'W',\n      'qty', case when (p_toggles->>'panel')::boolean then format('%s لوح (%s × %s)', total_panels, arrays, panels_per_string) else 'لا يوجد' end,\n      'origin','الصين','warranty','30 سنة ضد انخفاض الإنتاجية عن 87.40% / 12 سنة ضد عيوب الصناعة',\n      'net', case when (p_toggles->>'panel')::boolean then round(panel_sell) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(panel_sell), 'cost', round(panel_cost))),\n    jsonb_build_object('n',2,'name','الشاسية','type', case when upper(p_structure_type)='ROTATIONAL' then 'متحرك صينية - كمر سيجال - دهان ايبوكسي' else 'ثابت مجلفن تثبيت مسامير' end,\n      'qty', case when (p_toggles->>'structure')::boolean then format('%s KW', round(calc_kw,1)) else 'لا يوجد' end,\n      'origin','مصر','warranty','خمس سنوات',\n      'net', case when (p_toggles->>'structure')::boolean then round(structure_sell - (structure_sell-structure_cost)*factor) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(structure_sell), 'cost', round(structure_cost))),\n    jsonb_build_object('n',3,'name','الانفرتر','type', v_inv.brand || ' ' || v_inv.power_kw || ' KW',\n      'qty', case when (p_toggles->>'inverter')::boolean then '1' else 'لا يوجد' end,\n      'origin','الصين','warranty','سنتان',\n      'net', case when (p_toggles->>'inverter')::boolean then round(v_inv_list_price) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(v_inv_list_price), 'cost', round(v_inv_cost_basis))),\n    jsonb_build_object('n',4,'name','الكابلات','type','HIS / LEADER / KBE',\n      'qty', case when (p_toggles->>'cables')::boolean then format('يحدد في الموقع - بحد أقصى %s متر', cables_len) else 'لا يوجد' end,\n      'origin','ألمانيا / الصين','warranty','سنة واحدة',\n      'net', case when (p_toggles->>'cables')::boolean then round(cables_sell - r_cables) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(cables_sell), 'cost', round(cables_cost))),\n    jsonb_build_object('n',5,'name','التأريض / بئر أرضي','type','-',\n      'qty', case when (p_toggles->>'earth')::boolean then 'يحدد في الموقع' else 'لا يوجد' end,\n      'origin','مصر','warranty','----',\n      'net', case when (p_toggles->>'earth')::boolean then round(earth_sell - r_earth) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(earth_sell), 'cost', round(earth_cost))),\n    jsonb_build_object('n',6,'name','الريأكتور (VFD Reactor)','type', reactor_model || ' A',\n      'qty', case when (p_toggles->>'reactor')::boolean then '1' else 'لا يوجد' end,\n      'origin','مصر','warranty','سنة واحدة',\n      'net', case when (p_toggles->>'reactor')::boolean then round(reactor_sell - r_reactor) else 0 end,\n      'cost_note', jsonb_build_object('sell', round(reactor_sell), 'cost', round(reactor_cost))),\n    jsonb_build_object('n',7,'name','التوريد والنقل والتركيب وعمالة ولوحة الحماية IP65 والاكسسوارات والمواسير','type', format('Combiner %s: %s', v_comb_capacity, v_comb.brand),\n      'qty', format('%s KW', round(calc_kw)),\n      'origin','مصر / الصين','warranty','----',\n      'net', round(install_lump_sell - r_install),\n      'cost_note', jsonb_build_object(\n        'sell', round(install_lump_sell), 'cost', round(install_lump_cost),\n        'breakdown', jsonb_build_object(\n          'combiner', round(v_comb_list_price), 'mc4', round(mc4_sell), 'ip65', round(ip65_sell),\n          'install_mech', round(mech_install_cost), 'install_elec', round(elec_install_cost),\n          'transport', round(transport_cost), 'concrete', round(concrete_cost * (1+s.concrete_markup_pct/100.0))\n        )))\n  );\n\n  select coalesce(sum((r->>'net')::numeric),0) into sell_total from jsonb_array_elements(rows) r;\n  final_total := sell_total;\n\n  return jsonb_build_object(\n    'panels_per_string', panels_per_string, 'arrays', arrays, 'total_panels', total_panels,\n    'calc_kw', round(calc_kw,1), 'efficiency_ratio', round(efficiency_ratio,3),\n    'vimp', round(v_vimp,1), 'voc', round(v_voc,1), 'iimp', round(v_iimp,1), 'isc', round(v_isc,1), 'isc_calc', round(v_isc_calc,1),\n    'inverter_brand', v_inv.brand, 'inverter_kw', v_inv.power_kw, 'inverter_oversize_warning', inverter_oversize_warning,\n    'reactor_model', reactor_model, 'cb_size', cb_size, 'combiner_capacity', v_comb_capacity,\n    'rows', rows, 'final_total', round(final_total),\n    'payment_terms', jsonb_build_array(\n      jsonb_build_object('label','مقدم عند التعاقد','pct',70,'amount', round(final_total*0.70)),\n      jsonb_build_object('label','عند التوريد','pct',25,'amount', round(final_total*0.25)),\n      jsonb_build_object('label','عند التشغيل','pct',5,'amount', round(final_total*0.05))\n    )\n  );\nend;\n$function$;\n"}	fix_pricing_semantics_and_source_combiner_from_products	alhussieni95@gmail.com	\N	\N
20260819070432	{"\n-- حاسبة الري بقت مقصورة على الموتور والطلمبة والمواسير بس — الإنفرتر بقى جزء\n-- من عرض سعر \\"تشغيل منظومة الري بالطاقة الشمسية\\" المنفصل\ncreate or replace function public.rep_create_irrigation_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,\n  p_items jsonb,\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_supplier_discount_pct numeric;\n  v_qty numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true\n          and p.category in ('well_motors','pumps','pipes');\n      if v_prod.id is null then\n        raise exception 'product not found, not published, or not a well category: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key for irrigation quote: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer\n      );\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$$;\n"}	split_well_and_solar_pump_quotes	alhussieni95@gmail.com	\N	\N
20260819184728	{"\n-- مقاسات الريأكتور وقاطع الحماية بيانات صناعية من الداتا شيت — مش هتتحسب بمعادلة،\n-- الأدمن هو اللي يدخلها لكل موديل إنفرتر كبير (خاصة إنفرترات الري الصناعية).\nalter table public.products add column if not exists reactor_rating_a numeric;\nalter table public.products add column if not exists breaker_rating_a numeric;\n"}	inverter_reactor_breaker_ratings	alhussieni95@gmail.com	\N	\N
20260819184921	{"\nalter table public.offgrid_bom_settings\n  add column if not exists combiner_box_customer_fixed numeric not null default 3500,\n  add column if not exists mc4_customer_per_pair numeric not null default 45,\n  add column if not exists concrete_customer_fixed numeric not null default 0,\n  add column if not exists field_works_customer_fixed numeric not null default 0,\n  add column if not exists electrical_install_customer_fixed numeric not null default 0;\n\nalter table public.offgrid_bom_cost_settings\n  add column if not exists combiner_box_cost_fixed numeric not null default 3500,\n  add column if not exists mc4_cost_per_pair numeric not null default 45,\n  add column if not exists concrete_cost_fixed numeric not null default 0,\n  add column if not exists field_works_cost_fixed numeric not null default 0,\n  add column if not exists electrical_install_cost_fixed numeric not null default 0;\n\ncreate or replace function public.rep_create_offgrid_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_quote_type text,\n  p_items jsonb,\n  p_notes text default null\n)\nreturns bigint\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_supplier_discount_pct numeric;\n  v_qty numeric;\n  v_watt numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer,\n        'warranty', v_item->>'warranty'\n      );\n\n    elsif v_item->>'type' = 'panel' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'panel product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_watt := coalesce((v_item->>'watt')::numeric, 0);\n      if v_watt <= 0 then\n        raise exception 'invalid panel watt';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0) * v_watt;\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer,\n        'warranty', v_item->>'warranty'\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'steel' then v_bom.steel_customer_per_unit\n        when 'cables' then v_bom.cables_customer_per_meter\n        when 'accessories' then v_bom.accessories_customer_fixed\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        when 'combiner_box' then v_bom.combiner_box_customer_fixed\n        when 'mc4' then v_bom.mc4_customer_per_pair\n        when 'concrete' then v_bom.concrete_customer_fixed\n        when 'field_works' then v_bom.field_works_customer_fixed\n        when 'electrical_install' then v_bom.electrical_install_customer_fixed\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'steel' then v_bom_cost.steel_cost_per_unit\n        when 'cables' then v_bom_cost.cables_cost_per_meter\n        when 'accessories' then v_bom_cost.accessories_cost_fixed\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        when 'combiner_box' then v_bom_cost.combiner_box_cost_fixed\n        when 'mc4' then v_bom_cost.mc4_cost_per_pair\n        when 'concrete' then v_bom_cost.concrete_cost_fixed\n        when 'field_works' then v_bom_cost.field_works_cost_fixed\n        when 'electrical_install' then v_bom_cost.electrical_install_cost_fixed\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer,\n        'warranty', v_item->>'warranty'\n      );\n\n    elsif v_item->>'type' = 'info_only' then\n      -- بند معلوماتي بس (زي التأريض/الريأكتور) — يظهر في العرض بدون سعر أو كمية\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', v_item->>'label', 'qty', null, 'unit_price', 0,\n        'discount_pct', 0, 'line_total', 0, 'warranty', v_item->>'warranty', 'info_only', true\n      );\n      continue;\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$$;\n"}	irrigation_solar_full_bom_settings	alhussieni95@gmail.com	\N	\N
20260819185621	{"-- Allow website cart submissions to exist before a rep has been\n-- assigned (rep_id stays NULL until a rep/admin picks it up — they\n-- already see these via the existing is_admin() RLS bypass in\n-- rep-quotes.html's \\"my quotes\\" list, and via the SELECT policy any\n-- rep can be assigned to it manually later).\nALTER TABLE public.quotes ALTER COLUMN rep_id DROP NOT NULL;\n\n-- Public, unauthenticated RPC for the customer-facing cart on the main\n-- site. Mirrors rep_create_quote()'s server-side price computation\n-- (never trusts client-submitted prices) but:\n--   - does not require is_rep()/is_admin()\n--   - does NOT apply supplier_discount_pct (that's an internal wholesale\n--     cost lever for reps; customers should see the same retail price\n--     already shown on the site)\n--   - always quote_type = 'supply_only', installation_cost = 0 (that\n--     gets discussed once a rep actually contacts the customer)\n--   - tags the customer with lead_source = 'website_cart' so it's\n--     distinguishable from rep-originated leads\nCREATE OR REPLACE FUNCTION public.customer_submit_cart_quote(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_items jsonb,\n  p_notes text DEFAULT NULL\n)\nRETURNS bigint\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\ndeclare\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_product record;\n  v_unit_price numeric;\n  v_qty numeric;\n  v_computed_items jsonb := '[]'::jsonb;\n  v_subtotal numeric := 0;\nbegin\n  if p_customer_name is null or length(trim(p_customer_name)) < 2 then\n    raise exception 'invalid name';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    if v_qty <= 0 then\n      raise exception 'invalid quantity';\n    end if;\n\n    select id, name_ar, name_en, category, brand, price\n      into v_product\n      from public.products\n      where id = (v_item->>'product_id')::uuid;\n\n    if v_product.id is null then\n      raise exception 'product not found: %', v_item->>'product_id';\n    end if;\n\n    v_unit_price := round(coalesce(v_product.price, 0), 2);\n\n    v_computed_items := v_computed_items || jsonb_build_object(\n      'product_id', v_product.id,\n      'name', coalesce(v_product.name_ar, v_product.name_en),\n      'category', v_product.category,\n      'brand', v_product.brand,\n      'unit_price', v_unit_price,\n      'qty', v_qty,\n      'line_total', v_unit_price * v_qty\n    );\n\n    v_subtotal := v_subtotal + (v_unit_price * v_qty);\n  end loop;\n\n  if jsonb_array_length(v_computed_items) = 0 then\n    raise exception 'cart is empty';\n  end if;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (trim(p_customer_name), trim(p_customer_phone), nullif(trim(coalesce(p_customer_city, '')), ''), null, 'website_cart')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, null, 'supply_only', v_computed_items, v_subtotal, 0, v_subtotal, p_notes)\n  returning id into v_quote_id;\n\n  return v_quote_id;\nend;\n$function$;\n\nGRANT EXECUTE ON FUNCTION public.customer_submit_cart_quote(text, text, text, jsonb, text) TO anon, authenticated;\n"}	allow_customer_cart_quote_submissions	alhussieni95@gmail.com	\N	\N
20260820045427	{"-- Fully standalone table for customer-facing cart/quote-request\n-- submissions. Deliberately independent from quotes/customers/reps\n-- (the QL rep-tools system), which is still under active\n-- development/trial and may be removed.\nCREATE TABLE IF NOT EXISTS public.cart_quote_requests (\n  id bigint generated always as identity primary key,\n  customer_name text NOT NULL,\n  customer_phone text NOT NULL,\n  customer_city text,\n  items jsonb NOT NULL,\n  subtotal numeric NOT NULL,\n  notes text,\n  status text NOT NULL DEFAULT 'new',\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.cart_quote_requests ENABLE ROW LEVEL SECURITY;\n-- No SELECT/UPDATE/DELETE policies for anon/authenticated — writes only\n-- happen through the SECURITY DEFINER function below, and reads happen\n-- via the Supabase dashboard's Table Editor (service role) for now.\n\n-- Public, unauthenticated RPC: computes prices server-side from the\n-- published product data (never trusts client-submitted prices), then\n-- inserts one row capturing the customer's cart + contact details.\nCREATE OR REPLACE FUNCTION public.submit_cart_quote_request(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_items jsonb,\n  p_notes text DEFAULT NULL\n)\nRETURNS bigint\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\ndeclare\n  v_request_id bigint;\n  v_item jsonb;\n  v_product record;\n  v_unit_price numeric;\n  v_qty numeric;\n  v_computed_items jsonb := '[]'::jsonb;\n  v_subtotal numeric := 0;\nbegin\n  if p_customer_name is null or length(trim(p_customer_name)) < 2 then\n    raise exception 'invalid name';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    if v_qty <= 0 then\n      raise exception 'invalid quantity';\n    end if;\n\n    select id, name_ar, name_en, category, brand, price\n      into v_product\n      from public.products\n      where id = (v_item->>'product_id')::uuid;\n\n    if v_product.id is null then\n      raise exception 'product not found: %', v_item->>'product_id';\n    end if;\n\n    v_unit_price := round(coalesce(v_product.price, 0), 2);\n\n    v_computed_items := v_computed_items || jsonb_build_object(\n      'product_id', v_product.id,\n      'name', coalesce(v_product.name_ar, v_product.name_en),\n      'category', v_product.category,\n      'brand', v_product.brand,\n      'unit_price', v_unit_price,\n      'qty', v_qty,\n      'line_total', v_unit_price * v_qty\n    );\n\n    v_subtotal := v_subtotal + (v_unit_price * v_qty);\n  end loop;\n\n  if jsonb_array_length(v_computed_items) = 0 then\n    raise exception 'cart is empty';\n  end if;\n\n  insert into public.cart_quote_requests (customer_name, customer_phone, customer_city, items, subtotal, notes)\n  values (trim(p_customer_name), trim(p_customer_phone), nullif(trim(coalesce(p_customer_city, '')), ''), v_computed_items, v_subtotal, p_notes)\n  returning id into v_request_id;\n\n  return v_request_id;\nend;\n$function$;\n\nGRANT EXECUTE ON FUNCTION public.submit_cart_quote_request(text, text, text, jsonb, text) TO anon, authenticated;\n"}	create_standalone_cart_quote_requests	alhussieni95@gmail.com	\N	\N
20260821095716	{"-- Panels are priced per watt (price = EGP/W), not per unit. The actual\n-- price of one panel = price * power_watt. Every other category's price\n-- is already a flat per-unit price. Fix the server-side quote\n-- calculation so submitted totals are correct.\nCREATE OR REPLACE FUNCTION public.submit_cart_quote_request(\n  p_customer_name text,\n  p_customer_phone text,\n  p_customer_city text,\n  p_items jsonb,\n  p_notes text DEFAULT NULL\n)\nRETURNS bigint\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\ndeclare\n  v_request_id bigint;\n  v_item jsonb;\n  v_product record;\n  v_unit_price numeric;\n  v_qty numeric;\n  v_computed_items jsonb := '[]'::jsonb;\n  v_subtotal numeric := 0;\nbegin\n  if p_customer_name is null or length(trim(p_customer_name)) < 2 then\n    raise exception 'invalid name';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    if v_qty <= 0 then\n      raise exception 'invalid quantity';\n    end if;\n\n    select id, name_ar, name_en, category, brand, price, power_watt\n      into v_product\n      from public.products\n      where id = (v_item->>'product_id')::uuid;\n\n    if v_product.id is null then\n      raise exception 'product not found: %', v_item->>'product_id';\n    end if;\n\n    -- Panels: price column is EGP-per-watt, not a flat unit price.\n    -- Everything else: price is already the flat per-unit price.\n    if v_product.category = 'panels' and v_product.power_watt is not null then\n      v_unit_price := round(coalesce(v_product.price, 0) * v_product.power_watt::numeric, 2);\n    else\n      v_unit_price := round(coalesce(v_product.price, 0), 2);\n    end if;\n\n    v_computed_items := v_computed_items || jsonb_build_object(\n      'product_id', v_product.id,\n      'name', coalesce(v_product.name_ar, v_product.name_en),\n      'category', v_product.category,\n      'brand', v_product.brand,\n      'unit_price', v_unit_price,\n      'qty', v_qty,\n      'line_total', v_unit_price * v_qty\n    );\n\n    v_subtotal := v_subtotal + (v_unit_price * v_qty);\n  end loop;\n\n  if jsonb_array_length(v_computed_items) = 0 then\n    raise exception 'cart is empty';\n  end if;\n\n  insert into public.cart_quote_requests (customer_name, customer_phone, customer_city, items, subtotal, notes)\n  values (trim(p_customer_name), trim(p_customer_phone), nullif(trim(coalesce(p_customer_city, '')), ''), v_computed_items, v_subtotal, p_notes)\n  returning id into v_request_id;\n\n  return v_request_id;\nend;\n$function$;\n"}	fix_panel_price_per_watt_calculation	alhussieni95@gmail.com	\N	\N
20260831202540	{"alter table public.supplier_discounts\n  add column sale_discount_pct numeric not null default 0;\n\nalter table public.supplier_discounts\n  add constraint supplier_discounts_sale_discount_pct_check\n  check (sale_discount_pct >= 0 and sale_discount_pct <= 100);\n\nalter table public.supplier_discounts\n  add constraint supplier_discounts_sale_le_supplier_check\n  check (sale_discount_pct <= supplier_discount_pct);\n\ncomment on column public.supplier_discounts.sale_discount_pct is\n  'نسبة الخصم اللي بيتباع بيها للعميل (خصم بيع)، لازم تكون <= supplier_discount_pct عشان الشركة متبيعش بخسارة.';"}	add_sale_discount_to_supplier_discounts	alhussieni95@gmail.com	\N	\N
20260903193927	{"create table if not exists public.promotional_discounts (\n  id                  uuid primary key default gen_random_uuid(),\n  category            text not null,\n  brand               text not null,\n  name                text,\n  promo_discount_pct  numeric(5,2) not null default 0,\n  is_active           boolean not null default false,\n  start_date          date,\n  end_date            date,\n  created_at          timestamptz not null default now(),\n  updated_at          timestamptz not null default now(),\n  unique (category, brand)\n);\n\nalter table public.promotional_discounts enable row level security;\n\ndrop policy if exists \\"promo_discounts_public_read\\" on public.promotional_discounts;\ncreate policy \\"promo_discounts_public_read\\" on public.promotional_discounts\n  for select using (is_active = true);\n\ndrop policy if exists \\"promo_discounts_admin_write\\" on public.promotional_discounts;\ncreate policy \\"promo_discounts_admin_write\\" on public.promotional_discounts\n  for all using (public.is_admin());\n"}	create_promotional_discounts	alhussieni95@gmail.com	\N	\N
20260904090052	{"create table if not exists public.roi_settings (\n  id                        smallint primary key default 1,\n  electricity_price_per_kwh numeric(10,4) not null default 0,\n  diesel_price_per_liter    numeric(10,4) not null default 0,\n  updated_at                timestamptz not null default now(),\n  constraint roi_settings_singleton check (id = 1)\n);\n\ninsert into public.roi_settings (id, electricity_price_per_kwh, diesel_price_per_liter)\nvalues (1, 0, 0)\non conflict (id) do nothing;\n\nalter table public.roi_settings enable row level security;\n\ndrop policy if exists \\"roi_settings_read\\" on public.roi_settings;\ncreate policy \\"roi_settings_read\\" on public.roi_settings\n  for select using (is_rep() or is_admin());\n\ndrop policy if exists \\"roi_settings_admin_write\\" on public.roi_settings;\ncreate policy \\"roi_settings_admin_write\\" on public.roi_settings\n  for update using (is_admin());\n"}	create_roi_settings	alhussieni95@gmail.com	\N	\N
20260904112607	{"create table if not exists public.feasibility_studies (\n  id                        bigint generated always as identity primary key,\n  quote_id                  bigint references public.quotes(id) on delete set null,\n  rep_id                    uuid not null references public.reps(id),\n  customer_name             text,\n  customer_phone            text,\n  system_label              text,\n  capex                     numeric not null default 0,\n  system_kw                 numeric not null default 0,\n  psh                       numeric not null default 5.5,\n  degradation_pct           numeric not null default 0.65,\n  electricity_price         numeric not null default 0,\n  electricity_escalation_pct numeric not null default 8,\n  diesel_price              numeric not null default 0,\n  diesel_escalation_pct     numeric not null default 8,\n  generator_kwh_per_liter   numeric not null default 3.5,\n  annual_maintenance_pct    numeric not null default 1,\n  created_at                timestamptz not null default now(),\n  updated_at                timestamptz not null default now()\n);\n\nalter table public.feasibility_studies enable row level security;\n\ndrop policy if exists \\"feasibility_studies_select\\" on public.feasibility_studies;\ncreate policy \\"feasibility_studies_select\\" on public.feasibility_studies\n  for select using (is_admin() or (is_rep() and rep_id = auth.uid()));\n\ndrop policy if exists \\"feasibility_studies_insert\\" on public.feasibility_studies;\ncreate policy \\"feasibility_studies_insert\\" on public.feasibility_studies\n  for insert with check (is_rep() and rep_id = auth.uid());\n\ndrop policy if exists \\"feasibility_studies_update\\" on public.feasibility_studies;\ncreate policy \\"feasibility_studies_update\\" on public.feasibility_studies\n  for update using (is_admin() or (is_rep() and rep_id = auth.uid()));\n\ndrop policy if exists \\"feasibility_studies_delete\\" on public.feasibility_studies;\ncreate policy \\"feasibility_studies_delete\\" on public.feasibility_studies\n  for delete using (is_admin() or (is_rep() and rep_id = auth.uid()));\n"}	create_feasibility_studies	alhussieni95@gmail.com	\N	\N
20260906093454	{"CREATE OR REPLACE FUNCTION public.rep_create_offgrid_quote(p_customer_name text, p_customer_phone text, p_customer_city text, p_quote_type text, p_items jsonb, p_notes text DEFAULT NULL::text)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_rep_id uuid := auth.uid();\n  v_customer_id bigint;\n  v_quote_id bigint;\n  v_item jsonb;\n  v_result_items jsonb := '[]'::jsonb;\n  v_subtotal_customer numeric := 0;\n  v_subtotal_cost numeric := 0;\n  v_discount_pct numeric;\n  v_supplier_discount_pct numeric;\n  v_qty numeric;\n  v_watt numeric;\n  v_customer_unit numeric;\n  v_cost_unit numeric;\n  v_line_customer numeric;\n  v_line_cost numeric;\n  v_prod record;\n  v_bom record;\n  v_bom_cost record;\nbegin\n  if not (is_rep() or is_admin()) then\n    raise exception 'not authorized';\n  end if;\n  if p_quote_type not in ('supply_only','supply_install') then\n    raise exception 'invalid quote_type';\n  end if;\n  if p_customer_phone is null or length(trim(p_customer_phone)) < 8 then\n    raise exception 'invalid phone';\n  end if;\n\n  select * into v_bom from public.offgrid_bom_settings where id = 1;\n  select * into v_bom_cost from public.offgrid_bom_cost_settings where id = 1;\n\n  for v_item in select * from jsonb_array_elements(p_items)\n  loop\n    v_qty := coalesce((v_item->>'qty')::numeric, 0);\n    v_discount_pct := greatest(0, least(100, coalesce((v_item->>'discount_pct')::numeric, 0)));\n    if v_qty <= 0 then\n      continue;\n    end if;\n\n    if v_item->>'type' = 'product' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0);\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer,\n        'warranty', v_item->>'warranty'\n      );\n\n    elsif v_item->>'type' = 'panel' then\n      select p.id, p.name_ar, p.price, p.category, p.brand into v_prod\n        from public.products p\n        where p.id = (v_item->>'product_id')::uuid and p.published = true;\n      if v_prod.id is null then\n        raise exception 'panel product not found or not published: %', v_item->>'product_id';\n      end if;\n      v_watt := coalesce((v_item->>'watt')::numeric, 0);\n      if v_watt <= 0 then\n        raise exception 'invalid panel watt';\n      end if;\n      v_customer_unit := coalesce(v_prod.price, 0) * v_watt;\n      select supplier_discount_pct into v_supplier_discount_pct\n        from public.supplier_discounts where category = v_prod.category and brand = v_prod.brand;\n      v_cost_unit := v_customer_unit * (1 - coalesce(v_supplier_discount_pct, 0) / 100.0);\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_prod.name_ar),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer,\n        'warranty', v_item->>'warranty'\n      );\n\n    elsif v_item->>'type' = 'bom_fixed' then\n      v_customer_unit := case v_item->>'key'\n        when 'steel' then v_bom.steel_customer_per_unit\n        when 'cables' then v_bom.cables_customer_per_meter\n        when 'accessories' then v_bom.accessories_customer_fixed\n        when 'transport' then v_bom.transport_customer_fixed\n        when 'install' then v_bom.install_customer_per_unit\n        when 'combiner_box' then v_bom.combiner_box_customer_fixed\n        when 'mc4' then v_bom.mc4_customer_per_pair\n        when 'concrete' then v_bom.concrete_customer_fixed\n        when 'field_works' then v_bom.field_works_customer_fixed\n        when 'electrical_install' then v_bom.electrical_install_customer_fixed\n        else null end;\n      v_cost_unit := case v_item->>'key'\n        when 'steel' then v_bom_cost.steel_cost_per_unit\n        when 'cables' then v_bom_cost.cables_cost_per_meter\n        when 'accessories' then v_bom_cost.accessories_cost_fixed\n        when 'transport' then v_bom_cost.transport_cost_fixed\n        when 'install' then v_bom_cost.install_cost_per_unit\n        when 'combiner_box' then v_bom_cost.combiner_box_cost_fixed\n        when 'mc4' then v_bom_cost.mc4_cost_per_pair\n        when 'concrete' then v_bom_cost.concrete_cost_fixed\n        when 'field_works' then v_bom_cost.field_works_cost_fixed\n        when 'electrical_install' then v_bom_cost.electrical_install_cost_fixed\n        else null end;\n      if v_customer_unit is null then\n        raise exception 'unknown bom_fixed key: %', v_item->>'key';\n      end if;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', v_item->>'key'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer,\n        'warranty', v_item->>'warranty'\n      );\n\n    elsif v_item->>'type' = 'custom' then\n      -- بند يدوي بيدخله المندوب بنفسه (لوح إضافي/كابل زيادة/أي حاجة لظروف\n      -- الموقع) — مفيش مرجع كتالوج نتحقق منه، فبنثق في السعر اللي كتبه\n      -- المندوب زي ما هو. التكلفة الداخلية = نفس سعر البيع (مش أقل)، عشان\n      -- تقرير الربح متفترضش هامش ربح وهمي على بند مالوش تكلفة موردين حقيقية.\n      v_customer_unit := coalesce((v_item->>'unit_price')::numeric, 0);\n      v_cost_unit := v_customer_unit;\n\n      v_line_customer := v_qty * v_customer_unit * (1 - v_discount_pct / 100.0);\n      v_line_cost := v_qty * v_cost_unit;\n\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', coalesce(v_item->>'label', 'بند يدوي'),\n        'qty', v_qty, 'unit_price', v_customer_unit,\n        'discount_pct', v_discount_pct, 'line_total', v_line_customer,\n        'warranty', v_item->>'warranty'\n      );\n\n    elsif v_item->>'type' = 'info_only' then\n      -- بند معلوماتي بس (زي التأريض/الريأكتور) — يظهر في العرض بدون سعر أو كمية\n      v_result_items := v_result_items || jsonb_build_object(\n        'label', v_item->>'label', 'qty', null, 'unit_price', 0,\n        'discount_pct', 0, 'line_total', 0, 'warranty', v_item->>'warranty', 'info_only', true\n      );\n      continue;\n    else\n      raise exception 'unknown item type: %', v_item->>'type';\n    end if;\n\n    v_subtotal_customer := v_subtotal_customer + v_line_customer;\n    v_subtotal_cost := v_subtotal_cost + v_line_cost;\n  end loop;\n\n  insert into public.customers (name, phone, city, assigned_rep_id, lead_source)\n  values (p_customer_name, p_customer_phone, p_customer_city, v_rep_id, 'rep_quote')\n  on conflict (phone) do update\n    set name = excluded.name,\n        city = coalesce(excluded.city, public.customers.city),\n        updated_at = now()\n  returning id into v_customer_id;\n\n  insert into public.quotes (customer_id, rep_id, quote_type, items, subtotal, installation_cost, total, notes)\n  values (v_customer_id, v_rep_id, p_quote_type, v_result_items, v_subtotal_customer, 0, v_subtotal_customer, p_notes)\n  returning id into v_quote_id;\n\n  insert into public.quote_costs (quote_id, total_cost, profit)\n  values (v_quote_id, v_subtotal_cost, v_subtotal_customer - v_subtotal_cost);\n\n  return v_quote_id;\nend;\n$function$\n"}	add_custom_item_type_to_rep_offgrid_quote	alhussieni95@gmail.com	\N	\N
20260916095430	{"create table public.quote_drafts (\n  rep_id uuid primary key references public.reps(id) on delete cascade,\n  customer_name text,\n  customer_phone text,\n  quote_type text,\n  items jsonb not null default '[]'::jsonb,\n  subtotal numeric not null default 0,\n  installation_cost numeric not null default 0,\n  total numeric not null default 0,\n  page text,\n  last_active_at timestamptz not null default now()\n);\n\nalter table public.quote_drafts enable row level security;\n\ncreate policy \\"Admins see all drafts\\" on public.quote_drafts\n  for select using (is_admin());\n\ncreate policy \\"Reps see own draft\\" on public.quote_drafts\n  for select using (is_rep() and rep_id = auth.uid());\n\ncreate or replace function public.rep_upsert_quote_draft(\n  p_customer_name text, p_customer_phone text, p_quote_type text,\n  p_items jsonb, p_subtotal numeric, p_installation_cost numeric,\n  p_total numeric, p_page text\n) returns void\nlanguage plpgsql security definer set search_path to 'public'\nas $$\nbegin\n  if not is_rep() then raise exception 'not authorized'; end if;\n  insert into quote_drafts (rep_id, customer_name, customer_phone, quote_type, items, subtotal, installation_cost, total, page, last_active_at)\n  values (auth.uid(), p_customer_name, p_customer_phone, p_quote_type, p_items, p_subtotal, p_installation_cost, p_total, p_page, now())\n  on conflict (rep_id) do update set\n    customer_name = excluded.customer_name, customer_phone = excluded.customer_phone,\n    quote_type = excluded.quote_type, items = excluded.items, subtotal = excluded.subtotal,\n    installation_cost = excluded.installation_cost, total = excluded.total,\n    page = excluded.page, last_active_at = now();\nend;\n$$;\n\ncreate or replace function public.rep_clear_quote_draft() returns void\nlanguage plpgsql security definer set search_path to 'public'\nas $$\nbegin\n  delete from quote_drafts where rep_id = auth.uid();\nend;\n$$;\n\ngrant execute on function public.rep_upsert_quote_draft(text, text, text, jsonb, numeric, numeric, numeric, text) to authenticated;\ngrant execute on function public.rep_clear_quote_draft() to authenticated;\n"}	create_quote_drafts	alhussieni95@gmail.com	\N	\N
